/* 令和元年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r01.committeeSessions.push(...[{"id":"r01-20190318-3","meetingId":"r01-c-budget","date":"2019年3月18日","dateIso":"2019-03-18","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時１２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を125件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"質問の第１点目は、防災対策の強化についてです。我が会派は長年、ブロック塀の危惧、または大谷石も万年塀も危険な崖や塀などの点検をして対応してくださいと長年要望を続けてまいりました。そこで質問いたします。そこには子どもが遊ぶ場合もありますので、行政の線引きは道路境界線というのは十分理解できるのですが、命を守る視点というところではいかがでしょうか。教えてください。","respondent":"中村都市環境部長","answer":"コンクリートブロック塀等安全化支援における隣地境界線という考え方ですけれども、ブロック塀の安全化支援につきましては、制度の実施にあたりまして、支援の対象や方法について、さまざまな検討を行ってまいりました。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"先ほども申し上げましたが、隣地境界線、行政が取組むことですから、どこかで線引きをしなければならないのは十分理解できますが、今後の課題としまして、公共性の高いというところでは、安全面、命を守る視点でも考えていっていただきたいと思います。次の質問に移ります。品川区の防災協定は、昭和５１年８月に医師会との締結をはじめ、今日までありとあらゆる方面、分野において締結をされています。","respondent":"曽田災害対策担当部長","answer":"その後、熊本地震など最近の地震におけるさまざまな教訓から、避難所における段ボールベッドや簡易間仕切りの提供、あるいは災害時の物資提供、行政書士会による生活再建支援、あるいはドローンによる情報収集支援など、新たなニーズに基づく協定締結を進めておりまして。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問","question":"本当に防災協定はさまざまなことを想定して対応していただければと思います。皆様の不安払拭に向けた取組みを引き続きお願いいたします。この実務、そして準備、訓練などについてお聞かせください。そして、例を挙げます。防災時、災害時にドローンを活用するということで、そのいざというときに万全を期すために、日ごろより別の用途での使い方が必要ではないかという質問です。お願いいたします。","respondent":"曽田災害対策担当部長","answer":"いずれにしましても、委員のご提案を参考に、平素の活用を含めたドローンの運用について検討していきたいと考えております。","id":"exchange-003"},{"speaker":"本多委員","kind":"質問","question":"所管や持ち場があります。有事の際の活用に大いに役立てていただければと思います。次の質問です。全ての体育館、全ての避難所に空調機の設置が３カ年計画で実施されます。ありがたいことです。現在、町会の数は２０１です。町会会館所有の数は８１です。町会会館前などの外部がいいかと思いますが、町会会館前に公衆電話の増設の働きかけについてはいかがでしょうか。お聞かせください。","respondent":"中山企画部長、曽田災害対策担当部長","answer":"ご質問の前半の区政と複数年計画との関係についてお答えいたしますけれども、まず、現行の１０年スパンの長期基本計画を３カ年の総合実施計画で具体的にスケジュール化し、財政収支も想定して各年度の予算を編成しているです。このため、区といたしましては、避難所運営訓練における特設公衆電話の設置訓練や公衆電話の設置場所や利用方法の周知など、そういったことを進めていきたいと考えています。","id":"exchange-004"},{"speaker":"本多委員","kind":"提案","question":"電話につきましては、品川区は働きかける立場ですから、先方の考え方はわかりましたけれども、本当に有効なものですので、この辺は現状あるものを有効活用するのは当然ですが、さらに一工夫必要かなと考えています。質問の２点目に移ります。款別審査で渡辺委員より、高齢者に対するネーミングで、シルバー、老人、高齢者クラブなど、品川区としてできる配慮をとの提案がされました。よい提案だと思います。","respondent":"永尾福祉部長","answer":"認定を受けていない方の数も含めますと、さらに多くなるということが推定されております。平成３１年１月末現在では、区で把握している認知症の人数は１万２,１１５人で、高齢者人口増に伴い、今後、増加が見込まれます。","id":"exchange-005"},{"speaker":"本多委員","kind":"質問・要望","question":"ありがとうございました。現状を鑑みまして、対応できることをするべきだと考えます。款別審査であくつ委員が取り上げました保険について、同趣旨で質問します。神奈川県大和市が、平成２９年１１月より、全国自治体初の「はいかい高齢者個人賠償責任保険事業」を開始しました。被保険者の自己負担なし。１５年がたちました。それらの状況や見通しなど、どう情報収集をされているのかお聞かせください。","respondent":"永尾福祉部長、福内健康推進部長","answer":"今後、他の自治体の実施状況を参考に、保険内容や対象者などを検討し、区が進めているこれらの事業について、組み合わせて相乗効果が得られるような形になるよう導入を考えてまいります。アルツハイマー型認知症の治療薬といたしまして、日本でもエーザイの候補薬が治験を開始いたしまして、早期の承認を目指しておりますけれども、治験終了までまだ時間がかかる見込みであるというふうに聞いております。","id":"exchange-006"},{"speaker":"本多委員","kind":"質問","question":"保険の導入については、前向きに考えていただいているということでお願いしたいと思います。次の質問に移ります。平成は、あと４３日間となりました。世界中を見ましても、類まれ、歴史と伝統を持つ日本の天皇、そして建国以来２,０００年以上の歴史を持つ美しい伝統文化、日本の祝日の意義、２月３日は節分など、それぞれの点、誰がどう伝えていくべきか、家庭や地域社会も意識を持つべきだと思います。","respondent":"榎本総務部長","answer":"こうして以前いただいた善意に対しては、忘れずに後世に伝えていくということの大切さの視点として捉えておりまして、正確な事実や認識を伝える取組みを区としても行ってまいりたいと思います。","id":"exchange-007"},{"speaker":"本多委員","kind":"確認","question":"後世に残し伝えたい取組みを映画などでの活用はいかがでしょうか。先日、地域の歴史１００年間について、そして１００年後について意見交換を地域で行う機会がありました。技術がどんどん進むにつれ、安心をしているところ、専門家は、今までの１００年、物が保存よく残っていたけれども、これからの１００年のほうが心配だと発言をされていましたが、その辺についての確認をさせてください。","respondent":"安藤文化スポーツ振興部長、中山企画部長","answer":"委員ご提案の映画などでの活用や後世に残す取組みですけれども、例えば伝統行事や町の姿を記録としてドキュメンタリー化とするなどの考えがありますので、今後、関係所管とも連携して研究を進めてまいります。ただ一方では、デジタル媒体の磁気劣化といった懸念も言われていますので、今後も時代に即した資料保存技術を研究、情報収集しながら、区政等の貴重な記録をしっかりと大切に保存していくように心がけていきたいと考えております。","id":"exchange-008"},{"speaker":"本多委員","kind":"質問・要望","question":"質問を続けます。１つ１つの課題を的確に捉えた取組みと感じます。人工知能の時代が到来、どのように時代が変わっても、人の郷土愛、マンパワー、人材活用の総合的なバランスが求められる点について、または観光大使への人材活用、あるいはふるさと納税流出抑制、流入促進に向けたイメージキャラクターへの人材活用、それぞれについてお聞かせください。そして最後の質問です。１、国家の絆。２、地域社会。","respondent":"安藤文化スポーツ振興部長、中山企画部長","answer":"それぞれの事業ごとにふさわしい人選も重要であることから、観光大使にふさわしい方がおりましたら、任命に向けて検討させていただきたいと考えています。５つの絆ですけれども、安全で安心な暮らしを維持していくために、さまざまな国レベル、そして地域コミュニティ、そして家族、そういったものを品川区の財産を生かしながら、また家庭でのつながり。","id":"exchange-009"},{"speaker":"本多委員","kind":"質問・要望","question":"人材活用につきましては、これまでの取組みとあわせて、地方自治体ですから、人を起用するときには、やはり縁やゆかりを考えて登用するのかもしれませんが、品川に縁がない方でも、半年とか１年間とか、短期間での登用はいいのかなと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"伊藤委員","kind":"質問","question":"初めに、防災対策について質問をします。東日本大震災から８年がたちますけれども、いまだに行方不明者がいまして、これに伴う震災関連死が２万１,０００人、未曾有の被害となりました。さて、防災となると、品川区の予算は６４件ありました。さらに前進してほしいと思っているわけです。世帯数は約２２万世帯。それから、ホームページやＳＮＳ等を活用した防災意識の向上施策等について教えてください。","respondent":"曽田災害対策担当部長","answer":"今後もさまざまな新たな手法を取り入れるなど、いろいろな方法でＳＮＳを活用いたしまして、防災意識が向上するよう努めていきたいと考えております。","id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問","question":"個人的なことで恐縮ですが、私のふるさとが東日本大震災で被災しました。私の母も震災を経験しました。被災地には何十回もお伺いしました。非常に厳しい現状がありました。それから、保育園や幼稚園、小学校、中学校等での防災教育の展開が必要であります。そういうことをどう展開していくのか。そういうことを自助、共助の部分で展開していくことが必要だと思われますが、品川区のお考えをお聞かせください。","respondent":"福島子ども未来部長、本城教育次長、藤田防災まちづくり部長","answer":"消防署と連携しました子どもたちにわかりやすい防災教育の実施を行っているところです。区立学校におきましては、都の安全教育プログラムを踏まえまして、どのように身を守るかを具体的に考えたり。ワークショップにつきましては、一旦終了しているところではありますが、地域からのご要望等があれば。","id":"exchange-012"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ただ、それがいつどういう瞬間に惹起するかは誰も想定することはできないわけでありますから、定期的な訓練や定期的な研修は当然必要でありますけれども、それが実際に起こった際に、どういう行動をして、具体的にどう子どもたちや児童の命を守っていくのかということが行政に求められているわけでありますから、私の思いとしては、今の答弁では納得するところはありますけれども、ただ。","respondent":"本城教育次長","answer":"それと同時に、今ご指摘がありましたように、子どもたちが、その場、その場の状況に応じて判断するという基礎的な能力をつけることが、突発的な対応についても基本的なものとしてとても重要であると考えているところです。","id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問","question":"防災対策の一環として、港区でタワーマンション等で備蓄品の備蓄をするように条例化されているわけでありますから、１つ参考にすべきだと思います。例えば４０階の方が歩いて１階まで行って食料の買い出しをすることが当然出てくるわけであります。そういうことを考えていきますと、例えばタワーマンション等での食料、水の備蓄の条例化についても検討すべきと思いますが、いかがでしょうか。","respondent":"曽田災害対策担当部長","answer":"ご提案の条例化につきましては、港区も含めました他区の事例を参考にしながら、マンション等集合住宅の建設時に備蓄倉庫の設置を義務づけるなど、こういったことを検討しまして、備蓄に向けた取組みが進むよう、関係所管とは連携してまいりたいと考えております。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"確認","question":"遠回しに、つまり、条例化はしないということだと思うのですけれども、よく考えてほしいのは、自助をこれから打ち出していくことを確認されたわけであります。もちろん、繰り返しますけれども、行政が税金を使ってさまざまな防災対策をすることは必要であります。例えば、５階、１０階、それぞれの階ごとにマンションの理事会が備蓄をすることは当然やっているわけであります。お願いいたします。","respondent":"曽田災害対策担当部長","answer":"タワーマンションの防災対策につきましては、現在、マンション防災アドバイザー派遣事業を防災課で実施していまして、マンションにそれぞれ出張し、防災訓練や防災対策の指導を行っているところであります。","id":"exchange-015"},{"speaker":"伊藤委員","kind":"提案","question":"改めて、今のことも含めて、「わが家の防災ハンドブック」の改訂版の全戸配布と、今おっしゃったマンションの方々に対するＰＲ、それから企業向け、あわせて外国人の方々、いろいろな方々に共通する認識を持っていただくためには、やはり防災ハンドブック、これは議会からの提案で実現させていただいたわけでありますから、多角的な面で展開していってほしいと思いますが。","respondent":"曽田災害対策担当部長","answer":"今年度、防災ハンドブック、防災地図を作成しておりますけれども、これは全戸配布を今年の５月中旬から予定しております。","id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それぞれよろしくお願いいたします。次に、新たな課題として、震災関連死に関連して質問いたします。そういうことを考えてまいりますと、品川区でもせっかく大震災から助かった命を失うことのないように、カウンセラー、医師、看護師の専門知識を前提に、避難生活をされる方々の悩みや苦しみを抱える避難者個々の精神的支援も具体的に検討すべきと思いますが、いかがでしょうか。","respondent":"福内健康推進部長","answer":"メンタルケアに関しましても、専門医やカウンセラーなどの協力を得まして、巡回精神相談チーム等を編成し、被災者の相談に当たってまいります。区では、こうした取組みにより、助かった命を失うことのないよう、精神的な支援をしっかり行っていきたいと考えております。","id":"exchange-017"},{"speaker":"伊藤委員","kind":"質問","question":"確かにチームが組織されるのでしょうし、人材も来るでしょう。そこに具体的に何人の方が派遣されて、そしてそこでどういう相談を受けて、そしてそれをどのように長期的な観点からケアしていくかということについても、この問題は具体化していかないと、福島県の例で見ると、被災者の方々はなかなか立ち直れなかったという話もたくさん聞くわけでありますから、改めて品川区のお考えをお聞かせください。","respondent":"福内健康推進部長","answer":"それらの専門性等も考慮いたしまして、医療救護本部において、区の医療コーディネーターの助言のもと、適切に振り分けを行い、また、連日、実際の状況について報告を受けながらきめ細かく対応をしていきたいと考えています。","id":"exchange-018"},{"speaker":"伊藤委員","kind":"意見","question":"そうですね。今の答弁は理解できる部分もあるのですけれども、いざ震災が起こって被災をされた方々を目の前にして、どういうケアをしていくのかということについては、これはやはり想定はできないです。そういうことから考えてまいりますと、今の部長の答弁は理解できるところはあるのですけれども、長期的な観点から見てどうなのだということについて、改めてお考えをお聞かせください。","respondent":"福内健康推進部長","answer":"当然、長期的に被災者の方たちに寄り添うことは必要だというふうに考えておりまして、他県から入ってくる保健師たちのチームなどとも協力し、区の職員でしっかり相談等に乗り、支援を行っていきたいと考えています。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"提案","question":"品川区役所のＩＣＴ化推進について質問いたします。行政のＩＣＴ化に関するさまざまな提案をさせていただいて、今年度、品川区の職員のワークスタイルの変更があり、それからフリーアドレス等が具体化されて、私ども自民党の提案が展開されましたことを改めて感謝する次第です。改めて質問ですが、まず、品川区役所のＩＣＴ推進を長期基本計画等で策定すべきと考えますが、いかがでしょうか。","respondent":"中山企画部長","answer":"その辺のレベルについては、またしっかりと策定委員会の議論を踏まえながら進めていきたいと考えているところです。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"確認","question":"将来的なお話でありますけれども、区民所有の端末に、例えばスマートフォンやパソコン等から、品川区への各種申請、登録、選挙の投票、災害時の安否確認等、さまざまな観点からこの技術は活用できるわけでありますから、幅広く検討すべきと思いますが、品川区のお考えをお聞かせください。お願いいたします。","respondent":"中山企画部長","answer":"一元化を図るかどうかということにつきましては、現在のアプリの利用状況の反応を見ながら、それぞれの充実だとか、より一体化させていくかについては、幅広く検討していきたいというふうに考えているものです。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"意見","question":"確かにまだ飛躍的な発展はしてはおりますけれども、セキュリティの面であるとか、それから情報漏洩の部分については、まだまだ検討すべき面があると思われますから、すぐには展開できないとは思います。そして、行政のＩＣＴ化については、当面、技術的な面が確立するまでの間は、あくまで客観的、１つの基準に基づいてデータを判断ができるものだけに留めるべきだと考えています。お願いいたします。","respondent":"中山企画部長","answer":"こういう地域の力もしっかり注視しながら区の中でどう生かしていくか、こういう観点で今後ともＩＣＴ化のさらなる推進を意識しながら進めてまいりたいと考えております。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問","question":"この話はこれから長いこと続けていこうと思っていますけれども、ただ、確かなことは、この世界に進んでいかなければ、行政は取り残されることは確かでありますから、ぜひ推進をよろしくお願いいたします。改めて品川区議会自民党・子ども未来の各委員の質問を的確に把握していただきまして予算に反映していただきますことを心からお願いいたしまして、総括質疑を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"質問・要望","question":"平成の３０年間で、戦争の世紀であった２０世紀から２１世紀を迎えました。質問の１点目は、品川区長期基本計画とＳＤＧｓとの連動について伺います。国際社会、そしてステークホルダーの一員として、ＳＤＧｓに取組む品川区の姿勢を伺います。そして、今後、品川区がＳＤＧｓに取組み、随時目標達成を継承していくためには、担当部署の設置が必要と考えますが、ご見解を伺います。","respondent":"中山企画部長","answer":"このＳＤＧｓに掲げる１７の目標につきましては、環境、教育、保健衛生、まちづくりなど、区の施策に直接かかわる分野も多く、継続的、包括的に施策を進めるべきという考え方は、区政の目指す方向性と合致するものであるというふうに認識しているものです。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問・要望","question":"質問の２点目は、ＳＤＧｓに取組む区内企業への支援について伺います。そこでまず、品川区が率先してＳＤＧｓを推進した上で、区民にこのような区内企業のＳＤＧｓの取組みを紹介していただきたいと思いますが、いかがでしょうか。そして最後に、ＳＤＧｓに熱心に取組む企業や各種団体に、区内でのＳＤＧｓ展開の協力を求めたり、支援を行ってはいかがでしょうか。ご見解を求めます。","respondent":"中山企画部長","answer":"今後ともこういった行動についての支援については、幅広い観点で捉えていきたい、考えていきたいというふうに考えています。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問・要望","question":"質問の１点目は、プラスチックストローの使用見直しについて伺います。そして、プラスチックストローは引き続き使用したい方にも十分な配慮をした上で、区立小中学校の児童保護者から、プラスチックストローを使用しないで、代替の手法で牛乳を飲みたいとの申し出があった場合、教育委員会として全ての学校において柔軟な対応を求める見解を出していただきたいと思いますが、いかがでしょうか。","respondent":"本城教育次長","answer":"児童生徒や保護者から、プラスチックストローの利用を控えたいとの申し出があった場合には、各学校において、現在も柔軟に対応しており、教育委員会としても、学校の判断を尊重する姿勢に変わりはございませんが。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今後、東京都は、学校給食のプラスチックストローにかわる方法を区市町村と連携して検討していくとのことですが、未来を見据えた母の願いである請願を全会一致で採択して、真っ先に声を上げた品川区として、東京都から連携の呼びかけがあった際には、ぜひ真っ先に協力をしていただきたいと思いますが、いかがでしょうか。","respondent":"本城教育次長","answer":"現時点におきましては、まだ都から動きはございませんが、今後、具体的な提案や呼びかけがあった際には、区として対応できるものかどうか精査いたしまして、可能なものについては検討してまいりたいと考えているところです。","id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問・要望","question":"可能なものということにもいろいろな意味があると思いますけれども、ぜひこれはご検討していただきたいと思います。質問の２点目は、学校給食での宗教的な配慮について伺います。款別審査では、このような宗教上の理由から、お弁当を持参している区内の児童生徒は１９名であることを確認しました。宗教上の理由での給食への配慮の要望があった場合、現在、教育委員会では、どのような対応をとっているのか。","respondent":"本城教育次長","answer":"宗教食への対応につきましては、国や都から通知等が出されているわけではございませんが、平成２９年に総務省が、宗教的な配慮を要する外国人の受け入れ環境等の整備に関する調査を行いまして、今後の取組みの参考に調査結果を公表しています。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ありがとうございました。現状と対応について確認をさせていただきました。今後、宗教上の理由での給食の配慮については、多様性を尊重して最大限の対応をとっていただきたいと考えますが、いかがでしょうか。各家庭がどのような思想、信条、宗教をお持ちだとしても、児童・生徒とその保護者がそれゆえに取り残されたと感じないような、学校、教育委員会としての配慮を求めますが、いかがでしょうか。","respondent":"本城教育次長","answer":"異なる文化の理解不足によりまして、当事者が疎外感などを持つことがないように、現在も各学校では十分留意し対応しているところではありますが、教育委員会も含めまして、今後も引き続き力を入れて取組んでまいりたいと考えているところです。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ありがとうございました。最後に、区民の安全安心を守る新たな保険制度について質問します。来年度予算案に区民交通傷害保険が新規計上されました。数年前、区内での自転車と歩行者の衝突事故で尊い命が失われた痛ましい事故について、被害者側からご相談を受けたことがきっかけで、区民のリスク軽減の観点から、議会質問で２年間継続して法制度の実施を求めてまいりましたので、とても期待をしております。","respondent":"藤田防災まちづくり部長","answer":"事業開始の初年度につきましては、約４,０００人の加入を見込んでいるものです。三者の関係についてですが、お一人お一人の申し込みを区が取りまとめて保険者となり、保険会社と契約をする、いわゆる団体保険のようなイメージが一番合うかと思いますが、そのような形のものです。","id":"exchange-030"},{"speaker":"あくつ委員","kind":"意見","question":"先ほどご答弁にあったとおり、裁判で自転車事故の加害者に高額の損害賠償を命じるということが増えており、被害者が泣き寝入りするような現状であって、一番低い保険料としては、年間１,４００円で、このように１億円までの損害賠償をカバーできるという本事業の導入には大きな意義があると考えます。小さなお子さんと保護者が同乗している場合などは人数分保険に加入する必要があるのかどうか。","respondent":"藤田防災まちづくり部長","answer":"加入につきましては、自転車事故では高額な損害賠償の事例もありますので、１人で自転車に乗り始めたお子さん、あるいは、日々、通勤通学で自転車を利用する方、保育園等に子どもを自転車で送り迎えする方などには特に有効であるというふうに考えてあります。","id":"exchange-031"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ケーブルテレビを含め、あらゆる区の広報媒体を活用して、先ほど伺ったような保険制度の概要やメリットを区民にしっかりと周知をしていただきたいと思いますが、いかがでしょうか。本制度によって得た集金事務費の一部を交通安全啓発のために特化した新たな目的に活用していき、それを広報することが加入者を呼び込むことにつながると思いますが、ご所見を伺います。","respondent":"藤田防災まちづくり部長","answer":"警察と連携をいたしました自転車安全利用のキャンペーン等、こうしたイベントでも啓発を進めてまいりたいと考えています。なお、保険を周知する際には、法律に基づきます保険会社の審査が必要となっています。","id":"exchange-032"},{"speaker":"あくつ委員","kind":"質問・要望","question":"非常によい制度を今回品川区が導入されるということですが、区民がこれを知らないということでは宝の持ち腐れになってしまうと思います。あのとき、この保険の存在を知っていればとならないよう、区民への周知を徹底していただければと改めて要望いたします。以上で、私の平成最後の総括質疑を終わります。ご清聴ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"塚本委員","kind":"質問","question":"区議会公明党を代表して、あくつ委員に引き続き、総括質疑を行います。初めに、防災対策について質問します。空き家対策についてです。区内の密集市街地が２０１５年からの３年間で約半減したことについて、区はこれまで実施してきた密集市街地解消施策によってもたらされた効果についてと、その中で空き家の除却実績も伺います。さらなる密集市街地解消に向けた取組みについてもお聞かせください。","respondent":"中村都市環境部長","answer":"この中で空き家の除却につきましては、平成２９年度と平成３０年度の２年間で４９件ございました。さらなる密集市街地の解消に向けた取組みですけれども、不燃化１０年プロジェクトが終了予定の平成３２年度末に向けて、制度のさらなる周知の啓発に取組むという考えです。","id":"exchange-034"},{"speaker":"塚本委員","kind":"質問・要望","question":"特に空き家について質問させていただきたいのですけれども、区は、平成３１年度予算案で、空き家になる前の発生予防対策を新たな事業として始める予定です。既に空き家となっているものの中で老朽化などのために将来的に活用の見込みがない場合は、所有者に除却を促し、新しい建物を建てたり、売却するなど、土地の再活用が促進されるよう一層の働きかけを求めますが、いかがでしょうか。","respondent":"中村都市環境部長","answer":"現在、不動産団体と相談体制について協議を進めておりまして、この空き家について相談が来た場合に、根本的な内容につきましては、各専門家団体と協力していく体制を整えていきたいと考えております。","id":"exchange-035"},{"speaker":"塚本委員","kind":"質問・要望","question":"この協力体制は大変に大事かと考えています。都議会公明党の求めに対しまして、今年の都議会第１回定例会で、都は、一人ひとりや地域が我が事として、豪雨や河川氾濫、高潮、土砂崩れに対応する意識を高めるため、マイタイムライン作成セットを作成し、都内での普及啓発に努めると述べました。マイタイムライン作成を防災訓練やワークショップなどで活用してはいかがでしょうか。ご見解をお聞かせください。","respondent":"曽田災害対策担当部長","answer":"区民一人ひとりがマイタイムラインを作成することは、確実に避難する上で有効だと認識しており、都の取組みへの対応、訓練やワークショップへの取り入れなどにつきましては、都の施策の具体的な内容を確認しまして。","id":"exchange-036"},{"speaker":"塚本委員","kind":"質問","question":"マイタイムライン人材育成の考え方について、現時点で結構ですので、区のお考えをお聞かせください。加えて、マイタイムライン作成時には、都が作成した東京都防災アプリに搭載されたＧＰＳと連動して、震災のリスクをリアルタイムに知ることができる機能を使用するとのことなので、東京都防災アプリの周知も必要と考えておりますが、見解を伺いたいと思います。","respondent":"曽田災害対策担当部長","answer":"ただ、先ほども述べましたとおり、東京都マイタイムラインの事業につきましては、具体的な内容を承知しておりませんので、人材育成の取組みだとか、あるいは東京都防災アプリの周知などにつきましては、具体的な内容を踏まえまして考えていきたいというところであります。","id":"exchange-037"},{"speaker":"塚本委員","kind":"質問","question":"今定例会の我が会派の代表質問の答弁で、緊急時には防災行政無線の音声を品川コミュニティＦＭで放送するとありました。現在、防災行政無線のデジタル化を進めている最中でありますけれども、防災行政無線の音声を品川コミュニティＦＭから発信するということは、開局時から可能であるのか伺います。品川コミュニティＦＭのスマートフォンのアプリ対応について見解を伺います。","respondent":"中山企画部長","answer":"コミュニティＦＭと防災無線情報との連動につきましては、開局の当初から実施する予定です。インターネット回線で視聴可能なスマホアプリとコミュニティＦＭとの連動、聴取ができることについても準備を進めているところです。","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問・要望","question":"ありがとうございました。これは本当にこれまで防災行政無線、聞こえない、家の中にいると音声が届かない、こういったお声をたくさん伺ってまいりました。区議会公明党では、障害者団体との懇談会などを通して、障害者が災害時に抱く不安や情報の共有など、意見や要望を伺っております。そして、区に対しては、当事者への丁寧な説明と、区や避難支援関係者との定期的な協議を行うことを求めてまいりました。","respondent":"永尾福祉部長、曽田災害対策担当部長","answer":"障害のある方とない方がともに楽しく触れ合えるよう、ふくしまつりや作品展等を実施するなど、障害者に対する理解促進に努めているところです。災害時におけます対応においては、地域の人々の理解のもと、地域と一体となって体制を平素から整えていくことが大切だと考えておりまして、地域の支援による避難行動要支援者の個別計画の作成や、避難誘導のワークショップの実施など。","id":"exchange-039"},{"speaker":"塚本委員","kind":"質問","question":"この障害者の方々への防災対策ということにつきましては、本当に大事な視点と捉えておりますので、今後ともよろしくお願いしたいと思います。続いて、教育と子育てに関して質問いたします。政府は本年１０月から、幼児教育・保育無償化がスタートします。公明党が２００６年に発表した少子社会トータルプランで掲げた幼児教育の無償化が実現するもので歓迎いたしております。","respondent":"福島子ども未来部長","answer":"幼児教育の無償化ですけれども、３歳から５歳の幼児につきまして、全額無償になるです。軽減につきましては、さまざまな軽減を行っておりますけれども、例えば、多子軽減ですとか、あるいは低所得者等への軽減等を行っているところです。","id":"exchange-040"},{"speaker":"塚本委員","kind":"質問・要望","question":"品川区として、多子家庭への支援の必要性についての見解を伺いたいと思います。今回、都独自の支援策で、多子家庭への負担軽減が拡充されますが、これまで国や都に先立って多子家庭への支援策を拡充してきた品川区として、さらなる支援の推進を要望いたしますが、ご所見をお聞かせください。","respondent":"福島子ども未来部長","answer":"多子家庭への支援の必要性は従前から認識しています。次に、さらなる施策の推進についてですが、これは新たな財源が必要と考えられますので、都が創設します補助金の活用等を踏まえ検討してまいります。","id":"exchange-041"},{"speaker":"塚本委員","kind":"質問","question":"短時間就労者の保育について伺います。これまで待機児童対策による保育所定員の拡大で、待機児童は大幅に減少し、来年４月入園に向けた定員増でさらに解消に向かうと期待しております。一方で、短時間就労の方からは、いまだ入園が困難な状況にあるとの声を聞きます。通常の認可保育園に申し込んだ方の中で、就労時間が短い方の入園状況についても、０歳から５歳の年齢別にお知らせください。","respondent":"福島子ども未来部長","answer":"就労時間が短時間の方で、通常の認可保育園に入園した方の４月の一次の数ですが、０歳児が４８人、１歳児が４２人、２歳児が５８人、３歳児が６９人、４歳児が１１人、５歳児が２人です。全体の入園者数の約１割弱の状況です。","id":"exchange-042"},{"speaker":"塚本委員","kind":"質問","question":"いわゆるフルタイムでない０歳から２歳児は、認可保育園に入園することがなかなか難しいというような状況が今の答弁からありましたけれども、５園の短時間就労枠が一方ではあいているという理由について伺いたいと思います。","respondent":"福島子ども未来部長","answer":"今後の短時間就労の受け入れの変化ですが、保育園の増設と年少人口の動向によっては、乳児クラスでも短時間の方が入園できる可能性が上がっていくのではないかというふうに考えている次第です。","id":"exchange-043"},{"speaker":"塚本委員","kind":"質問","question":"介護などの理由によりフルタイムで働けない事情がある家庭の保育の必要性について、区はどのように考えているか伺います。区立認可保育園においては、堺市のように就労と介護を同等に捉える保育所等利用基準など、介護を必要とする家庭の事情に一層寄り添った入園審査の考え方について見解を伺います。","respondent":"福島子ども未来部長","answer":"就労と介護を同時に捉えた利用基準ですが、現在、介護要件としては、８点から１７点の範囲で点数をつけていますが、常勤と同様に、日中８時間以上、週４０時間以上の介護を行っている場合などにつきましては、常勤と同等の指数に見直していきたいというふうに考えております。","id":"exchange-044"},{"speaker":"塚本委員","kind":"質問","question":"ぜひよろしくお願いしたいと思います。次に、小中学生とスマートフォン、ＳＮＳの利用について伺います。ＳＮＳ利用については、ＳＮＳの仕組みを正しく理解し、デジタルタトゥーなどの危険性、あるいは依存症にならないようにすることなどを教えていくことが大切と考えますが、区としての児童生徒に対する指導への見解について伺います。","respondent":"本城教育次長","answer":"中学生の場合ですが、家庭におきまして、ルールについて話し合って、さまざまなデメリットなども検討した結果といたしまして、スマホを持たせない家庭もある現況がありますので、スマホの学校への持ち込みについて、現時点におきましては。","id":"exchange-045"},{"speaker":"塚本委員","kind":"質問","question":"最後に、災害時、緊急時に連絡手段を確保したいという中学生の保護者の声にどのようにこたえるのか、今般の社会情勢を鑑み、区としてまもるっちを中学生が持つことへの考えを伺います。","respondent":"本城教育次長","answer":"そのような観点から、しっかりと学校あるいは教育委員会として伝えていくことが大切であると考えているものです。","id":"exchange-046"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"日本共産党を代表し、総括質問を行います。私からは、羽田新飛行ルート計画の撤回へ品川区の反対表明を強く求め、３点伺います。１点目は、反対表明。２点目は、区民世論。３点目は、住民投票の実施です。ところが、繰り返し反対表明を求めても、区は応じません。改めて、まず濱野区長は、一度でも国交省に計画中止、撤回を求めたことはあるのか伺います。そして、この計画になぜ反対しないのか伺います。","respondent":"中村都市環境部長","answer":"反対ということにつきまして、これは区としましては、現在、国から騒音や落下物の対応について示されておりますけれども、具体性について十分ではないと考えているところです。実効性もまだまだ不明確です。区民に対しての説明も十分ではないと考えているところです。","id":"exchange-047"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"私が伺ったのは、濱野区長は一度でも国土交通省に計画の中止、撤回を求めたことがあるのかないのかです。そして、なぜこの計画に反対できないのか、改めて伺います。","respondent":"中村都市環境部長","answer":"これまで国とさまざまな協議、やりとりをする中では、国に対して、騒音や落下物などの環境影響に対する可能な限りの低減策について、具体的に示し、そして区民に丁寧に説明するよう求めることを繰り返して国交省に対して念押ししているものです。","id":"exchange-048"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"結局今の答弁は、区長が国に対して反対を一度も求めたことがないと認めるものだと思います。私が伺っているのは、区が国に求めていることではなく、区が求めている対応が未達成なまま飛行機が飛ぶその日を迎えてしまうのか、それともいつ反対表明をするのか伺います。あわせて、そもそも飛行機が飛ぶ前に、品川区は計画についての賛否を表明する用意があるのか、考えがあるのか伺います。","respondent":"中村都市環境部長","answer":"そうした国の取組みに対して、まずは耳を傾け、そして説明を受け、区として国に意見を伝え、また、区民の意見もよく聞いてもらい、そして国として判断をしていくというべきものと考えております。","id":"exchange-049"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"答弁が不誠実だと思います。私が伺っているのは、区が国に求めている対応が未達成なまま飛行機が飛ぶその日を迎えてしまうのか、それとも、いつ反対表明を行うのか、そして、そもそも飛行機が飛ぶその前までに、品川区は計画の賛否についての態度を表明する考えがあるのか、しっかりご答弁ください。","respondent":"中村都市環境部長","answer":"先ほども申し上げましたけれども、国は現在、まだ区民に対して説明を行っている最中です。そういった中では、まずは国の対応策をよく聞く必要性があると考えております。","id":"exchange-050"},{"speaker":"中塚副委員長","kind":"質問","question":"実施まであと１年なのです。そのような悠長なことを言っていいのでしょうか。この計画の危険性を区がどう考えているのか改めて伺いたいと思います。品川区民にどのような危険がある計画なのか伺います。住民の知りたいことの１つに、もう決まってしまったのかという問題があります。そこで、もう決まってしまったことなのか、計画の決定とは、いつどのように決められるのかあわせて伺います。","respondent":"中村都市環境部長","answer":"したがいまして、反対ということにつきましては、まだまだ具体性や実効性において区として不十分であると捉えていることを国に伝え、しっかり検討し、説明するよう求めているところです。この計画の決定につきましては、国からは計画はまだ案であるということを確認しております。","id":"exchange-051"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"この計画をよく考えていただきたい。このような危険な計画に対して中止を求めなくてどうするのでしょうか。マンションの価格も騒音が日常的に発生する物件を今までと同じ価格で買いたいと思う人がどれだけいるでしょうか。私は命の危険にさらす計画だと思いますが、いかがでしょうか。落下物が住民に当たったら、この騒音に住民が日々さらされたら、その住民はどうなるのか、区の見解を伺います。","respondent":"中村都市環境部長","answer":"区からもしっかり国に声を届けるとともに、説明会においてもさまざまなご意見を国が直接聞いていることも確認しております。区といたしましても、国の騒音や落下物等の対策について、より一層の丁寧な説明の必要性を感じており、引き続き、国にさらなる取組みを求めていくです。","id":"exchange-052"},{"speaker":"中塚副委員長","kind":"質問","question":"落下物は、どこに落ちるかわからないから危険なのです。今、予見しないとご答弁がありましたが、考えるべきことだと思います。私が伺ったのは、その落下物が住民に当たったら、その人はどうなるのか、この騒音に住民が日々さらされたら、その生活と健康はどうなるのか、しっかりとお答えください。","respondent":"中村都市環境部長","answer":"こうしたものの実効性の担保といたしまして、国は駐機中の抜き打ち検査を行うなどをし、確保していくです。ただ、区もこれで十分とは考えておりませんので、引き続き、国に対して対応策を求めるものです。","id":"exchange-053"},{"speaker":"中塚副委員長","kind":"質問","question":"答弁がかみ合っていないのです。私が伺ったのは、この落下物が住民に当たったらどうなるのか、騒音に住民が日々さらされたら、その住民の生活や健康がどうなると、区はどう考えているのかしっかりお答えください。","respondent":"中村都市環境部長","answer":"落下物の影響につきましては、国では被害を予見せずという回答です。ただ、区いたしましても、やはり区民に対する安全の確保は大事なことと考えております。","id":"exchange-054"},{"speaker":"中塚副委員長","kind":"質問","question":"落下物は予見せず、それでは住民の命と暮らしは守れないのです。落下物が人に当たれば命の危険にさらされるものです。騒音も日々の生活を壊し、健康も害するものです。取り返しがつかないことだから多くの住民は反対しているのです。しかし、どのような対策を講じても、騒音や事故はゼロにはなりません。品川区はそう考えないのか伺います。","respondent":"中村都市環境部長","answer":"国としましても、現在、検討する中で、検査体制の強化などを掲げておりますけれども、引き続き、さらなる取組みについて求めているところです。こういった落下物に対する１つ１つの取組みが、落下物をゼロにするという取組みにつながるものであると考えております。","id":"exchange-055"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"あってはならない、ゼロを求めていると言いますが、危険やリスクをゼロにするには、羽田新飛行ルート計画撤回が唯一の対策だとなぜ思わないのか、改めて伺います。","respondent":"中村都市環境部長","answer":"国が、こうした説明会に前向きに取組んでいるという、そういった姿勢は区としては評価していますけれども、ただ、まだ品川区内において説明会が残っておりますので、引き続き、品川区内全域において国からの説明が行われるように求めている段階であり、現在におきましては。","id":"exchange-056"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"話をごまかさないでいただきたい。説明会を行っているかどうかを聞いているのではなく、計画の撤回がなぜ唯一の対策だと思わないのか、改めて伺います。","respondent":"中村都市環境部長","answer":"まだこういった国の取組みが途中であるという段階におきましては、より一層詳しい説明を受けるというところが一番大事だというふうに考えているところです。","id":"exchange-057"},{"speaker":"中塚副委員長","kind":"質問","question":"先ほどから途中の段階と言いますけれども、実施まであと１年しか残っておりません。まさに最終局面です。こうした濱野区長の姿勢は、区民生活を守る意思は全くなく、結局は計画を受け入れるものです。品川区は、この区民の不安や怒りをどう理解しているのでしょうか。住民からは、どのような声が上がっているのか伺います。そして、どのような被害を与える計画だと住民は思っているのか、区の見解を伺います。","respondent":"中村都市環境部長","answer":"現在、オープンハウス型説明会、また教室型説明会を開催していますけれども、これを見たところ、やはり説明会の中では、国に対して多くの質問がなされております。区としましては、まだまだ国の丁寧な説明が必要であるという見解です。","id":"exchange-058"},{"speaker":"中塚副委員長","kind":"質問","question":"お上の決め事に文句があるのかということだと、さまざま怒りの声が上がっていることを部長はご存じではないでしょうか。区はなぜ区民がこのように怒っていると思うのか、改めて伺います。そして、区民はどのような被害に対して怒っているのか伺います。そして、この飛行機から落下物が落ちたら、飛行機そのものが墜落したらどうなるのか、騒音によって区民生活がどのような被害があるのか、改めて伺います。","respondent":"中村都市環境部長","answer":"区からもしっかり国に声を届けるとともに、説明会においてさまざまなご意見を国が直接聞いていることも確認しております。区としましても、騒音や落下物の対策につきまして、より一層丁寧な説明が必要と感じているところです。","id":"exchange-059"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"さまざまな声とか、説明を求めるとか、落下物は予見せず、そのようなことでは住民の暮らしは全く守れません。もはや品川区は住民の気持ちも被害も他人事だと思います。そこで部長も、濱野区長も、住民説明会に参加して住民の生の声を、当日の状況を把握してほしいと思いますが、いかがでしょうか。区が反対しなければ、国は理解が得られたと判断するとは思わないのか伺います。","respondent":"中村都市環境部長","answer":"説明会の出席につきましては、状況について常に情報共有を図っているところです。それから、理解についてですけれども、区として国に対しさらなる環境影響への対応策や情報提供、また区民への丁寧な説明を求めるという区としての考え方を明確に国に対して示しております。","id":"exchange-060"},{"speaker":"中塚副委員長","kind":"質問","question":"説明会ですが、改めて部長も、濱野区長も出席をすべきだと思いますが、改めて伺います。そして、品川区が反対表明しなければ、国は理解が得られたと判断するとなぜ思わないのでしょうか。相手は安倍政権です。そのような政権に対して反対すら表明しないということは、なおのこと国は理解が得られたと判断する、なぜそうは思わないのか改めて伺います。","respondent":"中村都市環境部長","answer":"理解につきましては、国としては、まだ理解を得たという段階ではないというふうにも明言をしております。区といたしましても、現在、国に対して、その考えを明確に示しております。それは現在さらなる環境影響への可能な限りの低減策を具体的に示し、そして説明をするです。","id":"exchange-061"},{"speaker":"中塚副委員長","kind":"質問","question":"結局、説明会への参加も、計画への反対も拒む、そして今日の答弁も、国交省と同じように、質問に正面から答えようとしていない。結局、この点でも品川区は計画容認だということです。これではいよいよ１年後に計画が実施されてしまう。次に、２点目の区民世論について伺いたいと思います。ずばり低空飛行計画の区民世論は、反対が多いのか、賛成が多いのか、区の見解を伺います。","respondent":"中村都市環境部長","answer":"現在、説明会が開催されましても、国に対し多くの質問が出されております。区としましては、まだまだ国の丁寧な説明が区民の皆さんに対して必要であるという見解です。","id":"exchange-062"},{"speaker":"中塚副委員長","kind":"質問","question":"丁寧な説明が必要かどうかを聞いているのではなく、この計画に住民は反対が多いのか、賛成が多いのか、どちらが多いのかと、その点を伺っております。国も地元の理解を得ながらと何度も述べています。共産党が集めた２,３００通を超えるアンケートでも、反対が多数です。説明会でも参加者の多数が反対です。私も計画反対です。区は、賛成、反対、どちらの区民が多いと思うのか、改めて伺います。","respondent":"中村都市環境部長","answer":"まだまだ国として地域の皆さんへ理解を深めてもらう取組みが不十分であると考えております。は十分な説明を経た後に、国が考える、あるいは判断するべきというふうに考えております。","id":"exchange-063"},{"speaker":"中塚副委員長","kind":"質問","question":"国が判断するかどうかを聞いているのではなく、区がどう思うのかを聞いているのです。反対している区民が多いという事実すら、なぜ認めようとしないのか伺います。","respondent":"中村都市環境部長","answer":"区としまして、さまざまな意見があることを承知しております。１つ１つの意見が尊重されるべきであり、しっかりと国に届ける中で、区として国に対してさらなる環境影響の低減に向けた方策と、検討の説明を求めるものです。","id":"exchange-064"},{"speaker":"中塚副委員長","kind":"質問","question":"区がどう思うかを聞いているのです。反対している区民が多いという事実すら、なぜ認めようとしないのですか。今日ここにもたくさんの議員がいますが、少なからずこの計画に対して区民の多くは反対していると誰もが実感するところです。品川区は反対している区民が多いという事実をなぜそのように頑なに認めようとしないのか、改めて伺います。","respondent":"中村都市環境部長","answer":"新飛行経路は国が進めているものでございまして、現在、国が地域において説明を行っているところです。したがいまして、地域の理解あるいは区民のご意思につきましては、説明を行っている国が確認するべきであるというふうに考えてあります。","id":"exchange-065"},{"speaker":"中塚副委員長","kind":"提案","question":"国が確認すべきことではなく、区がどう思うのかと聞いていることに答えられない。本会議で区民投票の実施を求めましたが、区は区民の理解を深め、それを確認していくのは計画事業主である国が行うものと答弁しました。これは住民投票は国が実施すべきことという意味か伺います。国はなぜ住民投票を拒んでいるのか伺います。そして、国が拒むなら、品川区が実施すべきと思いますが、いかがでしょうか。","respondent":"中村都市環境部長","answer":"引き続き、丁寧な説明をしていくとしております。区もまた国の丁寧な説明により、計画内容をより多くの方に知っていただきまして、国に対しさらなる検討を求めるというものです。","id":"exchange-066"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"だんだん部長の声も小さくなってきたのですけれども、理解が重要とか、多くの方に知ってもらうとかではなく、私が聞いたのは、国に住民投票を実施する考えがあるのか、区は国に求めているのか、ないのだったら、区独自に実施する考えはないのかということです。お答えください。","respondent":"中村都市環境部長","answer":"住民投票というご意見に対して、より多くの方々に理解していただくことが重要として、国は区民に対して説明を行い、意見を聞くと言っているところでございまして、区もまた同じ考えで、意見を聞くのは国の責任であるという考えのもと、引き続き。","id":"exchange-067"},{"speaker":"中塚副委員長","kind":"質問","question":"その声を届けているといっても、では、その声は賛成が多いのですか、反対が多いのですか、どの声を届けているのですか。ちゃんと答えてください。","respondent":"中村都市環境部長","answer":"区民の皆さんからいただくご意見につきましては、単に賛成、反対といったご意見ではなく、騒音影響に対する不安があるというような理由を添えてご意見をいただくというものです。そういった区民の方のご意思と、そしてその理由を国へ事細かく伝えているところです。","id":"exchange-068"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"だからこそ、いよいよ私たち品川区議会が国への反対表明、さらには住民投票の実施など、区民の期待にこたえるため、議決機関である品川区議会独自の役割が今こそ求められていると思います。羽田新飛行ルート計画撤回へ、この１点で多くの政党、幅広い住民の皆さんと一緒に力を合わせることを呼びかけて、私、中塚亮の総括質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"引き続きまして、日本共産党の総括質疑を行います。私からは、国保の問題と、特別養護老人ホームの増設を求めて伺います。国保についてです。国保料の引き下げと、子どもの国保料無料化を求めて質問いたします。改めて国保の構造的な問題とは何かお答えいただきたいと思います。そして、構造的問題は解決が必要だと考えているのか、解決が必要だと考えているのであれば、どう解決をしていくのか伺います。","respondent":"福内健康推進部長","answer":"構造的問題を含め、増大する医療費等が背景にあり、国民皆保険を将来にわたって堅持していくために、今回の法制度改革がされております。区といたしましては、財源の確保について、引き続き、特別区長会、全国市長会を通じて、国や都に対して要望をしてまいります。","id":"exchange-070"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この構造的な問題をどう解決していくのか、これを伺いました。この答弁がありませんので、ぜひお願いしたいと思います。そこで質問をいたします。経年的に見て、国保料がどれだけ値上げされてきたか伺います。４０代夫婦、子ども２人、４人世帯の場合、さまざまな制度改悪の前の平成２１年度と、新年度、平成３１年度の保険料が幾らかお答えください。先ほどの答弁もあわせてお願いします。","respondent":"福内健康推進部長","answer":"経年的に見てどれだけ上がったかですが、年収３００万円の場合、平成２１年度は１７万９,８２９円で、平成３１年度は３６万６,９００円です。年収５００万円の場合、平成２１年度は３２万８,５０５円であり、平成３１年度は５８万４,３００円です。","id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"今の値上げの数字、皆さん、驚かれたのではないでしょうか。年収３００万円の方は１８万円から３６万７,０００円に、２倍以上です。この格差はなくすべきではないでしょうか。そして、日本共産党は、全国知事会も求めています１兆円の公費投入で、時代錯誤の人頭税ともいえる均等割の廃止をすべきと、そうすることで協会健保並みに引き下げられると提案を行っているところです。改めて伺います。","respondent":"福内健康推進部長","answer":"平成２２年度は３５億９,０００万円、平成２３年度は２９億１,０００万円、平成２４年度は２５億９,０００万円、平成２５年度が２２億４,０００万円、平成２６年度が２１億６,０００万円、平成２７年度は１８億６,０００万円、平成２８年度が１５億２,０００万円。","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このパネルをご覧いただきたいと思います。このグラフを見ていただければ一目瞭然ではないでしょうか。法定外繰入の税金投入を平成２２年度並みに戻して、国保料１人当たり４万円の引き下げを求めます。いかがでしょうか。そして、品川区は子どもの国保料均等割の無料化を国に求めておりますけれども、その求めている理由は一体どういう理由で求めているのかも伺います。改めて求めますが、いかがでしょうか。","respondent":"福内健康推進部長","answer":"特別区では、平成３０年から６年間の解消計画を立てて、法定外繰入金を段階的に縮小する予定です。したがいまして、法定外繰入金をもとに戻すことにつきましては、国の方針や特別区の方向性と相違しております。","id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"既に都内でも４自治体がやっております。改めてなぜできないのか、お金の問題なのか伺います。税の再配分によって不公平を正すというのが税金のあり方ではないでしょうか。むしろ税金で不公平な子どもの国保料をなくすことが公平な税のあり方ではないのか伺います。そして、区も国に求めています。税金の使い方として、国と区の税金の使い方の考え方にどう違いがあるのかも伺います。","respondent":"福内健康推進部長","answer":"子どもの均等割の軽減措置につきましては、国民健康保険は全国同一の制度です。子どもにかかる均等割軽減措置を含め、その制度上の課題につきましては、国が責任を持って対応すべきものと考えています。","id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は公平性の観点から一般財源を使うのはふさわしくないという、そのことに対してお伺いいたしました。むしろ公平な税金のあり方として子どもの国保料を無料化すべきではないかと先ほど申し上げました。そのことについての答弁がありませんので、ぜひお願いします。","respondent":"福内健康推進部長","answer":"国民健康保険制度は、国民健康保険法に基づいて運用されているものです。この中で税の使い方、一般財源でまかなうことについては非常に困難というふうに考えているものです。","id":"exchange-075"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"改めて求めておきます。さらに、わずか２億円でできる子どもの国保料の無料化を強く求めて次の質問に移ります。次に、特養ホームの増設を求めて質問します。入所調整会議で入所者を決めるための点数のつけ方について、項目とそれぞれの点数、何点で入れるのか、昨年２月締め切りで９月までに入れた人は何点までの人が入れたのか、おおよそ入れる点数といわれる７０点以下は何人いたのか伺います。","respondent":"永尾福祉部長","answer":"今年２月末締め切りの特養ホームの申請者数ですけれども、総数が４８８人。年齢別人数は４０代が１人、５０代が４人、６０代が１５人、７０代が８１人、８０代が２７０人、９０代が１０９人、１００歳以上が８人となっております。","id":"exchange-076"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"部長はこうした実態に胸が痛まないでしょうか。伺いたいと思います。その息子さんの思いを、その言葉を聞くご両親の思いを部長自身がどう想像し、どう受けとめるか伺いたいと思います。それはなぜなのでしょうか。介護で大変な状況を判断するのに年齢を基準とする理由を伺います。若くして突然倒れ、重度で在宅介護ができない場合は、どのような方法があるのか伺います。","respondent":"永尾福祉部長","answer":"７５歳以上の方についての加点というような形で５点刻みで区としては点数をつけているところですけれども、やはり７５歳以上になりますと、重度化や回復力の低下などが早いというところから。","id":"exchange-077"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"私はこういう若い方が突然倒れた場合、どういう方法があるのかも伺いました。この方には区にも相談しましたが、提案するものがないと言われました。どうなるという見通しが全く立たないのです。改めて伺いたいと思います。８４％、３８８人が入れない。特養ホームの絶対数が足りないことを部長は認めますでしょうか。林試の森隣の増設後も特養ホームの増設が必要だと、こういう認識はあるのか伺います。","respondent":"永尾福祉部長","answer":"そしてまた、ご本人が、例えばほかの有料老人ホームに入っていた場合に、その環境を変えたくないということで、ご家族としては特養に希望されていますけれども、ご本人のご希望でそのままというようなケースもあり、さまざまな場合がありますので。","id":"exchange-078"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"絶対数が足りないというのは、品川区が２０００年から２０１０年までの１０年間、１つもつくってこなかったのです。このことはぜひ認めていただきたいと思います。先ほど、断るケースというのもありましたけれども、では、断るケースが何人いたのか伺いたいと思います。それなのに、なぜ増設計画をつくらないのか、直ちに待機者ゼロへの増設計画をつくるべきだと思いますけれども、いかがでしょうか。","respondent":"永尾福祉部長","answer":"特養の待機者を少なくしてほしいというようなご要望ですけれども、もちろん特養だけではなくて、在宅、また実際に今、どこかの施設に入居しても困っている方はたくさんいるのは承知しておりますので、そういう状況を見ながら。","id":"exchange-079"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今の数字を抜いても４００人は深刻な状況にあるわけです。私は改めて第一日野小学校跡、そして荏原第四中学校跡、この契約や暫定活用法、それから東大井都営住宅跡など、特養ホームの増設計画を立てて増設すべきだと求めますけれども、いかがでしょうか。そして、その計画を直ちに立てるように求めます。そしてまた、林試の森隣の特養ホームもできる限りベッド数を増やすよう求めます。いかがでしょうか。","respondent":"中山企画部長","answer":"公有地等を活用した施設整備につきましては、さまざまな行政需要の中、地域特性等の諸条件を勘案して総合的に判断してまいりたいと考えております。","id":"exchange-080"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひとも土地もあります、お金もあります、この区民の切実な声にこたえていただきたいと思います。そして、年老いた家族も心配で夜も眠れないというつらさから開放されて、身近な地域で面会に行けるように、大変な区民の実態に心を寄せていただいて、待機者ゼロへ直ちに計画を立てて、５００人分の特養ホームをつくるよう求めて質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"木村委員","kind":"質問・要望","question":"最初に、非核平和都市品川宣言事業からお伺いいたします。お聞きいたします。なぜ日本政府は２０１７年７月に採択された核兵器禁止条約交渉に出席し賛成しなかったのでしょうか。我々は、いかなる国であれ、いかなる理由であれ、核兵器の製造、配備、持ち込みを認めないと品川区民の皆さんに改めて宣言してほしいと思いますが、いかがでしょうか。","respondent":"榎本総務部長","answer":"それから次に、品川区としては、非核平和都市宣言を行って以降、区の実施する各種平和事業を通じまして、核兵器廃絶と恒久平和のための意識啓発を継続的に行っていると考えております。","id":"exchange-082"},{"speaker":"木村委員","kind":"質問・要望","question":"人権啓発事業からの質問です。この問題は、人を差別し喜んでいるような大人になる前に、親が、また近所の大人たちが手本となり教えていくことが大事と思いますけれども、行政としてのお考えをお聞かせください。物事は時期を逃さないうちに実行しないと成功しにくいという教えといわれるように、これは我々大人たちにも責任があると思いますが、どのようにお考えかお聞かせいただきたいと思います。","respondent":"榎本総務部長","answer":"子どもたちにもしっかりと伝わるように、親子で参加できる啓発事業等も実施しています。例えばですが、昨年行った性の多様性尊重の映画会につきましては、小学生以上の子どもが親子で参加いたしまして、性的マイノリティについていろいろな受けとめをしたと考えております。","id":"exchange-083"},{"speaker":"木村委員","kind":"質問","question":"未来に向かって希望を抱き、目標に向かって努力し続けるとともに、地域の一員として自覚を持ち、やがて社会の形成者となってくれることを望んでいますとあります。お聞きいたします。先ほどの人権啓発事業で質問いたしました、まさに鉄は熱いうちに打てという言葉、青少年健全育成基本方針そのものと考えます。生命の尊重とは、青少年にどのように指導をしていくのでしょうか。お聞かせください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"木村委員","kind":"質問","question":"どうもありがとうございました。次に、地域スポーツ支援から伺います。年代別に見ると、２０代から５０代のビジネスパーソンの実施率が低く、７０代以上は７１.３％がスポーツを実施しているとお聞きしています。本区では、文化芸術・スポーツ振興ビジョンによりスポーツを振興されていますが、スポーツを強制するものではなく、スポーツに関心を持ち、積極的に参加をしてもらうために何が必要でしょうか。","respondent":"安藤文化スポーツ振興部長","answer":"今後は、引き続き、地域スポーツクラブの充実に向けて支援をしてまいりますとともに、スポーツ推進計画を新たにこれから策定する予定です。その中でこれまで以上に生涯スポーツや地域スポーツを支援をしていきたいと思います。","id":"exchange-085"},{"speaker":"木村委員","kind":"質問・要望","question":"この地域スポーツ支援の中の障害者スポーツイベント拡充について質問です。品川区では、昭和５６年の国際障害者年を契機に、障害がある方もない方も一緒にスポーツを楽しめる環境づくりと、障害者スポーツの推進を目的に、さまざまな教室や事業を実施しています。お聞きいたします。最後に、今後の本区のスポーツ推進全般にあたって、何かあればお聞かせいただきたいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"今後のスポーツの推進策ですけれども、先ほどもお話しさせていただきましたが、今、品川区長期基本計画の策定作業をしていますが、そこの中に新たにスポーツ推進計画を策定することを位置づけまして、これまで以上に障害者スポーツを推進してまいりたいと考えています。","id":"exchange-086"},{"speaker":"木村委員","kind":"質問","question":"こころの健康づくり事業からの質問です。こころの健康は、人が生き生きと自分らしく生きるために重要であり、生活の質にも大きく影響します。こころの健康には幾つかの要素があります。お聞きいたしますけれども、こころの健康とは何でしょうか。あるいは、健康なこころとはどのようなこころでしょうか。どのようなこころの状態を不健康だというのでしょうか。お聞かせください。","respondent":"福内健康推進部長","answer":"健康な社会生活を営むためには、体の健康と同時に、こころの健康を保つことがとても大切です。気分が落ち込み、全てのことに興味が持てず、何事にも悲観的で不安感が強い状態は、こころが不健康といえます。","id":"exchange-087"},{"speaker":"木村委員","kind":"質問・要望","question":"こころの健康とは、まずは生き生きと自分らしく生きるための重要な条件です。お聞きいたしますが、早期の相談や医療機関受診をすることが、よい回復の一歩となりますが、本区での相談状況はいかがでしょうか。本区では、年間７０人ほどの自殺者が出ているとのことです。来年度、自殺対策計画をつくるということですが、どのような計画でしょうか。お聞かせいただきたいと思います。","respondent":"福内健康推進部長","answer":"具体的には、品川区の自殺者の現状を分析した上で、医療機関、児童相談所、警察や消防等、関係機関との連携や全庁的な取組みにより、追い込まれて自殺する人を未然に防ぐことを目指した計画としていく予定です。","id":"exchange-088"},{"speaker":"木村委員","kind":"質問・要望","question":"年間７０人の自殺者が出るということでありますけれども、本当にこころが弱っている人間に対して、周りの方がどれほどサポートができるのか、これは確かに隣近所の方々もそうでありますけれども、やっぱり家族の理解が大変大事ではないかと思っています。これは要望で終わります。以上をもちまして、私、木村けんごの質問を終わります。引き続き大倉委員より総括質疑をいたします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"大倉委員","kind":"質問","question":"木村委員に引き続きまして総括質疑をします。シティプロモーションについて伺いたいと思います。現在、「わ！しながわ」ポスター掲示状況や活用の状況など、また、このキャッチフレーズの区民の認知度など、どのような効果が出ているのか、またその検証状況など、またほかに区外からの反応などがあれば教えてください。シティプロモーションを行っていく意義について、改めてお知らせいただければと思います。","respondent":"中山企画部長","answer":"そういう意味では、プロモーション活動の認知度は上がっているという認識を持ってありますけれども、これはあくまでもツールであって、これをもとにどのように魅力を発信していくかということが大事かということで。","id":"exchange-090"},{"speaker":"大倉委員","kind":"質問・要望","question":"しながわ水族館も新たにポスターをつくられましたけれども、大井競馬場や先ほども言いましたけれども水辺の活用とか、もっともっとポスターとしても活用ができる品川区の魅力のある箇所があるのかと思っていますし、例えばしながわ観光大使シナモロール、地元のキャラクター等もたくさん品川区にはいると考えていますが、さまざまな種類を増やしていくと、例えばカレンダーができたり。","respondent":"中山企画部長","answer":"そのほかにも建築現場に、これはポスターそのものというよりプリントをする形で通行の方にもアピールするような取組みをしているということでありますけれども、こういったものをよりインパクトを持って認識していただくように。","id":"exchange-091"},{"speaker":"大倉委員","kind":"質問","question":"ありがとうございました。こういった活用についてお伺いできればと思うのですが、品川区の小学校、また区有施設の壁、例えば目黒川の内壁や鉄道会社等の線路沿いの壁などを利用して、子どもたちや大人も、また地域の人たちで、環境という点で配慮したアートであったり、また、品川区のプロモーションとしての活用だったり、こういったことができるのではないかと思っているのですが、ご所見を伺います。","respondent":"中山企画部長","answer":"区の施設等でありますけれども、比較的丁寧にメンテナンスしている例が多く、なかなか区内でこういった例が出てくるのは限られているかという認識ではありますけれども、ご提案の例えば河川であったり、鉄道会社の敷地等の中で、可能性があるのか。","id":"exchange-092"},{"speaker":"大倉委員","kind":"質問・要望","question":"クラウドファンディングを実施するため、成功に向けてというところで、取組みを多くの方に知ってもらう、また、品川区がこういうことをやっているのだというシティプロモーションにもつながるのかと思いますが、品川区がどのように周知していくのかと、広報に対する品川区の戦略についてもあわせてお知らせいただきたいのと、今、ほかの区でも、自治体でも、子ども食卓や、佐賀県のＮＰＯでも。","respondent":"福島子ども未来部長","answer":"今後に向け、食の支援の拠点や食を提供する子どもの居場所づくりの検討などを行っていく予定です。今回は子ども食堂や食の支援事業など、既に稼動している事業やスキームが確定した事業を支援していくとともに、さらに今後の展望、方針を示すのが目的でもあります。","id":"exchange-093"},{"speaker":"大倉委員","kind":"質問","question":"さまざま工夫をして成功に向けて進んでいるということで、私たちもさまざまなところで情報発信しながら応援していければと思います。今後についてですが、これはこの事業ということではなくて、これからの品川区のガバメントクラウドファンディングというところで、活用について伺いたいと思います。墨田区の事例ですが、返礼品が結構墨田区ではありました。","respondent":"中山企画部長","answer":"例えば企業との連携の支援につながるようなガバメントクラウドファンディングという点では、現在でもクラウドファンディング利用手数料の助成制度というふうなものを持っておるわけでありますけれども、この辺の活用の枠を広げられるのか。","id":"exchange-094"},{"speaker":"大倉委員","kind":"質問","question":"わかりました。次に、賑わいの創出について伺いたいと思います。劇団四季、スポルなど、多くの人が集まるスポットへ来た方が、商店街へ立ち寄れるような工夫、仕組みづくりも地域経済を潤わせていくことができるというところで、大型の商業施設や地域商店街との連携について、品川区が間に立って連携をとっていくというのは大事だと思いますが、お考えをお聞かせください。","respondent":"安藤文化スポーツ振興部長","answer":"そこの中にもショートトリップ等専門部会がありまして、そこでは回遊性のさまざまな検討をされていますので、委員ご提案の趣旨を踏まえて、今後の検討課題とさせていただきたいと考えています。","id":"exchange-095"},{"speaker":"大倉委員","kind":"質問","question":"今現在、品川区でも商店街と連携してやられていたり、観光協会が先頭に立ってやっていたりということは伺っているので、ぜひさまざまな商店街とそういった連携ができるような検討をしていただければと思います。次に、品川区のイベントの後援というところで、品川区が後援をしているイベントについて、区はどのような役割を果たしているのか。","respondent":"安藤文化スポーツ振興部長","answer":"民間事業者のイベント等の支援と申しましょうか、それについて集客イベントの開催については、地元町会や商店街の理解と協力というものが非常に不可欠であると私どもの認識です。","id":"exchange-096"},{"speaker":"大倉委員","kind":"質問・要望","question":"最後に、防災について。防災訓練、以前も質問させていただいたのですが、子どもの参加がなかなか増えない中で、防災フェスティバルがこの間も開催されていましたが、多くのファミリー世帯の方が参加されていました。子どもたちが参加できるようなドローンの活用や、防災訓練を運動会みたいな形でやるというような、子どもが参加しやすい防災訓練について、どのようにお考えかお知らせください。","respondent":"曽田災害対策担当部長","answer":"さまざまな手段で子どもを呼ぶということはこれからもいろいろ検討していきたいと考えているところであります。","id":"exchange-097"},{"speaker":"須貝委員","kind":"質問","question":"３、災害などへの危機管理体制は大丈夫ですか。もしも大惨事が起きたとき、職員の方は対応可能でしょうか。４、電気やガス、水道などのライフラインは、安定的な供給に支障がないのでしょうか。６、金融機関のＡＴＭ使用や、振り込みや、資金繰り等の借入対応は大丈夫でしょうか。そして、死亡、出生など、戸籍関連の届け出を時間外の夜間受付窓口や休日窓口での対応は大丈夫でしょうか。","respondent":"榎本総務部長","answer":"１０連休に対する区の対応方針ということですけれども、まず、ごみの収集ですけれども、ごみ収集につきましては、この１０連休中に２回日曜日がありますけれども、それ以外については全て平常どおり収集するということで行います。","id":"exchange-098"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、やはりさまざまな金融機関の対応もそうですが、やはり品川区として、身近な自治体として、できるだけ区民の皆さんに情報は流していただきたい。いざとなったら何もできないというのでは、これは区民生活に本当に支障が出ると思いますので、それを教えてください。おそらく心配されている方も多々いらっしゃると思うのですが、この辺についてご見解だけお聞かせください。","respondent":"榎本総務部長","answer":"もっと早くという部分ですけれども、やはりそれぞれ国の対応等も踏まえた上での対応ですので、なるべく早めに広報については周知徹底をしていきたいと考えています。","id":"exchange-099"},{"speaker":"須貝委員","kind":"質問","question":"２問目に移らせていただきます。プレミアム付商品券についてお聞きします。企業格差、個人の所得格差は拡大しています。その中で低所得者層が増えています。その実態を把握されていますか。お聞かせください。区では、景気が上向いているという認識をされているように聞こえますが、その根拠は何ですか。教えてください。","respondent":"中山企画部長","answer":"景況の認識はさまざまの数値がありますけれども、この間、内閣府もやや景況判断を下降の兆しがあるというような報告が出ているのは認識しておりますけれども、全体としての回復基調があるという中での景況判断を区としては踏まえつつ。","id":"exchange-100"},{"speaker":"須貝委員","kind":"質問・要望","question":"商店街もそうです。でも、区内はどうですか。実際は違うのではないですか。今の件についてもう１回、ご見解をお聞かせください。これも悪いということではないのですか。区民に身近な存在である品川区は、きちんとその実態を把握して、区内産業、製造業や商店街もよくないということをよく認識して、それをもとに予算組みをしなければいけないのではないですか。その辺についてご見解をお聞かせください。","respondent":"中山企画部長","answer":"国の数値をもちろんそのまま区のものに当てはめるということではありませんけれども、例えば直近の現状判断、ＤＩ値みたいなものを見ても、業種によって上がり、総合判断の中で３カ月ぶりに上がっている数値があったりするということがありますから。","id":"exchange-101"},{"speaker":"須貝委員","kind":"質問","question":"何度も申し上げますが、区内経済、商店街を含めて、やはり実態は大変厳しいところがあります。ここに１０月に消費税が増税されますが、負担は低所得者層ほど消費税が増税されると大きい。ですが、政府が今後やっていこうとしているように、今は低所得者層の負担を減らすための救済に向けるべきではないのですか。お聞かせください。お聞かせください。この事業について知らなかった。お聞かせください。","respondent":"堀越地域振興部長","answer":"プレミアム付区内共通商品券は今回、１０月の発行の予定といたしましては、２億円増という形での発行を予定しています。こちらは区内商店街の振興、それから個人消費の喚起も目的としております。","id":"exchange-102"},{"speaker":"須貝委員","kind":"質問","question":"この件については、再度お聞きしたいと思います。では、足の悪い方は、買いに行けるのでしょうか。そして、やはり情報弱者といいますか、なかなか品川区の広報誌を見られない方もいらっしゃいます。そうすると、どうしても一部の元気な方で、動ける方で、そしてプレミアム付商品券を買うということは、そこにお金が要るわけですから、そういう人たちに販売が偏るのではないですか。","respondent":"堀越地域振興部長","answer":"これはアンケートから試算をしておりまして、いろいろ内閣府ですとか民間のコンサルティング会社、シンクタンク等の試算では、今まで大体２０％から２５％の経済効果があると言われてありますが、それに比べ区内の経済効果としては。","id":"exchange-103"},{"speaker":"須貝委員","kind":"質問・要望","question":"まして、どうしても買えない人たち、買いにくい人たち、情報弱者の人たちがいますから、そういうことを考えて進めていただきたいと思います。このようなことをやったら、この子たち、誰が責任をとるのですか。東京都でこの子どもたちの行く末に責任をもってもらえるのですか。子どもと接している教員の方々の人物評価はされているのでしょうか。親友になれますか。この辺についてご見解をお聞かせください。","respondent":"本城教育次長","answer":"その点に関しましては、実数が増えているということだけでは必ずしもなくて、学校におけます担任をはじめ教職員が児童・生徒の様子を丁寧に観察しておりますので、その結果として、いじめ等への対応件数が増加してきたということも背景の１つにあると考えているところです。","id":"exchange-104"},{"speaker":"須貝委員","kind":"確認","question":"そしてまた別のお子さんは、先生が相談を受け、本人に確認していたにもかかわらず、自殺している事実、こういうものがあるのです。これに対してどう思われますか。このようなことでは、先生に相談したり、信頼したりすることはできないのではないですか。先生はもういなくなってしまうのだ、そういうことでは信頼関係を築けないと思うのですが、その辺についてもご見解をお聞かせください。","respondent":"本城教育次長","answer":"教師との信頼関係という観点ですが、少し繰り返しになりますが、担任の教員一人だけで対応するのではなくて、組織としてしっかり対応して、さまざまな観点から子どもを見守っていくというのが１つ基礎にあると思います。","id":"exchange-105"},{"speaker":"須貝委員","kind":"質問","question":"ですけれども、逆に増えているという現状を私は申し上げています。そして、その相談に対してきちんと回答をお伝えする、そういう安心感がお子さんに持てなければ、信頼関係など築けないのではないですか。今日はこの人、今日はこの人、今日はこの人では、そういうことではないのではないですか。そういうじっくり１対１の対面で相談に応じる、そういう姿勢が大事ではないですか。もう一度、教えてください。","respondent":"本城教育次長","answer":"そういう意味でも、個別的な信頼関係をベースとしつつも、例えば学校の中には、今、スクールカウンセラー、あるいは養護教員等々、それぞれの違う立場から専門性のある目で子どもたちをあわせて見ることによって。","id":"exchange-106"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはりじっくりその人の話、お子さんのつらいところ、悩んでいるところを聞いてあげて、そしてそれが向こうの信頼関係、お子さんが信頼を持って親に話す、私はそういうことだと思いますので、そこはきちんとやっていただきたいと思います。いじめに対する免疫を持たない子はどうすればよいのか教えてください。今はいじめを克服できる教育をすべきではないのですか。その辺についてもお聞かせください。","respondent":"本城教育次長","answer":"本区といたしましては、例えば市民科においても、自己管理、あるいは人間関係形成領域でさまざまな体験を通じまして、例えば、友達とのコミュニケーションのとり方とか、意見が異なる場合でも対処する仕方だとか、そういうものもしっかり学ばせて。","id":"exchange-107"},{"speaker":"須貝委員","kind":"意見","question":"今、実社会でいじめがやっぱりありまして、私も新入社員の相談を何人かから受けました。そしてやっぱりいじめによりショックを受けて、精神科を受診している方が本当に増えているそうです。こういうことがあるので、私は教育委員会に、自立し、社会に出て生き抜いていける力も養ってほしいのですが、その辺について、教育委員会としてこういうことをやっていきたいという意思表示をしてください。","respondent":"本城教育次長","answer":"今ご質問いただいたことについて、今までの回答と重なるところはあるかもしれませんけれども、教育委員会としては、将来を担う子どもたちに、生きる力をしっかりと育み、現在の学校生活にしっかりと適合するとともに。","id":"exchange-108"},{"speaker":"田中委員","kind":"確認","question":"２０１６年の予算特別委員会で、インフラ整備に係る部署との連携について質問したところ、区内での市街地再開発事業を行う場合は、計画段階から庁内各部署との連携を図り、各地域における行政需要の見込み、必要となる公共施設についても事業者と協議を重ね整備をしてきていると答弁をされましたが、計画の結果に導き出される行政需要を見込むのではなくて、担当部署と協議を行い、保育園や学校。","respondent":"中村都市環境部長","answer":"帰宅困難者等の避難者に対する対応ですけれども、こちらも再開発のビルは地域の防災拠点としての機能も可能な限り担うというところで事業者と協議を進めているところです。","id":"exchange-109"},{"speaker":"田中委員","kind":"質問","question":"計画ありきでインフラが追いついていないように見えます。このような状況からも、再開発が進んでいる地域からは、区として高さや容積率を制限する条例をつくるなど対応が必要なのではないかと聞こえてきますが、区の見解を伺います。次に、マスタープランと個別計画の整合性について伺います。戸越公園に設置される環境館では、防災機能をどのように取り入れていくのか伺います。","respondent":"中村都市環境部長","answer":"再開発におけます上位計画との位置づけと連携についてですけれども、これはそれぞれマスタープランというまちづくりの最上位計画がある中で、再開発を行う際に、その地域、地域におけるまちづくりビジョン、または整備方針。","id":"exchange-110"},{"speaker":"田中委員","kind":"質問・要望","question":"再開発のほうです。今後は、現場の受入能力を前提とした協議、そして整備を求めたいと思います。国の第５回協議会開催に先駆けた都の連絡会について、いまだに開催が決定されていないということをあらかじめ伺っております。そして、何度も繰り返しの質問となりますが、全く答えていただけていないのでまた伺います。であるのなら、はっきりと白紙撤回を明言するべきと考えますが、いかがでしょうか。","respondent":"中村都市環境部長","answer":"ただ、区といたしましても、本当にこれで実効性の担保が１００％図れるのかというところにつきましては、これはやはり疑問が残るところですので、さらに国に対して対応策、新たな強化策を求めていきたいと考えているところです。","id":"exchange-111"},{"speaker":"田中委員","kind":"質問・要望","question":"そこは高さ１４５ｍです。区には、区民や区民の生活や命を守る視点に立ってほしいと再度強く求めますが、見解を伺います。２０１７年第４回定例会からたびたびヤングケアラーについて伺っています。問題の性質上、さまざまな所管がかかわることが必要ですが、今後どのように繰り込んでいくのか、関係する所管の部署と教育委員会の見解を伺います。１８歳を超える子どもへのケアも求めますが、見解を伺います。","respondent":"中村都市環境部長、福島子ども未来部長、本城教育次長","answer":"これはもともと再開発のビルのガラスだとか建設資材の利用のされ方は、台風時にも耐えられるような、そういった設計、あるいは地震も当然ですけれども。１８歳を超えるケアラーに関しましても、昨年、品川区では、子ども・若者計画をつくりまして。今後とも学校として、家庭への適切な働きかけとともに、教育委員会といたしましても、関係各課と連携に努めていきたいと考えているところです。","id":"exchange-112"},{"speaker":"田中委員","kind":"質問・要望","question":"ヤングケアラーのほうです。でも、いろいろな世代や高齢者、障害者福祉、子ども・若者施策にかかわる問題ですので、各所管で密な連携をとり、ケア者支援につなげていただきたいと強く要望いたしますが、見解を伺います。そして、羽田です。そして、武蔵小山のマンションです。これは羽田新ルートのことも想定されてビルの設計、そしてガラスの設定とかもされていたのか、もう一度伺います。","respondent":"福島子ども未来部長、中村都市環境部長","answer":"したがいまして、どのように把握していくのか、あるいはどのような支援が必要なのか、そういったことにつきまして、関係部署と十分に話し合いを行い、今後、検討していきたいと考えています。再開発ビルにおきましては、特に羽田を想定しているというわけではなくて、地震や台風に対する風の耐圧性、こういったものに対して設計で対応しています。","id":"exchange-113"},{"speaker":"田中委員","kind":"質問・要望","question":"羽田ですけれども、担保は今の国の説明だと不十分だから、区として求めるものではないということでしたが、だとしたら、国も落下物リスクをゼロにはできないと言っているのですし、やはり区としてこの新ルート案を容認していないということになると思うのですけれども、そこのところはいかがでしょうか。高層マンションの部分です。答弁を求めます。","respondent":"中村都市環境部長","answer":"ちょっと説明が不足していたというところがあるかもしれません。したがいまして、やはり、国策として取組んでいる国がさまざまな問題に対しては対応策を考えて、そして説明をする立場であるというのは、これがやはり大原則だというふうに考えているところです。","id":"exchange-114"},{"speaker":"田中委員","kind":"提案","question":"提案する立場ではないということだったのですけれども、この羽田新ルート問題では、都心上空の中で一番影響を受けるのが品川区です。ですので、提案する立場ではないとかではなくて、区民の生活や命を守る姿勢、立場に立ったときに、これは実効性が担保されないということがわかっているのであれば、やっぱり区としてはっきりと白紙撤回と明言するべきだと思うのです。そういう部分です。伺います。","respondent":"中村都市環境部長","answer":"武蔵小山の建物に対する影響につきましては、これは国も品川区内全域に対して説明を行うというふうにしているところで、調整中というところで、現在、教室型説明会も今８カ所、残り５カ所について協議していますので、引き続き。","id":"exchange-115"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほどから何回も申し上げているのですが、国は落下物リスクはゼロにはできないと言っているので、やっぱり実効性の担保を求めるなどではなくて、これはゼロにはできないと国が言っているのですから、これは区としても新ルートを容認していないとはっきり明言されたらいいのではないでしょうかと思います。残り５カ所でしっかりと説明をということでしたが、しっかりとした説明を求めます。","respondent":"中村都市環境部長","answer":"説明会につきましても、残り５地区ですけれども、こちらもしっかりと区内全域に説明をしていただくように国に求めてまいります。","id":"exchange-116"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、実際に説明会のところでは、国に求めているだけで、現場ではそのような対応がされていない、区民の方たちからは、とてもそういう声が上がっています。きちんと開かれた説明会の場であることを求めますし、あと、やっぱり区として全体の政策がきちんと整合性がとれていないと思います。区には、区民の生活や命を守る姿勢に立ってほしいと再度強く求めますが、見解を伺います。","respondent":"中村都市環境部長","answer":"ただ、これは国の見解であって、区としては区の考えを伝えていかなければいけないというふうに考えております。ただ、一番大事なことは、やはり地域の皆様に説明がなされることだと考えておりますので、そういったところでは、しっかりと説明自体は行われているという認識です。","id":"exchange-117"},{"speaker":"田中委員","kind":"質問・要望","question":"説明会の現場で、もしもまた国からのメディア規制があった場合に、そうしたら、区としてメディア規制をしないようにということはしていただけるのでしょうか。そこを伺います。そしてやはり区として新ルート案を容認していない、はっきりと白紙撤回を明言するべきと求めますが、いかがでしょうか。","respondent":"中村都市環境部長","answer":"メディア、マスコミに対して規制をしないですけれども、こういったことについては、説明者である国が最終的には判断をするというところが残念ながらあります。","id":"exchange-118"},{"speaker":"田中委員","kind":"質問・要望","question":"説明会でのメディア規制について、きちんと区として申し入れてください。そのように求めますが、いかがでしょうか。","respondent":"中村都市環境部長","answer":"そういった地域の皆様からの声も届いておりますので、しっかりと伝えたいと思います。","id":"exchange-119"},{"speaker":"渡部委員","kind":"提案","question":"歳入では、順調に特別区民税が伸び、収入が増え続けるものの、他自治体へのふるさと納税による流出の影響は増大し、引き続きの対策が求められます。地域の保護者、児童に漏れることなく、制度周知されるよう求めます。本日の総括質疑や、この間の款別審査にて、自民党・子ども未来１１名の委員からの要望、提案を新年度の事業実施に生かされるよう求め、品川区議会自民党・子ども未来の意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-120"},{"speaker":"若林委員","kind":"提案","question":"品川区議会公明党の意見表明を行います。最後に、予算執行や施策展開にあたっては、総括質疑で取り上げたＳＤＧｓの推進、給食プラスチックストローへの対応、空き家対策、マイタイムラインの活用、障害者の災害時支援をはじめ、款別審査での提案や意見、要望を今後の区政運営に反映されるよう求めます。以上で、品川区議会公明党の意見表明を終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-121"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"日本共産党は、安倍政権による社会保障の解体や消費税１０％増税などの悪政から、地方自治体の本旨、住民の福祉の増進で区民生活を守り抜く区政を求めてきました。国保料は、値上げではなく引き下げこそ、子どもの均等割を廃止し負担軽減を求めます。２３区で最低の整備率の障害者グループホーム、就労継続支援Ｂ型、放課後等デイサービスは、区外利用者の要望をつかみ、施設増設と支援充実を求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-122"},{"speaker":"石田（し）委員","kind":"提案","question":"ＡＩやＩｏＴなどの活用や、情報発信のあり方、羽田新飛行ルート、学校教育、東京２０２０大会などの課題への積極的な取組みも求めます。ダイバーシティの視点も求められています。今回の予算特別委員会において、我が会派の所属議員が、質問の中で指摘、提案した各項目を真摯に受けとめ、予算を執行することを強く要望して、国民民主党・無所属クラブの意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-123"},{"speaker":"須貝委員","kind":"質問・要望","question":"平成３１年度品川区各会計予算について、無所属品川の意見表明をします。品川区一般会計、国民健康保険事業会計と後期高齢者医療、介護保険、災害復旧の３つの特別会計の各予算に賛成します。特別区民税と財調が増え、一般会計予算は約１,８７７億円と過去最大となりました。低賃金で社会を支えている民間の保育士や幼稚園教諭や介護士の処遇を早急に改善するべきです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-124"},{"speaker":"吉田委員","kind":"提案","question":"以下、何点か意見を申し述べます。１０月の開設に向けては、このような齟齬が起きないよう強く求めます。今回実施された調査結果を生かし、相談者に寄り添った相談支援体制を一刻も早く構築することを求めます。今後も給食の放射能検査を継続することを求めます。その他、款別審査で生活者ネットワークが指摘、提案させていただいた意見を予算執行に生かしていただくことを要望し、意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-125"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/430016?Template=document&Id=1104#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":107764,"voices":291}},{"id":"r01-20190325-10","meetingId":"r01-cm03","date":"2019年3月25日","dateIso":"2019-03-25","committee":"議会運営委員会","time":"午前１０時３０分～午後 １時２０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件抜き出しています。","topics":[{"id":"topic-01","title":"決議案","agenda":"決議案","exchanges":[{"speaker":"飯沼副委員長","kind":"提案","question":"品川上空を飛行する羽田新飛行ルート計画に反対する決議について、提案理由を説明します。１点目です。羽田新飛行ルート計画は２０２０年までに実施に移す計画です。１年余に迫っています。４点目、国は地元の意見を聞いて進めるとしています。この時期になり、国交省に撤回を求めるためには、反対の文言を入れた決議が必要であることを強調し、決議を読み上げします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"若林委員","kind":"提案","question":"平成３１年第１回定例会を閉じるに当たり、現段階で全会一致をもって品川区議会として決議できる内容として、このようにご提案をしたいと思います。表現も含めて、読み上げさせていただいて説明に代えたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"２つの決議案はほぼ同じなのです。１段落目、２段落目は若干文言整理のようなことですが、趣旨は同じだと思います。違う点はただ１つで、「反対」という文言があるかないかなのです。なぜこの「反対」という文言を抜いたのか、その理由をぜひ、３会派で共同提出されておりますので、自民党、公明党、国民民主党に伺いたいと思います。なぜこちらでは全会一致できないのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"本多委員","kind":"質問","question":"さらに申し上げれば、２つの文が出ていますが、これは品川区議会としての決議文ですから、全会一致が望ましいと思うのです。なので、２つの文を１つにまとめる作業も必要かと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"提案","question":"私どもも共同提案ということで、今、本多委員のお話のとおりです。そもそも大上段で「反対」という言葉が入ってしまったら、再考の余地もないわけですから、私どもがかねてから申し上げているところ、また今回、全会一致で皆さんにご理解いただけるのではないかというところで、今回提案した文書になっています。私はやはり一本化をすべきだと思いますし、最大限の努力をしていくべきであると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"石田（し）委員","kind":"提案","question":"その最優先にやるべきことというのは、今回我々が提案させていただいている決議であれば、品川区議会での各会派が総意で出すことができるのではないか、そういった意味では、我々としてはこの提案書どおりに何とか皆さんの一致をもって、区議会の総意としてやるべきではないかと思っているところから、今回こちらを出させていただいているということであります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"安藤委員","kind":"提案","question":"全会一致で出していく努力というのはもちろん、大事だと思います。お伺いしたいのですけれども、市民団体の「みんなの品川」というところが、区議会議員を含む、今度の選挙立候補予定者に対して、羽田新ルートの公開質問アンケートというものをとりました。そこをなぜ賛成できないのかわからないので、ぜひ公明党、国民民主党には、私たちの案にも賛成していただけますよねということをお伺いしたいです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問","question":"今、安藤委員から、「みんなの品川」のアンケート結果について、お話があったのですが。これはどこかで公開されているのですか。どこに公開されているのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"公開質問アンケートですから、「みんなの品川」という団体のアンケートを、私ももちろん返しましたけれども、その団体の中には、共産党も幹事として入っています。そういうところで……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"先ほど市民団体とおっしゃいましたけれども、その回答を知っているわけですよね。当然それは公開されるものだと、公開質問として来ましたから、今そういうふうにおっしゃるということは、その質問の根拠というのは、あなたたちが出した、あなたたちが考えたアンケートを選挙に当たって出してきた、こういうことでいいのですか。それをお認めになったということでいいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"先日、「みんなの品川」の幹事会が開かれました。そこは政党だけではないです。市民の方も入っていますし、大学教授の方も入っています。その市民の役員も入ったところで、こういうアンケートの結果が出ましたという報告があったのです。それを私たちは聞きました。ですから、何の問題もないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今の件ですけれども、公開質問状の中に「みんなの品川」の構成団体がどういうものかということは、明確に載せてあります。その中に共産党も入っていますので、当然幹事会という形になったときは行くということも含めて、ご理解いただいた上で公開質問状ということで回答をいただいたものだと思います。公開質問状はそういうものですから。しかも公開質問状ですから、間もなく全て明らかにされるものです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問","question":"今、その質問状の表書きが手元にあります。立候補予定者の皆様へということで来ているわけですから、個人で回答しています。こうは言いたくないですけれども、立候補予定者の方に出すものを、共産党が名前を連ねている、確かに入っています、生活者ネットワークも入っている、立憲民主党も入っている、けれども、これは政党から政党に対して出したものなのですか、と聞いたのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その団体の中に含まれている、政党も入った団体だということで、ご承知おきの上に公開質問状に回答があったというものだと思うのです。なので、そこのところはもう公開されているものですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問","question":"公開されていないでしょう。どこに公開されているのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"間もなく公開されるものですから、そういうところも踏まえた上で回答されたものだと思いますので、私たちはその団体に所属している一団体ですから、そういうことで全く問題ないということを申し上げておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"渡部委員長","kind":"質問","question":"今の件で申し上げます。委員長として、いまだ公開されていないものに対して、そのようなことをここで議論することは控えようと思いますので、そこまでにしてください。それで、次の質問をどうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"ここのところで、私たちが提案した決議案に対して、「反対」という文言をとったものになっているのですけれども、改めてお聞きしたいのは、「容認することはできない」、ここまで述べているわけです。容認することができないということは、反対ということではないのでしょうか。そこのところを改めて、自民党、公明党、国民民主党、それぞれ伺いたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"本多委員","kind":"意見","question":"同じことなのですよ。文にあるとおり、このままでは認められませんよ、再考をということですので、人から人に物事を頼むということも含めて総合的に判断して、こうなるのですよ。頼む姿勢もあると思うのです。やはり認められませんよということだと思うのですけれど。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問・要望","question":"本多委員のおっしゃるとおりで、一体何を求めるのかというところで、我々は対話を求めていきたいわけです。粘り強い対話を求めていきたい。先ほど鈴木ひろ子委員ご自身がおっしゃったように、容認することができない、そのようにお感じになるのであれば、この文章のままでいいのではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そのほか試験飛行も含めて、国がやるべきことをしっかりやってほしいというのを区に対して、国に対して求めている中であって、それを言葉だけで反対だとか、賛成だとかではなく、我々は現実的にどうしたらこの課題が解決するのかといった意味では、総意で決議を上げられるのであれば、私はこの３会派が出している案が現実的であり、区議会が一致して出せるものであるなら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"ここを４年間ずっとやってきたわけです。何としてもこれをとめてほしいというのが、区民の思いなのです。容認できないと言っているのであれば、全会一致で反対決議ということになるのではないですかと、私は聞いているのです。この計画を知った方は、ほとんど反対ですから。容認できないというのであれば、反対と明確に意思表示をする、その決議をなぜ上げられないのかということを伺っているのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"石田（し）委員","kind":"提案","question":"我々の認識では、区民が思っていることは、区議会が一致団結して、この新飛行ルートに関しては見直しも含めて検討させるべきだということが、区民の思いだというのが我々の理解であって、反対とか賛成とかではなく、新飛行ルートに関してしっかり、上空を飛ばさないためにはどうしたらいいのか区議会としても考えて、提案すべきだというのが我々としては区民の思いだという理解です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"地元の理解を得たかどうかというのは、どこでどう判断するのだということを何回も国交省に聞いているわけですけれども、国交省は明確に応えていません。それが区民の思いだと思うのです。これから議会も改選になるわけですから、そういうところでいえば、この議会での最後のチャンスですから、ここで反対の決議を、国交省に向けて議会の総意として示していくというのが一番大事なことだと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"石田（し）委員","kind":"提案","question":"なので、こちらの案であれば総意でできるのではないかという、提案をしているわけでありますので、そこはぜひ検討していただきたいと思います。これをただただ、賛成だ、反対だといって、ではどうするのですか。なので、我々はしっかり、区民が今本当にどう思っているのか、大勢の人に聞きましょう、しっかり確認しましょうというのも、提案としてやっているわけです。反対だ、反対だと言っている。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"その回答の８割は反対、賛成者は本当に数％という状況だということは、この間やっていますし、議会の中でも区民投票を品川区としてやるべきだという提案も行っているところです。そういうことで、区民の意思でこのことを決めていくべきだということは、ずっと提案しています。容認することはできないという言葉で書きながら、反対するということが言えない立場なのか、改めてお聞かせいただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"石田（し）委員","kind":"質問","question":"立場としては別に何ら、反対も賛成の立場も別に、我々としてしっかり議論をした中で、政党としての意見というのは別に、賛成の立場だろうが、反対の立場だろうが、どちらでも別に、賛成の立場に立てないのかとか、反対の立場に立てないのかという質問なので、それはどちらでも、我々としてはしっかり議論をした中で示す方向性があるのであれば、それは賛成だろうが、反対だろうが、立場というのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問","question":"ですから我々も何度も言っているように、容認することはできない、これはもう常日ごろ、昨年から我々はこの表現をしているわけです。なぜそれを賛成、反対という言葉で当てはめようとしているのか、これは決議の話ですから、全会一致でやるのであれば、この文章でいいではないですか。なぜそういうふうにしたいのですか、逆に。なぜそれを押しつけるのですか。この文章で何が悪いのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"反対だと明確な意思表示を国交省に向けて、区議会としての意思表示をするということ、この新ルート計画に対しては、区議会として反対だという意思表示をすることこそが、１年後に迫ったこの時期に必要だと。そこで容認できないと言うのであれば、反対だということがなぜ入れられないのか、聞いているわけです。反対ではないのかということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"提案","question":"冒頭で申し上げましたけれども、繰り返し同じことをおっしゃっているので、先ほどから申し上げていますけれども、先ほどの提案理由にもありましたけれども、区議会として全ての会派、議員の考え方が一緒であるということではないのです。さまざまな捉え方があるわけです。そちらの本旨でいうならば、なぜこれに賛成できないのですかということです。なぜこの文章ではだめなのですかということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"飯沼副委員長","kind":"提案","question":"反対の文言が入らない、やはりここの違い、理解の仕方だと思っていますが、他会派と共同で提案し、文書をつくったときの内容としては、区民世論の反対を、私たち提案者は明確に受けとめたのです。私たちはそこを強調したいと思います。ここを強調していますので、全会一致でまとめてほしいと言われても、既にそこのところ、皆さんの意見が変わらない限り、私たちはこれを提案していきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"若林副委員長","kind":"提案","question":"委員長の仕切りで、お互いにこちらの案で全会一致でいけないのかということはお互いに投げかけられていますが、今の中ではどうもまとまらないということですが、それでも投げかけられているということなので、生活者ネットワーク、筒井議員、須貝議員、藤原議員という提案者になっている方も一部この場にいらっしゃらないので、例えば持ち帰っていただいて、一回休憩して。","respondent":"渡部委員長","answer":"この間議会においては、先ほど石田しんご委員からも説明がございましたように、平成２６年度から品川区においてはスタートしており、当初は行革特別委員会、今年度は建設委員会においても活発な議論がされてきたと思います。","id":"exchange-032"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"先ほどの議論の中での話を、先にさせていただきたいと思います。先ほど賛成とか、反対という立場になったとき、我々が今の時点で、いろいろな声があると、もちろん反対されている方たちの声も聞いていますし、一定理解をされている方たちの声も聞いている中で、先ほどアンケートをされて８割方は反対だと、では残りの２割の方たちの声はどこに行くのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その団体が公開質問という形で候補者に対してのアンケートをとったものだと。だから共産党も参加する団体による公開質問だったということですから、それは情報が入ってこういうところにその状況を出するということは、当然あり得るということで、皆さんもご回答いただいているところだと思います。それともう一つ、少数派の声を聞くべきということですけれども、２割の方も賛成しているわけではないです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"全然質問にお答えいただけていないのですが、我々はその団体の構成がどうだったとかという話はしていないのです。だから公開するわけで。あくまで公平性をもってやるべきこと、公開をした後にしっかりと議論をするのは大いに構わないですけれど、その辺はやはり一定の期間まではしっかり持っている情報は公開できないと思うので、そこはぜひ改めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"飯沼副委員長","kind":"提案","question":"他の提案者と意見を交わしてきました。この間、地域を回っての区民の方たちとの話し合い、またアンケートもとりました。私たちはそこに確信を持っていますので、区民の代表である議会がやはりそういった区民の声を反映させて、責任ある態度をとっていく、そのことが求められていると思いますので、私たちが提案しました反対をする決議をぜひ、提出をし、賛成をしていただきたいと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"本多委員","kind":"提案","question":"共産党も先ほど全会一致で決議を出すのが望ましいと言われておりましたけれども、平行線なので、私、一つ提案させていただきたいのが、反対の声も聞こえているのは事実ですので、文言の中にそうした状況、「区民の反対意見もあり」という文言を入れた上で、表題には「反対」を入れず、文言の中に、区民の反対意見もありますという現状を捉えて、修正されて、結論を導き出すのはいかがかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"提案","question":"幹事をやられているから本当なのでしょうけれども。その中でも多分、各立候補予定者また現職の区議会議員からも、いろいろな意見があったのではないかと思います。ですから、聞く耳を持っていただいて、今ご提案があったような、どうしても「反対」という文言を入れたいのであれば、そういう形で「区民の声」ということで入れていくのも一つかなと、私の会派もそう思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"石田（し）委員","kind":"意見","question":"我々も、今回同じような決議が２つ出るというのは、区民に対して混乱も招くし、現実的に考えるというならば、本多委員が示された、いわゆる譲歩案といいますか、その２つの間をとってという案に対しては、我々も、全会一致でできる決議文になればと思いますので、賛成していきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"先ほど提案者の会派が皆そろって話し合いを行った結果、この「羽田新飛行ルート計画に反対する決議」、この文言を入れた決議案を必ず出していこうということでは変わらないということになっております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"私たちは、そういう区民の声を受けて議会として反対するということが、反対するという意思表示をしっかりとするということが大事だということで、今回の決議の共同提案になっておりますので、その決議は持ち帰りはしないということが一つと、こちらの提案に対しては、賛成をします。３会派の提案に対しては賛成をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"渡部委員長","kind":"提案","question":"私、委員長として腑に落ちないところがあるのですけれど。ほかに何かありますか。全く提案も受け入れられないということですので、そうしましたら、今回資料No.３－１と３－２、それぞれ議会に提出をして、それぞれについて採決するということで、よろしいですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"あくつ委員","kind":"確認","question":"確認ですけれど、討論の関係はいつ決めるのですか。これから議事日程の確認に入ると思うのですけれども。討論の関係は何か申し出たほうがいいのか、それとも個別に事務局での確認手続なのか。","respondent":"久保田区議会事務局長","answer":"もし討論されるということであれば、休憩中に確認しますので、氏名報告をお願いします。","id":"exchange-043"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（秀）委員","kind":"意見","question":"我々も会派でさまざま話をしている中で出てきたことで、この中で一つだけ言っておいてくださいということがあり、私もそう思うのですけれど、現職の議員なので、選挙だからといって、ある程度違反だとわかっていることは、もうやめましょうということだけ。ほかのこともあると思うのですけれど、わかって気がついてやるということはやめましょうということだけ、お伝えしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/268822?Template=document&Id=5318#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":29313,"voices":114}},{"id":"r01-20190610-6","meetingId":"r01-cm06","date":"2019年6月10日","dateIso":"2019-06-10","committee":"区民委員会","time":"午後 １時００分～午後 ２時５９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を6件抜き出しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"地域振興部ということで、事務事業概要なので、大きく１点だけ生活安全担当課長にちょっとお伺いしたいのですけれども、品川区には警視庁から幹部職員が来てくださることが既に伝統になっております。１点は、警視庁本庁からここに来られて、品川区の区民の安心安全に対する心構えを、きょうは初めてなので、お伺いしたいのが１点。","respondent":"黛生活安全担当課長","answer":"このシステムはいろいろな自治体から問い合わせが来たり、私のところでもやりたいと相談等が来ていると伺っておりますが、さまざまな事情によりその他の区では断念している中において、この品川区におきましては、皆様方の大変なご尽力をもちまして。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"それからあと、商業・ものづくり課で、補正予算で臨時商品券を組まれるということですし、今年消費税１０％に引き上げに対応して、共通商品券も２億円ということでしたけれども、私自身は消費税の対策にそれだけ要るのだな、そもそも引き上げないのが一番だと思っていますけれども、それはさておいて、本当は国の話だから、国に持っていくべき話なのですけれども、品川区としては、共通商品券２億円増額とか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"藤原委員","kind":"質問・要望","question":"今日は事務事業概要ですから、大きく伺います。そのとき視察したことは、私が議員をしていく上で今でもとてもプラスになっています。前置きがちょっと長くなったのですけれども、安藤部長、全庁的というお話もあるのですけれども、お一人いらっしゃるという意味で、区民委員会が今日からスタートですから、心構えをいただきたいと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"安藤文化スポーツ振興部長","answer":"それなので、切り口はたくさんありますけれども、心構えとしてあともう４００日少し、品川区をいかに売り出すことができるか、またオリンピック・パラリンピックを成功させるかについて、毎日一生懸命、真剣に取り組んでいきたいと思ってあります。","id":"exchange-003"}]},{"id":"topic-02","title":"令和元年度文化センター等工事による休館・休室予定","agenda":"令和元年度文化センター等工事による休館・休室予定","exchanges":[{"speaker":"藤原委員","kind":"確認","question":"休館・休室はわかったのですけれども、スクエア荏原は、私の感覚でいうと、できてからそんなに古くはないという思いがあるのですけれども、それでもう工事に入ると。１つだけ確認したいのは、これは初期設計のミスとか、そういうのではないのですよね。初期のミスでないということと、それに付随して、なぜやるかということも的確に教えてください。","respondent":"古巻文化観光課長","answer":"夏季の熱中症対策も含まれていると思います。イベントホールにつきましては、照明のＬＥＤ化です。こちらも省エネの観点から、区の施設全体的に進めているものの一環ですので、こちらも初期のふぐあいという性格のものではございません。","id":"exchange-004"},{"speaker":"藤原委員","kind":"質問・要望","question":"初期の設計ミスではないということなのですけれども、スクエア荏原はそんなに古くない施設だから、私自身もその当時のことはあれなのですけれども、つくるときに初めからアリーナの冷暖房化という案はなかったのですか。当時担当ではないからわからないと言われればそれまでなのですけれども、そんなに古い施設ではないですものね。そこがわかれば、ちょっと教えていただきたい。","respondent":"古巻文化観光課長","answer":"当時の正確なやりとりというのは、私もこの場ではご答弁しづらいのですけれども、一般的なお話として、大規模な空間、体育館といったものの冷暖房、エアコンの設置については、数年前はかなり技術的に難しいという認識で設計をしていたと聞いていますので、それを踏まえて。","id":"exchange-005"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"基本的には正副一任なのですが、経験も含めて、２年前に佐賀がありました。そのときにも私はこういう発言をしました。ですから、視察は場所よりも内容が一番ですけれども、どういう視察をするかということが一番だと思いますが、秋は台風の季節ですので、ここは考えの中の１つにしていただきたいのが１点。ちょうど札幌に泊まっていた夜中にぐらぐらと揺れたのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/826260?Template=document&Id=2836#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":38590,"voices":78}},{"id":"r01-20190610-7","meetingId":"r01-cm06","date":"2019年6月10日","dateIso":"2019-06-10","committee":"厚生委員会","time":"午後 １時００分～午後 ４時３５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件抜き出しています。","topics":[{"id":"topic-01","title":"の２の事務事業概要","agenda":"の２の事務事業概要","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"あわせて６人ですか、派遣されているということなのですけれども、目的は何なのか、そして何年ぐらい派遣をされているのか、そしてその派遣された方が品川区に戻ってどう活かされているのかということについてお聞かせいただきたいと思います。それが１点です。それで、実際問題も、すごく残業も多くて大変な状況だというふうなところもお聞きしていますので、これもあわせてお聞かせいただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっと別な点で、障害者福祉のほうで、障害福祉計画が平成３０年から始まりまして、今年は２年目になりますけれども、３年間の計画なので今年はアンケートとかヒアリングとかをやっていくということでのご説明があったのですけれども、前回のところは、自立支援協議会が策定委員会を兼ねるというふうな形でされてきたと思うのですけれども。","respondent":"寺嶋高齢者福祉課長、築山障害者施策推進担当課長、矢木生活福祉課長","answer":"例えば、これまでの例としましては、保健師の方にもお若い方、子育て中の方がいれば、保育園のお迎え等もありますが。策定委員会をつくるのかというご質問についてですけれども、こちらは別途委員会をつくって実施していく予定となっております。所管としてできることといたしまして、事業の集中化、効率化は常に考えてございまして、例えば遠方の病院訪問をまとめていくですとか。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"地域包括支援センターなのですけれども、事務職は地域包括支援センターには入らないので、それを除くということなのですけれども、そうすると、事務職を除いた保健師、社会福祉士、主任ケアマネ、そこの３職種の人は高齢者福祉課の全ての職員が地域包括支援センターの担当という位置づけになるのでしょうか。もう一つだけ、ごめんなさい。","respondent":"寺嶋高齢者福祉課長、松山障害者福祉課長","answer":"地域包括支援センターの位置づけですけれども、まず地域包括支援センターは品川区の場合は、在宅介護支援センターというところからもともと始まったもので。人員体制につきましては、人を増やすとともにスキルアップということで今研修をしておりますので、今後とも区民の皆様の期待に応えられるよう、丁寧にお声を拾ってサービスの充実を図ってまいりたいと考えております。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"地域包括支援センター、私はこの間ちょっと指摘してきたところなのですけれども、在宅介護支援センターには３職種が配置されておりませんので、３職種配置されている地域包括支援センターというのは高齢者福祉課のところにあるものだけですので、そこのところがどういう形で地域包括支援センターがここだという、これが地域包括支援センターが担っているところだよというのはないということで。","respondent":"寺嶋高齢者福祉課長","answer":"高齢者福祉課の窓口だけではなくて、在宅介護支援センターも含めて機能を分散して、地域包括支援センターということで運営をしていて、必要に応じて各在宅介護支援センターのほうから、例えば保険料に関する相談ということであれば。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問・要望","question":"やはり、そういうプロフェッショナルなところにつくっていただくというのも大切なことだと思うのですけれども、品川の障害者福祉をよくご存じの方、あるいは当事者の意見をアンケートの中に入れていくということがよりよいアンケート、アンケートの質によって出てくることというのは大分変わるというのは区の方もよくご承知のことと思いますので、どういう形でアンケートをつくられるのか。","respondent":"築山障害者施策推進担当課長","answer":"あわせて、障害者団体等へのヒアリングのほうも実施する予定となっております。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問・要望","question":"これは要望にしておきますけれども、やはりアンケートは項目の段階からお声を聞くというのも一つのやり方だと思いますのでご検討ください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"渡部委員","kind":"確認","question":"たわいのないことというか、大事なことなのですが、先ほどから数字の訂正が大分入ったと思うのですけれども、これは暫定版ですよね。ちゃんとした冊子版になるときは直ってくるのですよねという確認だけ。誰でもいいです。","respondent":"高山健康課長","answer":"大変申しわけございませんでした。本日ご報告の中には何点も修正点がありますので、冊子としてお出しする際にはそうしたことがないように心がけてまいります。","id":"exchange-007"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ネットワークというもの、ここの中には、虐待防止ネットワーク委員会というものもできているし、それからあと高齢者虐待対応チームというのがつくられて、そういうふうに事例ごとに対応するということも書かれているのですけれども、虐待防止ネットワークというのはどのように機能しているのかということと、今回の虐待というふうなことで立ち入り調査に５月３１日に入って。","respondent":"寺嶋高齢者福祉課長","answer":"その場合に、それが実際行われたかどうかの確認をするとか、そういった形を想定していて、今回のように、ちょっと異常な骨折でお亡くなりになっているという、こういったものを、全く想定していないわけではないのですけれども、こういう案件以前に。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、今回立ち入り調査に５月３１日に入られた方というのは、高齢者支援第一係と給付係の係長という、ちょっとその調査に入られた方のメンバーだけ教えてください。","respondent":"寺嶋高齢者福祉課長","answer":"今回は施設なので、施設支援係長と職員、それから介護保険の給付の検査指導をしている介護給付係の係長と職員、それから支援第二係のほうに虐待関係の担当の係長級の主査がいますので、その職員、計８名でこの日は調査した。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問・要望","question":"委員長にお願いです。今日の訂正の部分を紙でも出していただきたいと思うので、それは多分厚生委員会で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問","question":"冊子が来るより数字ですから。〔「いや、だめだめ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこの中でもちょっと出されていたのですけれども、ショートステイ、医療的ケアの必要な方の受け入れというふうなところが、なかなかちょっと実際問題、そこの方の受け入れというふうなことにまずはならないような、そういう形の説明だったと思うのですけれども、この計画の中で３１ページなのですけれども、平成３１年の開設も総合支援施設では。","respondent":"築山障害者施策推進担当課長、鈴木（博）委員長","answer":"ただし、受け入れに当たっては、どうしても安全な体制を整えてから受け入れたいというところで、運営業者とも協議をしているところではあるのですけれども、段階的に体制を整備していって。所管事務調査についてご案内いたします。さきの正副委員長会において話がありましたが、議会の活性化の観点から委員会として積極的に所管事務調査に取り組んでいく必要があると考えます。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"この間、障害児者の支援についてという点では、区としても相談支援体制を改めて充実させるという方向になっていますし、私は障害児者の支援についてというのを所管事務調査の中で深めていきたいというところでぜひお願いしたいなと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"渡部委員","kind":"質問","question":"今回初めての委員会で、今投げかけられて、鈴木ひろ子委員はお答えになられたけれども、多分準備をしてきていない方も多いと思うのですよ。ですから、どこかで日付を決めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/461144?Template=document&Id=3534#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":64672,"voices":100}},{"id":"r01-20190610-8","meetingId":"r01-cm06","date":"2019年6月10日","dateIso":"2019-06-10","committee":"建設委員会","time":"午後 １時００分～午後 ４時００分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"高橋（伸）副委員長","kind":"意見","question":"副委員長の、自民・無所属・子ども未来の高橋伸明です。１年間、しっかりと委員長をお支えいたします。理事者の皆様、委員の皆様、書記の皆様、この１年間、どうぞよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"説明にもありました第四次事業化計画のことですけれども、優先整備路線のほうは説明があったのですけれども、未着手整備路線を対象に、在り方について調査・検討を進めていると、この資料にも書いているのですけれども、これは昨年の建設委員会で中間まとめの報告がありまして、それですと３月ごろにはもう基本方針の策定。","respondent":"鈴木都市計画課長","answer":"今、日時等については検討中ということで、この場では具体的な日時はご説明できませんが、改めてご報告したいと思います。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"こういった大事な資料なので、なるべく最新の情報を載せていただきたいと思いまして、１２月末ですと、もう６カ月たっています。それと、概括的なところで２点だけ、再開発と羽田についてお伺いしたいのです。それが、なぜ事務事業概要には記載が一切ないのか伺いたいと思います。防音工事や騒音計の現状についてはどうなっているのか。これもお伺いしたいと思います。","respondent":"稲田都市開発課長、鈴木都市計画課長","answer":"この再開発事業は、東京都、国というところと協議しながら実施してきているところでございまして、品川区の活力等をつくっていくために、今現在、引き続きやっているところです。ただ、区民不安の払拭のために、区としては、これまでどおり、今後も国のほうに丁寧な説明あるいはさまざまな取り組みを求めていくです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"羽田の問題については、やはり非常に重要な、区民生活にかかわる問題ですし、建設委員会の所管でもありますので、特に説明会は区と国が共催でやっているわけですから、いろいろ立場はあるにしても、できる限り、計画の現在の現況はどうなっているかという情報提供というのは、しっかり、今まで以上に、これに載らないと困ると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"今日は大枠ということなので、確認だけさせてください。社会実験として始まったということは認識しているのですけれど、これはいつまでの実験で、いつ検証されるのかということを確認させてください。この事務事業概要から、その辺のことは読み取れないので、確認させていただきたいというのが１つ。何を基準とした２２.６％なのか。その辺の数字の確認をさせてください。","respondent":"今井土木管理課長、溝口公園課長","answer":"ですので、社会実験の期間は、今は延長して今年度までという形になっているところです。今後、１０区との連携の中で、社会実験から本格実施ということで移行する中で、課題等をまた整理していきたいと考えています。私からは、水とみどりの基本計画・行動計画に関する目標としての数値の関係についてご説明します。みどり率の関係で２２.６％を目標にしておりまして、平成２６年現在の数字が２１．４％です。","id":"exchange-005"},{"speaker":"吉田委員","kind":"確認","question":"自転車のほう、確認できました。ということは、当初１年で始まったものが、社会実験というのが３年に延びていくということは、その検証というのは次年度の事業になると理解してよろしいのでしょうか。それから、みどり率についてです。その辺をお聞かせください。","respondent":"今井土木管理課長、溝口公園課長","answer":"社会実験に伴う効果検証につきましては、平成３０年度、昨年度、実施したところです。緑率の考え方です。公園については、全てみどり率の中の計算に含まれるような形です。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"最後にそれだけ確認させてください。みどり率のほうはわかりました。これはあくまで事務事業概要を伺った感想というレベルでいいかと思うのですが、みどり率という考え方は、全体の緑ということで考えると、何となく納得がいかないというところがありますので、それはこれからの個々の事業の中で意見を述べさせていただきたいと思います。","respondent":"今井土木管理課長","answer":"今ご指摘のとおり、一旦、効果検証で課題等は見出しておりますので、区内への全域展開する中で、今年度、引き続き区内全域の拡大および他区との連携を含めて検証するということで進めてまいります。","id":"exchange-007"}]},{"id":"topic-03","title":"区立荏原児童遊園の一部廃止","agenda":"区立荏原児童遊園の一部廃止","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと、同じ２番のところ、最後の文章、読んでいてわからなかったといいますか、特定整備路線の目的が書いてあって、「整備の早期実現および地域住民への理解につながる」というのが、ちょっとわからなかったので、これはどういう意味なのでしょうか。お伺いします。","respondent":"鈴木都市計画課長","answer":"やはり、今回、町会の移転等がありますので、区としても公共性の高い町会の取り組みに対して協力する形で、一方で、あわせて特定整備路線の重要性・必要性についても、理解が深まる、周知が進むというところで、書かせていただいたです。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"最後のところが、ちょっとわからなかったのですけれども、今回、町会という、非常に地域のコミュニティ形成に当たっては重要な団体だと思いますけれども、その町会会館が放射２号線にかかるということで、その代替地を品川区が児童遊園の中に確保してあげることが、道路そのものの整備の理解につながると、今おっしゃったように聞こえたのですけれども、それは、そういった目的もあって。","respondent":"鈴木都市計画課長","answer":"それから敷地についてですが、基本的には、町会が求めるからといって、要求するだけ幾らでも町会に区有地を、それは、まず東京都にということなのですが、そういうことではなくて、やはり現有の町会の建物が建つ同程度の規模の土地を、結果的に、９２平米ですが。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"町会会館が移るにしても、新たに大きなお金を払わなくてはいけなくなった場合というのは、かなり大変ではないかと思うのですけれども、その辺の持ち出しの関係はどうなのかということもお伺いしましたので、後でお答えください。この地域の住民の方々にとっては、この道路の必要性など全く理解できないところですし、しかも一度も自分たちがこの土地に、何というか、この事業が、道路が必要ですか。伺います。","respondent":"鈴木都市計画課長","answer":"これとセットで周辺の木密の解消ですとか、あるいは沿道の用途地域の見直しですとか、そうした総合的な対応の中の一つとして、区としては本当に必要な事業だと認識しておりますので、今回のようなケースで、今。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"もう二、三、お伺いします。こういったことをやろうとしているわけですけれども、区民の財産、児童遊園を、地域で公開、届け出している町会とはいえ、一団体に払い下げるということになるわけですけれども、児童遊園を含めた利用者を含めた区民・住民への説明責任の果たし方、あと合意形成の仕方はどうするのでしょうか。どのようにお考えなのかお伺いしたい。伺いたいと思います。","respondent":"鈴木都市計画課長、溝口公園課長","answer":"１点目の近隣周知ですが、基本的には通常の、例えば公園整備あるいは改修工事等を行うときの一般的な近隣周知ということを今回考えてあります。決して、町会だからといって好き勝手に使っていいということはありませんし、これまでもイベントや町会行事といったものについては、しっかりと公園使用の許可を出しながらやってきているところですので。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"私は、児童遊園というのは昔から不特定多数の人が自由に使っていたわけですから、しかも、私は立場が違いますけれど、この道路が早期に整備するのにどうしても必要ですというお考えであるならば、当然、そういったことをしっかりと住民に説明する説明会というのが必要だと思いますけれど、それをなぜやらないのか。具体的に周知とは、今、どういうふうにしていこうと思っているのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"これは今、具体的に説明会という話をいただきましたが、今回、都市計画課、公園課の両課関連案件として私からご説明していますが、都市計画道路、特定整備路線の工事自体、都市整備自体は東京都の事業ですから、今回、主体的に説明すべき周辺の方にお知らせすべきは、閉園と。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"そして狭くなるというのは、紛れもなく放射２号線という事業が理由なわけですよね。こんなので本当にいいまちになるのですか。私はおかしいと思います。東京都もやるのですか。やらないか、やるのか、それを求める考えがあるのかお伺いしたいのと、最後に、品川区としてぜひ、今回の件に関しては、近隣の方や地域の住民も自由に参加できる説明会を開いて周知してほしいと思いますけれど、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"今回の児童遊園の閉園・縮小に関しては、これまでの公園整備の手続と同様に、周辺にチラシを直接ポスティングさせていただいてお知らせして進めるという形で考えておりますので、個別に説明会を区として行う考えはございません。","id":"exchange-013"},{"speaker":"松本委員","kind":"意見","question":"いずれにせよ、この計画が進んでいくと、児童遊園地の敷地が狭くなる。これは、住んでいる人たちからすると、利用できるスペースが狭くなるということなので、売却時期としては、できるだけ遅ければ遅いほうがいいと思うのですけれども、なぜ今の時期にこの計画というか売却という流れになったのかというところをご説明いただければと思います。","respondent":"鈴木都市計画課長","answer":"事業に協力して土地は売ったはいいけれど、行き場所がないと、これは町会の方も会館がないという中で長時間過ごさなければいけなくなるわけですから、やはり移転先の確保が前提で、この東京都との道路内の交渉が進むということですから。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから移転先を探していた。それが確保できることが、もうわかるわけですから、私も同じように、何で今でないといけないのか。その辺の、なぜ今なのかというのを、今お答えを伺いましたけれど、ちょっと理解できないのでもう一回教えていただきたい。そういうことも考えて、やはり説明会を開かれたほうが事がスムーズに運ぶのではないかと思うのですが、その辺についてのお考えを教えてください。","respondent":"鈴木都市計画課長","answer":"これは直接ポスティングをして説明をしてきているわけですので、この案件も同様の案件として、何か説明会を開いて行うというところは、区としては考えていないです。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問・要望","question":"区のお考えということで、これについて、これ以上続けても水かけ論になってしまうかと思いますので、区の考えを確認させていただいたということですが、この間、公園の問題だけではなくて、さまざまなところで品川区の事業がいきなり決定事項として知らされて、あげくに説明会を開いたとしてもすごく紛糾してしまうとか、そういうことが起きております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-04","title":"天王洲地区における景観形成基準（案）","agenda":"天王洲地区における景観形成基準（案）","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"景観形成基準の地区の範囲内の地権者の数についてお伺いします。土地所有者、借地権者、あるいは企業と住民の内訳について伺います。ぜひ参加したかったのですが、議会へのご報告はあったのかという確認と、当日の参加人数と主なご意見、何人ぐらいの方が来て、大まかにどんなご意見が出たのかというのをお伺いします。","respondent":"鈴木都市計画課長","answer":"地域内の居住者の方ですが、おおよそになりますが、居住者が３００名程度、事業者を含む地権者になりますが１５０社です。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"それと、説明会について、ちょっと今伺いましたけれども、当日の様子というのはやはりすごく気になるというか、知りたいのですけれども、どういった方がどういう意見を言ったのかというのは大体あれだったのですけれど、もう少し資料みたいなものをぜひ追加でいただけないか、書いてほしかったと思いますけれど、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"当日の説明会の様子ですが、冒頭の説明でも説明させていただきましたが、この地区内には、これまで勉強会の様子は全て、まちづくりニュースを作成して、先ほど申しました３００人あるいは１５０社の方に、郵送なりポスティングによって、毎回お知らせをさせていただいてあります。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"確認だけさせてください。だけれども、東京都も小池都知事になって、それをやめてくれるのかと思ったけれども、やはりそれは維持していくのだということがあって、それなら少し規制緩和をしてほしいという努力をずっとしてきて、これは品川区も一生懸命やってくれて、これが実ってきたというのは、大変感謝しています。だから、それをもっと活かしていきたい。その辺の意気込みだけ教えてほしいと思う。","respondent":"鈴木都市計画課長","answer":"まさに天王洲地区の取り組みについては、委員にご紹介いただいたように、このまちが市街地として形成していく過程で、当初から地域の団体の方にお集まりいただいて、自主的にいろんな検討を重ねていただいて、ここまで来ているというところは、しっかり区としても認識しています。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問・要望","question":"パブリックコメントに関しては、ここは建設委員会ですので、建設委員会に限ったことで言わなければいけないのだと思うのですけれども、いろいろなことで、パブリックコメントの前にいきなり資料をでんと出して、これに対してコメントを出してくださいという求め方は、いささか乱暴なのではないかということを、生活者ネットワークとしては意見を申し上げております。そのことを１点伺います。","respondent":"鈴木都市計画課長","answer":"説明会は５月３０日ということで、このペーパーの冒頭に、開催はもうそのとき決まっていましたので、入れるべきだったというところは申しわけございませんでした。","id":"exchange-020"}]},{"id":"topic-05","title":"令和元年６月区民住宅（空き室）入居予定者登録募集","agenda":"令和元年６月区民住宅（空き室）入居予定者登録募集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"このことを伺うと、今後の方向性を検討しているというお答えが返ってくるのですけれど、最新の検討状況は、どういうところで、どなたが何を検討されているのか、その状況をお伺いしたいと思いますし、またそういったものは大体いつぐらいに報告される見通しなのか、その辺がわかれば教えてください。","respondent":"森住宅課長","answer":"区民住宅のあり方につきましては、今現在、使用料でありますとか、あるいは効率的なＰＲであったり、そういった部分も含めて中長期的な方向性を検討し、昨年度までで検討の委託自体は終わっているのですけれども、現在、その中身について庁内の調整を進めているところです。","id":"exchange-021"},{"speaker":"安藤委員","kind":"意見","question":"委託ということもあるのですけれども、そういったデータがあった上で、やはり区の判断というのはすごく大事だと思うのですけれども、やはり若い世代や子育て世代にとって、品川区内の住宅問題というのは大変深刻といいますか、家庭の支出に占める割合が多くて、なかなか品川区に住み続けられないという問題もありますので、これまでの家賃補助はなくなってしまいましたが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"}]},{"id":"topic-06","title":"清掃車による事故","agenda":"清掃車による事故","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"本当に、あってはいけない事故ということで、かなり東京二十三区清掃協議会でもしっかりと安全対策を指示されたということなのですけれども、もう皆さんもご存知のとおり、２日ぐらい前ですか、五反田駅で品川区の事業をやっていらっしゃるのかわからないですが、清掃車がバスと衝突して、運転されていた清掃事業者の方が亡くなったという報道があったのですが、直接この議題ではないのですけれども。","respondent":"工藤品川区清掃事務所長","answer":"こちらは、私どもも情報収集しましたところ、一般廃棄物を取り扱っている事業者でございまして、私どもの品川区でも３００社ほど許認可しています。この事業者は東京２３区の中で２０区から許可を受けている業者です。","id":"exchange-023"},{"speaker":"たけうち委員","kind":"質問・要望","question":"そうすると、こちらは一般廃棄物ということで、いわゆる事業所を中心とする、直接区で委託して収集をお願いしているのとは少し違うという認識でいいのですよね。やはり続いているような感じに、我々からすると思ってしまうので、その辺がわかれば教えていただきたいと思います。","respondent":"工藤品川区清掃事務所長","answer":"私どもも東京二十三区清掃協議会で一律で許認可しておりまして、それぞれ２３区の中で事業を行う区への許認可を受けているです。","id":"exchange-024"},{"speaker":"吉田委員","kind":"確認","question":"今のご報告とか、このたびの５月６日の事故のご報告、まだ調査中ということで、責任の問題など、これからきちんと確定していくと思うのですが、改めてそういうことについては、事が決着してから改めてご報告などというものをしていただけるのでしょうか。そこだけ確認させてください。","respondent":"工藤品川区清掃事務所長","answer":"報告につきましては、なかなか示談というところもかなり時間を要するという部分ですので、そういった中でもう一度、どのような形でやるのかというのは検討してまいりたいと考えております。","id":"exchange-025"}]},{"id":"topic-07","title":"大井町駅前公衆便所改築工事","agenda":"大井町駅前公衆便所改築工事","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それに少し戸惑う方に対しての配慮というのですか、サインみたいなものはどのように考えているのか。それを実現させる上での管理体制というのはどのようになっていくのでしょうか。新しいトイレだけに、ほかと同じですよということなのか、それともちょっと特別な体制でやっていきますよということなのか、その辺の管理体制についてお伺いしたいと思います。","respondent":"溝口公園課長","answer":"これにつきましても、清掃回数を、３回で対応していきたいと思いますが、利用状況といったものを考慮しながら、これについては引き続き考えていきたいと思っているところです。","id":"exchange-026"},{"speaker":"松本委員","kind":"確認","question":"今のトイレのジェンダーフリーのところです。対応されていくというふうなお答えだったかと思うのですけれども、少し確認といいますか、ジェンダーフリーの中でも、おむつ台のトイレについては、最近、男性がおむつをかえる際に、やはり場所がないという話がよく話題になっているところです。そこに特化して、Ｄ棟のおむつ台は、男性も利用できるというところだけ、確認できればお願いします。","respondent":"溝口公園課長","answer":"Ｄ棟もそうなのですが、Ａ棟から、今回、だれでもトイレのＦ棟まで６棟建てますけれども、基本的に男女誰でも使えるような形での運用をしていきたいと考えているところです。","id":"exchange-027"}]},{"id":"topic-08","title":"区職員の防災服のリニューアル","agenda":"区職員の防災服のリニューアル","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"今回のリニューアルに係る経費は幾らになるのかというのが１つです。それと、今回のリニューアルの理由ですけれど、五輪開催を契機にとあるのですけれども、それだけなのか。というのは、リニューアルの動機というのは何だったのか、改めて、例えば区民の方から要望があったとか、あるいは職員の中から使いにくいという声が上がったとか、もう少しリニューアルの動機について伺いたいと思います。","respondent":"中島防災課長","answer":"経費につきましてですが、現状、防災服が４,６２３着の予定でございまして、経費につきましては約９,０００万円を見込んでいるところです。","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問","question":"すごく単純な質問なのですけれど、反射材が使われているということだったのですが、どの辺に使われているのか。ちょっとこれだとわからないのです。それで、実際、夜などで見え方がどう変わったとか、一般の方からどう見えるとか、何か実験的なことはされたのでしょうか。その辺を伺いたいと思います。","respondent":"中島防災課長","answer":"こちらに、反射材を用いてあります。品川区の区章および「品川区」の文字も反射材を表と裏に使っております。特に実験等は行っておりませんが、専門の業者等にも確認いたしまして、こちらを採用したものであります。","id":"exchange-029"}]},{"id":"topic-09","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"やはりこういう計画だったらどうなのだという判断ができると思いますので、そういった羽田新ルートの問題を１点、調査したいというのがあります。既に走らせているところというのが都内でもたくさんありますので、そういったところの事例研究なども参考にしながら深めていく必要があるのではないかということで、提案させていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"たけうち委員","kind":"提案","question":"１つ目は、ずっとこの間やってきていますけれども、防災対策で、細かい内容については、避難行動要配慮者というのか、その方たちの個別支援計画をつくりながら、町会等でもバックアップ体制をやっていますけれども、ここがなかなか進んでいかない状況もあるかと思うので、その件とか。は水辺も引き続きやってもいいかなと思うのですけれども、その３つを提案したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"意見","question":"１点だけ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/248410?Template=document&Id=4260#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":55658,"voices":159}},{"id":"r01-20190610-9","meetingId":"r01-cm06","date":"2019年6月10日","dateIso":"2019-06-10","committee":"文教委員会","time":"午後 １時００分～午後 ３時５５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"品川改革連合の筒井ようすけと申します。どうぞよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"職員配置のところで、どこが増員され、また減員されたということで、今回特に重点を置くといいますか、配置の面でどういったことをやっていこうかというところでの考えがありましたら、伺いたいと思います。会議の際、よく声が聞こえないというお話も伺いまして、ぜひマイクの使用ですとか、そういったことも考えていただきたいと思うのですけれども、いかがでしょうか。","respondent":"有馬庶務課長、大関教育総合支援センター長","answer":"庶務課についてご説明いたしますと、６ページで書いてあるところの学校施設計画係と、その下の学校施設整備担当（主査）というところが、大体５、６名程度の増強になっていることと、ここに担当課長がついているです。なお教科書採択に関連する、教科書の見本の展示ですが、既に先週より特別展示がスタートしておりまして、その後法定展示を６月末まで予定しています。広報紙およびホームページ等でお知らせはしています。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと今回この説明会が行われていると思うのですけれども、この制度変更に当たって、どういった形で周知がされたのか、伺いたいと思います。聞いたところによりますと、関係のある家庭にも知らせが届いていなかったというお話も聞いているので、とりあえずどういった形でされたのか、ぜひ関係する方にはお知らせが行くようにしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"若生学校施設担当課長","answer":"は未就学のお子様については各幼稚園、保育園、これは区内の私立、公立ともですけれども、同じタイミングでパンフレットと同時に、４歳児、５歳児を対象に説明会を行いますというお知らせのチラシを同封して、配布をお願いしたところです。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"わかりました。説明会のほうは対応されているということですが、しっかりと行き届くようにやっていただきたいと思います。そこをスクール・サポート・スタッフとかを入れて、少しずつ先生の仕事を減らしているとは思うのですけれど、やはりもともとの授業量を減らすですとか、教員を増やしていくということが一番重要なことかなと思っているのですけれど、お考えをぜひ伺いたいと思います。","respondent":"工藤指導課長","answer":"今、ご質問いただきました教員の働き方改革です。実際に取り組みとして行っているところは、ご指摘いただきましたように人的な支援につきましてはスクール・サポート・スタッフを、今年度から全校配置ということで行っているところです。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"教員の増員については、国などにも求めていくということでした。やはり国の配置の部分も変えていかなければいけないところもあると思いますので、ぜひ要望していただいて、品川では固有教員もいますので、そういったところで少人数学級にしていくということでも、子どもと接する時間が増えていき、本来の業務をしていくことができるというふうになると思いますので、そういったところも考えていただいて。","respondent":"工藤指導課長","answer":"今手元の資料で……、平均８分ということでお話ししましたが、すみません、後ほどご提供させていただければと思いますが、よろしいでしょうか。","id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"質問","question":"５年度以降はどうなのでしょう、はっきりわからないわけですけれども、５年度までで切るとすると、現状ここにある学校の改築のみということで、よろしいでしょうか。それと、その先の予定等はもう少し先にならないとわからないのでしょうか、ということです。もう１つは、１６ページの空調設備ですけれども、これは簡単で結構です。","respondent":"若生学校施設担当課長、有馬庶務課長、工藤指導課長","answer":"今年度も新たな改築校の検討を進めているところですけれども、選定については秋以降。ということで、２学期から使えるようにしたいというところが、大まかなスケジュールです。再任用の管理職の数については、後ほどお答えします。お願いいたします。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問・要望","question":"老朽化した学校を新しくしていくという中で、長寿命化計画というものが一方であると、どういう位置づけでこれがあるのかというところもご説明いただきたいと思います。最後に、これは簡単ですが、屋内運動場の空調設備で、工事による学校というのが４つあると、基本的にはリースが多いのですけれど、工事という選択をした理由はどういうところにあったのか、お伺いしたいと思います。","respondent":"有馬庶務課長","answer":"それから空調設備につきましては、基本的に工事は地元の事業者に頼むのが原則という考え方もあると思いますけれども、短期間で一気に各学校に整備していきたいということもありまして、リース会社でどのぐらい対応できるかということで。","id":"exchange-007"},{"speaker":"塚本委員","kind":"確認","question":"そういう中でちょっと気になるのは、二重投資のようなことにならないように。改築したかったけれども長寿命化してしまったから改築はやめましょうかというような、直接二重投資にはならないかもしれませんけれども、本当だったらもう少し早く改築できたのにという、そういうことへの懸念は、ないでしょうねという確認なのですが。","respondent":"有馬庶務課長","answer":"そうはいっても、屋上防水、雨漏り等の影響があったら１０年ごとに大体やっていくという過去の履歴も見ながら、ここである程度やらなければいけないというとき、あとはどの程度まで、応急措置にするのか、全面改修にするのかということもいろいろ。","id":"exchange-008"},{"speaker":"筒井委員","kind":"確認","question":"今の屋内運動場の空調設備整備のことですけれど、原則は工事による設置で、今回工事する４校以外は順次、最終的には全校工事をして設置していくということなのか、その確認と、また大型備品とか備品による設置というのは具体的にどのようなものか、工事とリースとの違いをお知らせください。この工事による設置は、なぜこの４校が選ばれたのか、お知らせください。","respondent":"有馬庶務課長","answer":"リースと今後整備する学校ということですけれども、先ほど言ったようにリースという方法は短期間で一気に入れていきたいということで、今回選択しましたけれども、今回備品で対応する学校については、工事での設置というふうに考えております。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問","question":"４３ページから４４ページ、ひきこもりの相談拠点を今年度実施するということですけれども、これは資料を読むだけではフリースペースでやるのかと思ったのですが、どういった形で進められているのか、伺えればと思います。そういったことを区ではどう考えていらっしゃるのか、今後どうしていくかというところを伺いたいと思います。","respondent":"廣田子ども育成課長","answer":"フリースペース、ひきこもりの相談ですが、お尋ねは４４ページの新規の事業のほうということだと思いますけれども、今現在は社会福祉協議会が持っているスペースの中で、相談を受ける事務局側の拠点という形で今はスタートして、講演会。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"わかりました。部屋のことは、教育委員会と相談して着手し始めたということで、ぜひ子どもたちが元気に遊べるというか、健やかに育つような環境をつくっていただきたいと思います。その後、その対応はどうなっているのか、伺えたらと思います。放課後等デイサービスの利用枠が広がったので、それで解決しているのかもしれませんが、どうなっているのか伺えればと思います。","respondent":"廣田子ども育成課長","answer":"一般論として、支援とか配慮が必要なお子様が来た場合には、加配をつけて親御さんと相談して、ということではあるのですけれども、迎えに関しては普通のお子さんと同様に行うという対応は私も認識しているのですけれども、まだ４月に異動して来たばかりで。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"では状況把握をしていただいて、ぜひ検討していただければと思います。今回の事件を受けて、検討したこととか変更点などありましたら、伺えればと思います。そういった中で、保育の質が担保されるのか危惧しているのですけれども、区の認識として、そういう状況をつかんでいらっしゃるかということと、今後どういった対応を考えていらっしゃるか、伺います。","respondent":"吉田保育施設調整担当課長、佐藤保育課長、大澤保育支援課長","answer":"区では、道路課、土木管理課、保育課、保育支援課と連携を図りながら、近隣の４警察署とも調整をとり、実際に危ないと思われる場所等のチェックをし。都の検査に対して、身近な自治体ということで立ち会いをしているというものでございまして、東京都のほうは体制を強化しているとは聞いておりますけれども。職員については経験とか年齢をバランスよく配置していただくように、事業所にはお願いしていますけれども、保護者の方から不安の声があったような場合は。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"職員の退職は、声があったときにやるということでしたので、しっかり運営されるように、やはり一遍に保育士が退職してしまうことになると、保育の質の問題にもかかわってきますので、そういったところもチェックしていただいて、質を高めていくようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"横山委員","kind":"質問","question":"４３ページの子ども若者応援フリースペースについてですけれども、平成３０年度の４月から６月までの延べ人数と、７月から３月までは電話相談件数が増やされているのですけれども、こちらは面会以外に例えば電話ですとかメールであったり、ＳＮＳ等も問い合わせの窓口としてあるかと思うのですが、相談件数の実績というところをどのような感じで、詳細がもしわかりましたら、教えていただけたらと思います。","respondent":"廣田子ども育成課長","answer":"７月からということなので、分けて計上しているのですけれども、詳細についてはまだ、平成３０年度は週３回だったのを、今年度はもう２日増やすとか、まだ流動的なところがあり、今後はしっかりと分けた検証をしなければならないので。","id":"exchange-014"},{"speaker":"横山委員","kind":"確認","question":"今回、７月から始まったということで、実績の出し方もこれからやっていただく段階ということで、確認させていただきました。子ども・若者を応援するようなフリースペースということなので、面会だけではなく電話ですとかＳＮＳなどの対応というのも、実際にやっていらっしゃると思うので、そのあたりも実績としてどのように出していくのか、ぜひ検討していただけたらと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"塚本委員","kind":"提案","question":"質問というか、提案なのですけれど、資料のことですが。平成３１年４月の待機児童は、先ほど１２人ということでご説明をいただきました。これは委員会でお諮りするような話かもしれません。ご検討いただきたいと思いますが、いかがでしょうか。","respondent":"大澤保育支援課長","answer":"年齢別の申し込み状況を、資料として出すことは、必要であれば。","id":"exchange-016"},{"speaker":"横山委員","kind":"提案","question":"資料の提出のご提案が今ありましたけれども、委員会として今後の所管事務調査であったり、内容によって深く議論をしていく必要があるのであれば、検討していきたい、議論していきたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"のだて委員","kind":"意見","question":"詳しい資料が出てくると、また議論も活発になると思いますので、必要と。お願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問","question":"保育課をはじめとした担当の方が、待機児童をなくそうとしていろいろ政策をされて、その結果、先ほどの説明のとおり、１２名ですか、昨年度より減となっているわけですから、そういったことがわかるような具体的な資料をもって、その政策の成果が話し合えると思いますし、また年齢によってでこぼこがあることについて、どういうポイントで今後どうしたらいいかという議論にもなると思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"筒井委員","kind":"意見","question":"すまいるスクールでは、午後５時を超えて時間延長する児童に間食を提供するということですけれども、間食ということで、子ども食堂はもちろん食事の提供もされていると思うのですけれども、すまいるスクールも、利用料がかかるとか、条件でその学校の在籍児童に限るということがありますけれども、内容は勉強とか、フリータイムなどの居場所づくりということからすると。","respondent":"廣田子ども育成課長","answer":"その状況はちょっと把握しておりません。子ども食堂に行く場合も、すまいるスクールからいったんおうちに帰ってから、行くことになるかと思いますので、把握はしておりません。","id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"意見","question":"２５ページのすくすく赤ちゃん訪問事業ですけれど、所管がまたがってしまうので、答えられる範囲でお尋ねしたいのですが。このようにして赤ちゃんを把握していくということですが、把握率や訪問率、特に８０数％というところで、１００％に近づけるためにフォローする検診等があるのですけれども、最終的にどういった形で把握をしていっているのか。","respondent":"廣田子ども育成課長","answer":"最初にご説明したとおり、最初は保健所で乳児の訪問をします。訪問できなかったものが児童センターに上がってきまして、訪問して、「面会できました」ということはフィードバックします。","id":"exchange-021"},{"speaker":"せお委員","kind":"質問・要望","question":"二つお聞きしたいのですが、１点目が児童センターで、３７ページに利用状況の表があるのですけれども。その明らかな理由がありましたら、お教えいただきたいと思います。２点目は、各種手当で、児童手当だったり、児童育成手当、障害手当、児童扶養手当、特別児童扶養手当、こういった手当の対象児童の養育者の方に、現在どのようにお知らせをしているのか、お聞きしたいと思います。","respondent":"廣田子ども育成課長、三ッ橋子ども家庭支援課長","answer":"児童センターの利用ですけれども、平成２８年度からすまいるスクールが利用の延長を午後７時までできる形にしたので、児童センターにもよるのですけれども、小学生の利用がぐっと減ってしまったというところで。例えば年齢によって大分違いますので、１８歳未満の方、１５歳未満などの場合もあります。お知らせはしています。","id":"exchange-022"},{"speaker":"芹澤副委員長","kind":"質問","question":"すみません、聞き逃していたらあれですが。６５ページのひとり親家庭パソコン教室についてですが、平成３０年度は実績なしということで、これはなぜ昨年やっていないのかというところと、この事業は就労機会を得やすくするために、ひとり親家庭の自立促進を行っているということで、パソコンの操作の技術というのは、例えば何を教えていらっしゃるのか、お伺いできればと思います。","respondent":"三ッ橋子ども家庭支援課長","answer":"つけ加えまして、平成３０年度につきましては、講座の認定はしたのですけれども、こちらに関しましては要件がさまざまありますので、支給できなかったという状況です。","id":"exchange-023"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"筒井委員","kind":"質問・要望","question":"バランスのとれた所管事務調査というのを望みますけれども、特に来年、東京２０２０大会を迎えるということで、オリンピック・パラリンピックに関連した教育ということをぜひやっていただきたいということと、昨今児童虐待が増えていますので、児童虐待防止についての調査を行っていただきたいということが、要望としてあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/810051?Template=document&Id=4968#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":50166,"voices":128}},{"id":"r01-20190610-5","meetingId":"r01-cm06","date":"2019年6月10日","dateIso":"2019-06-10","committee":"総務委員会","time":"午後 １時００分～午後 ５時１０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を72件抜き出しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"簡潔に３点伺いたいと思います。１点目は公契約条例について。３点目は性的マイノリティについて、同性パートナーシップ制度について、それぞれ伺いたいと思います。公契約条例ですけれども、既に要綱の話から、前年度の総務委員会でも報告がありましたけれども、今後のスケジュール、いつの定例会で条例として提出をする見通しなのか、そのスケジュールを伺いたいと思います。","respondent":"立木経理課長","answer":"そちらの情報収集、分析をいたしまして、今年度、公契約条例につきまして検討をしていく予定ですが、具体的なスケジュールに関しましてはまだ現在のところしっかり固まっておりませんので、またそのスケジュール等が固まりましたらご報告させていただきたいと考えています。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"４月から要綱で実施して、情報収集・分析をされているということですけれども、今後この条例化に向かって、まずは建設業組合の意見の聴取はもちろんのこと、その条例策定に向けた策定委員会を設置してはいかがかと思いますので、見解を伺いたいのと、それと今回の公契約条例は、その検討経過もしっかり議会に報告していただきたいと考えています。","respondent":"立木経理課長","answer":"検討の進め方につきましてもいろいろな手法があると思われますので、それぞれ検討しながら、議会とも連携をとりながらやらせていただきたいと考えています。賃金等の内容につきましては、また今後の検討課題とさせていただきたいと考えています。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"２３区の中でも、区長や議会が臨界前核実験に対する抗議を行うなどの対応を行っておりますが、この間、品川区の対応は臨界前核実験については抗議をしないという対応をとってきておりますが、やはり非核平和都市品川宣言３５周年事業という節目もありますし、核兵器のない世界をつくる上でも、しっかり臨界前核実験への抗議を品川区もすべきではないかと思いますので、この点、伺いたいと思います。","respondent":"立川総務課長、島袋人権啓発課長","answer":"品川区としましてどう取り扱うかにつきましては、今後とも研究してまいりたいと思います。性的マイノリティの方々への対応ですけれども、まず「マイセルフ品川プラン～誰もが自分らしく～」という、この４月からいよいよ施行させていただいているところなのですけれども。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"様々情報を集めて、こちらも進めていただきたいと要望したいと思います。私はぜひ変更していただいて、非核平和都市品川宣言にあるように、あらゆる核兵器、あらゆる核実験、全ての国に対して抗議を示し、核兵器のない世界へ品川区としても力を尽くしていただきたいと思いますが、最後その点だけ確認させていただきたいと思います。","respondent":"立川総務課長","answer":"指摘いただいた点につきましては、いわゆるどういった観点からそういったご主張をされるかについて研究していきたいという趣旨で言っております。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっと教えていただきたいのが、企画部の４ページに(3)主要事業の進行管理というのがあります。まだであればその整理をしていただいて、やはりその枠割分担、二重である必要はないと思っているので、役割分担をしながら、全体的な視野を私たちも総務委員会の中でやっていきたいとは思っているのですが、そのお考えを教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"西本委員","kind":"意見","question":"おいおいいろいろ報告されると思いますので、お願いいたします。なので、この時間も含めて何をしなければいけないのかということは、総務委員会も行財政改革特別委員会のほうも、両委員長を中心にスピードをもっての審議をぜひともお願いしたいと思っていますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"つる副委員長","kind":"質問・要望","question":"企画部の情報推進課で、これは１点確認というかお願いなのですが、２４ページでご説明いたただいた、本年度４月からスタートしているタブレット端末を利用したビデオ型手話通訳のサービス、これは非常に当事者の方をはじめ好評だということは聞いている中で、これは所管として情報推進課が今中心となってやっていらっしゃると思うのですが、対象としては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-02","title":"品川区長期基本計画の策定状況","agenda":"品川区長期基本計画の策定状況","exchanges":[{"speaker":"田中委員","kind":"確認","question":"今後の予定の部分なのですけれども、１０月から１１月にパブリックコメント実施ということだったのですが、その前に区民の方への説明会というものは実施されないのかということを確認させてください。","respondent":"大野計画担当課長","answer":"今、ご質問の説明会の件ですけれども、現在のところ実施の予定はございません。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"これだけの量があると、やはり説明がないと、区民の方も示されただけで、何をどう読んでいったらいいのかということなども含めて、やはり説明というものは欲しいのかなと思います。特に長期基本計画で、とても区民の方たちにかかわることですので、ぜひ実施をしてほしいと思うのですけれども、いかがでしょうか。","respondent":"大野計画担当課長","answer":"区民の方への周知といったところにつきましては、主に区ホームページを活用しておりますけれども、そのほかにもツイッターですとか「しなメール」といったものも活用しながら、随時策定委員会の内容といった部分については、情報の発信をしっかりと行っているところですので。","id":"exchange-009"},{"speaker":"田中委員","kind":"意見","question":"その周知方法についてはわかりました。その丁寧な説明という部分で、できれば地域ごとでも開催してほしいほど、説明会が必要だと思いますので、ぜひ検討をしていただけたらと。それで、本当に品川区長期基本計画のことを区民の方が知って、こういう計画をもって進めていくのだなという自覚を持って区民としての生活ができていけるようにと思うので、ぜひ説明会の実施を検討してほしいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"今日のこの総務委員会資料に３回行われた主な意見というのがありますが、結局品川区の方針と同じ方向を向いている意見しか紹介されないのです。私は３回ともしっかり自分なりに考えて意見を述べております。なので、この資料のつくり方としてはこうした恣意的な編集をするのではなく、ぜひ委員会の様子がわかるように、総務委員会に報告すべきだと思いますけれども、いかがでしょうか。","respondent":"大野計画担当課長","answer":"委員の皆様全員からのご意見の詳細につきましては議事要旨のほうに載っておりますので、でき次第すぐにホームページ等を通じてアップしておりますので、そういったところで全員の意見といったところについては把握をしていただければと考えてるところです。","id":"exchange-011"},{"speaker":"中塚委員","kind":"提案","question":"今後分野別の審査に分かれますので、少し詳細には入っていくとは思いますけれども、ぜひ任期を延長して、参加している委員が認識も深まるし、また提案や今後１０年間の区政運営についての意見が言えるような環境整備をすべきだと思うのですが、いかがでしょうか。","respondent":"大野計画担当課長","answer":"任期を延ばしてはというようなご提案かと思いますけれども、基本的にはある程度皆様お忙しい中で来ていただいていることから、時間についても２時間というところがいわゆる闊達に議論できる限界かとこちらとしては考えておりますので、決まった任期の中で、決まった回数の中で。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回の長期基本計画にかかわらず、やはり上位計画、しかも今後１０年の計画ですから、十分な議論の保証をすべきだと思いますが、議論ができる環境として十分なのか、区の認識を伺いたいと思います。そうしたキャッチボールができる区政に、せめてそれくらい今からでもできることだと思いますので、検討していただきたいと思いますが、いかがでしょうか。","respondent":"大野計画担当課長","answer":"説明会のお話がありましたけれども、行きつく先としては区民の方の理解をどう深めていくのかといったようなお話かと考えていますので、その方法につきましては検討はしてまいりたいと考えていますけれども、現在のところ説明会の実施の予定はしていないというものです。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"だから、結構やはり共通認識をつくったり課題をつくったり、計画そのものに住民参加を位置づけることが、理解を深めていく第一歩だと思いますので、様々検討していきたいということですが、ぜひパブリックコメントにおける住民説明会は最低限やっていただきたいと思いますし、そもそもパブリックコメントにかけるものでなくても、いわゆる障害者計画だったり福祉計画だったり、様々な行政計画を立てる際には。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"西本委員","kind":"意見","question":"なぜかというと、この策定委員会の目的というのがあって、目的は区長の諮問に応じて、要は区長が設置をして、区長がこの長期基本計画を策定するに当たって、いろいろな委員会をつくって、そこで議論をしていただき、それをもとにして行政側が長期基本計画をつくっていくのですよという流れだと思うのです。そのための委員会だと思うのです。それはどう考えられていますか。","respondent":"大野計画担当課長","answer":"策定の進捗といったものについて、総務委員会の中でご報告をさせていただいているですけれども、その中で出た意見、これはいわゆる策定委員会の生の意見というものではございませんけれども、総務委員会の中でこういったご意見をいただいているといったところについては、委員長。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"そうすると、この総務委員会での意見、もしくはこれから定例会などもありますけれども、そちらからの意見をきっちり踏まえた形で、最終的な長期基本計画が計画されるという認識でよろしいのでしょうか。それから、この１０年間で新しくなった傾向の変化、非常にこういうところは１０年前と変わっているというところがあったら教えてください。それともう一つ、最後にこの資料の中に、リサーチ会社ですか。","respondent":"大野計画担当課長","answer":"こちらについても事実だと考えているところですので、新しい長期基本計画についてはまず１０年というところで進めまして、総合実施計画、それから予算といったところで中期、短期についてはしっかりと補完をしてまいりたいたいと考えているところです。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"この１０年がどうかということについては、これからちょっと議論をしていただきたいと思います。しかし、近年の状況を考えると、１０年ごとというのは遅すぎると私は思っているのです。だから、この会社で普段リサーチをしているものをお示ししたということであれば、それほどお金はかかっていないと思うのですけれども、どのぐらいかけてこれを採用しているのかなと思ったのですが、その点どうでしょうか。","respondent":"大野計画担当課長","answer":"資料作成の予算といったようなお話かと思いますけれども、こちらにつきましては、長期基本計画の策定の支援事業者ということで、平成２９年度より三菱ＵＦＪリサーチ＆コンサルティングと委託契約を結んでおりまして、平成３１年度の契約の中で行っているというものですので。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"これでもうスタートしてここに任せているのですよね。今日、これは報告事項ということだと思うのですが、総務委員会がそこまで、中まで入り込んでいいのでしょうかと私は思うのです。ほかの委員の方、お気持ちはよくわかりますけれども、これでもうスタートして多くの方が関係して、そこで議論が進んでいるのですから、それはやはり見守るべきではないかと思います。","respondent":"本多委員長","answer":"しかし、その会議体のあり方という性質は、須貝委員が今言っていただいたことがまさにふさわしいと感じておりますので、私も委員長としてよくその辺を認識しながら委員会運営をしていきたいと思います。","id":"exchange-018"},{"speaker":"中塚委員","kind":"意見","question":"今日はまず実質上初日の総務委員会ということで、１年間長期基本計画が進められているわけだから、報告が冒頭にあるのは当然だなとは思いますけれども、今後も様々な機会を捉えて議会に報告をし、議会としてもその内容や、私は審議委員ですので中身については当日言うということで、議論の仕方のほうだけしか意見は言いませんでしたけれども、それは意見は自由だと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]},{"id":"topic-03","title":"コミュニティＦＭ「ＦＭしながわ」の開局および区広報番組","agenda":"コミュニティＦＭ「ＦＭしながわ」の開局および区広報番組","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"災害時の対応に関しては若干ご説明がありましたが、防災無線と違って、ラジオですのでその聞き取りやすさや情報の発信量は全然違うというか、より多くのことをはっきりと伝えられるツールだと考えています。ただ、災害時はどのような番組表になるのか、どのような運用・放送になるのか、ちょっとそこを具体的にご説明いただけますか。","respondent":"木村広報広聴課長","answer":"実際は定時、例えば何時現在というような形で情報としては入ってくる場合もあると思いますが、災害ですので、緊急の、例えばここで避難所が開設されたというあたりをお知らせしたりとか、そういうときに随時割り込めるような形で、今放送局のほうとは契約を締結しておりますので。","id":"exchange-020"},{"speaker":"中塚委員","kind":"確認","question":"災害時様々役に立つように、今から準備するということはとても大事なことだと思います。どうしても夕方５時の夕焼け小焼けの音ではありませんが、日常的には時間のように感じ、実際はあれが災害時の音の発信の確認でもあるので、その双方が日常的に行われている、それがこのラジオでもできたらと思うのですけれども、いかがでしょうか。","respondent":"木村広報広聴課長","answer":"繰り返しになりますけれども、やはりその規模感、実際に例えば大災害ですと、ＮＨＫの場合ずっとやっていますけれども、それも情報としてはかなりいろいろな各種情報を切り替えながらやっているというところもありますので。","id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"参加型という、やはり区民の人たちが参加しやすいものとかをぜひともたくさんつくってほしいと思っているのですけれども、それを誰がどのように組み立てて、このＦＭしながわが運営会社ということなのですが、その中には専門家の方がいらっしゃるのか、要するにどのような形の予算立てになってくるのかということを教えてください。","respondent":"木村広報広聴課長","answer":"参加型の話につきましては、もうこの番組を考える時点から、どうやったら聞いてもらえるようになるかなというところで、例えばいろいろな催し物の現場に出向いて中継をしたりだとか、そういう形もできるよねという話もしながら。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"別にお金はかからないほうがいいですけれども、ただ、そういうことでやるならば、かけてもいいのではないかなという思いがあるので、それには予算額も当然必要なわけですが、どういうものを考えられるのかということ。そうすると、そういう人たちをお願いするとお金がかかるなという思いがあるので、そこら辺の予算化も含めて、お考えをちょっとお聞きしたいと思います。","respondent":"木村広報広聴課長","answer":"こちらのほうも、今、その番組の制作の中で、いろいろな方にお声かけをしながらやっていく中で、例えばそういう方とうまく結びついたらいいなと自分では思っているのですけれども、いろいろ区民の方への広がりの中で、そういうところも取り組んでいけたらと考えています。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"手弁当でということは非常に有効ですけれども、多分品川を応援したいという方々はたくさんいらっしゃると思いますので、そこはちょっとアンテナを張っていただいて、ぜひ知っていただくというのが一番大きな目標だと思うのです。知っていただく、聴いていただくということが第一歩だと思いますので、ぜひ進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"田中委員","kind":"質問","question":"ケーブルテレビ品川の制作番組とのタイアップということで、ホームページでもちょっと見たのですけれども、区立学校の児童・生徒の作文朗読ということだったのですけれども、どこどこの学校の何年何組のその生徒の名前というのが出てしまうと思うのですけれども、防犯面のほうでちょっとそこが心配だなと思ったのですけれども、そこら辺はどのようにされているのかお伺いしたいのですけれども。","respondent":"木村広報広聴課長","answer":"なので特定はできないような形にはなって、見る方が見ればというところはあるかもしれないのですけれども、そういう形で許諾をいただいてやっているです。","id":"exchange-025"},{"speaker":"田中委員","kind":"確認","question":"では確認ですけれども、このラジオでやるときも、その学校名だったり学年だったり名前というのは出てこないということで、大丈夫でしょうか。","respondent":"木村広報広聴課長","answer":"そのような認識で、よろしいかと思います。","id":"exchange-026"},{"speaker":"つる副委員長","kind":"質問","question":"ＦＭしながわの番組全体というのは、先ほどご答弁があったようにＦＭしながわのほうでしっかりと企画等をやっていただいているので、内容充実ということだと思いますが、その中で品川区がお金を出して予算化してやっている帯番組の「ほっとラジオしながわ」の充実というのは、先ほど西本委員からあった形で、これは品川区の中で図っていただくという理解でいるのですけれども、その中で。","respondent":"木村広報広聴課長","answer":"それと、土日につきましては、検討当初からは基本的に土日も放送を何らかやっていこうと。","id":"exchange-027"},{"speaker":"つる副委員長","kind":"質問","question":"もしこの番組の枠の中で広告を何かやった場合の収入というのは、品川区に入るのではなくてＦＭしながわに入って、放送の運営費になるのか、ちょっとその仕組みを教えてもらいたい。品川区としては、これは番組を制作するのでもう既にＦＭしながわに払っているわけですよね。その番組の中で広告を募集するというときに、どういう扱いになるのかというところです。そのあたりを教えてほしい。","respondent":"木村広報広聴課長","answer":"同じ日の、今まさに委員がおっしゃった生ワイドの中で取り上げられないかというところで、やはり放送局のほうからも打診があったのですけれども、ちょっと時間的に生放送の枠にどうしても間に合わずに放送できませんでしたけれども、教訓として。","id":"exchange-028"},{"speaker":"つる副委員長","kind":"質問・要望","question":"わかりました。そうしたところでチャンネル、周波数をそこに合わせておいてもらう。そうすれば、「あれ、何だこの番組」と興味になりますよね。８８.９の何かを皆さん考えてください」とかいうことでもやはり聴いていただく方が増えていくということになると思うので、そのあたりもぜひ考えていただきたいのですが、パブリックで聴くところと、何かあれば教えてください。","respondent":"木村広報広聴課長","answer":"そういうところもちょっと考えていきたいなと考えています。","id":"exchange-029"}]},{"id":"topic-04","title":"区ホームページでのチラシ・パンフレットダウンロード機能追加","agenda":"区ホームページでのチラシ・パンフレットダウンロード機能追加","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"お伺いしたいのは、新しいバナーをつくるということだったのですけれども、チラシ・パンフレットを求めている方がここで探すというのはよいと思うのですが、また左側の、例えば「保養施設ご利用案内」を検索したときに、その担当課のページに飛んだときに、そこには施設案内のＰＤＦのものはそこの担当課のページにはつかなくなるのですか。","respondent":"木村広報広聴課長","answer":"いわゆる各事業、各課のページで、イベントを紹介するときは、通例ですけれども、そのチラシ・パンフレットはＵＲＬでこう、それはそれでそこからも見られるように。その情報をこちらのほうで集約して、そちらからも行けるというような形で考えております。","id":"exchange-030"},{"speaker":"西本委員","kind":"確認","question":"確認ですが、イベント情報というのがカレンダーに載っているのです。全ての部のイベントの網羅はもうできたのでしょうか。以前にちょっとお願いして、なるべくイベントをそのカレンダーに集約してほしいとお願いしたのですけれども、それは全部こういう形で集約をし、さらにチラシ・パンフレットがダウンロードできるようになったという認識ですか。","respondent":"木村広報広聴課長","answer":"その承認の一番最後のとりでが私どものところでございまして、そこでイベントカレンダーの掲載がない場合は掲載をするような形にして出してはおるのですけれども、まだ本当に全部出ているのでしょうかというあたりの問い合わせが来ているところではありまして。","id":"exchange-031"},{"speaker":"西本委員","kind":"意見","question":"ちょっとお願いしたいのです。なかなか、これはあったよなといってもカレンダーを見ると書いていなかったりとかいうのが多いので、でもそこに全部集約すると入り方が簡単になるのです。なので、ぜひとも情報収集して、まとめていただけるようにお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"}]},{"id":"topic-05","title":"品川区西五反田二丁目付近再構築その２工事請負契約","agenda":"品川区西五反田二丁目付近再構築その２工事請負契約","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"辞退の理由を聞かせていただきたいということと、あと、こちらが勉強不足で申しわけないのですけれども、工事請負指名業者選定要綱とか、いろいろな要綱を読んだりしたのですが、事業の請負、公募の対象などがわからなくて、どのように公募されているのかという部分をお知らせください。","respondent":"立木経理課長","answer":"３ページの調書の中で、４社、今回入札に参加していますが、そのうちの番号の２番、３番、それぞれ辞退理由ですが、こちらは、配置予定の技術者、工事をするに当たりまして配置しなければならない技術者が手当てできないということで。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問","question":"概要書が書かれたことなどは本当によかったというのは思ったのですけれども、辞退理由なども書かれていれば、質問が１個減るという、もう少し具体的でよかったかなと思うのと、あと、公募の対象が下水道のということだったのですけれども、下水道のことを扱っている事業者のところに全て知らされるような公募方法だったのかというところなどが知りたいので、そこら辺をお知らせいただけますか。","respondent":"立木経理課長","answer":"辞退理由のところは検討させていただきたいと思います。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問","question":"登録事業者というのは、ちょっとわからなくて、勉強不足でごめんなさい。都の共同入札の仕組みということだったのですけれども、都のお知らせから、事業者がこの情報を知るということなのですか。品川区における共同企業体に対する建設工事の発注取扱要綱とはまた別で、どういう周知がされているのかというところだったので、もう少し詳しく教えていただけると助かります。","respondent":"立木経理課長","answer":"発注予定は、区のホームページでもお知らせはしております。実際に入札が開始ということで公告が出されますのは、共同運営というサイトがございまして、これは東京都内の自治体で共同で運営しているものなのですけれども、そちらのほうが入札の窓口みたいになっているところです。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどの公契約条例にもかかわって、現状は要綱ということで４月から始まっているのですけれども、今回、一番初めの契約だったので、こういう契約を結ぶに当たって、公契約要綱と言えばいいのですか、省略の言葉も逆に教えていただきたいのですけれども、要綱に基づいてどういう公告があり、区としてはどういうチェックというのか、判断、評価をしているのか。","respondent":"立木経理課長","answer":"そちらをいただいた上で、それを分析して、何か適合していないものがあればというところでチェックをしていくということになっております。要綱は区のホームページでも、チェックリストも登録はできておりますので、そちらのほうもご覧になれる状況になってあります。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういう状況なのかご説明いただきたいと思います。要綱に基づいて区は職種ごとの賃金を把握することになりますが、区が入札に当たって積算の根拠としている労賃、要するに、区の労賃と相手側が提出した労賃、そこに差が生まれている場合、逆に言うと、区のほうが高い、相手業者のほうが安いなど、差が生まれている場合などは、要綱に基づいて区はどういう対応するのか、伺いたいと思います。","respondent":"立木経理課長","answer":"労務単価と、今回、労働環境のチェックシートのほうで確認する賃金の部分の差につきましては、今のところ、情報収集をさせていただいて、もちろん最低賃金を割るというような部分に関しましては、私どもの権限ではないのですが。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"労務単価ですけれども、建築職人で最低賃金を割るなどということはあり得ないし、そもそも最低賃金を割るということは法律違反ですから、契約そのものが成立しない事態ですけれども、区が積算をしている労務単価と相手が申請してきた労務単価に差が生まれたときというのは、区で想定しているよりも安く使っていることが私は問題だと思っているのですが、区が例えば、一日２万円だと。","respondent":"立木経理課長","answer":"データの蓄積をさせていただいた中で、今後分析をさせていただければと考えているところであります。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"今の中塚委員の質問にもかかわるのですが、ということは、今のご答弁だと、実際は区の権限としては、労務単価が違っていた場合に何も権限はないのですということなのですよね。そうなった場合に、これは明らかに違法までいくのかどうかわかりませんけれども、積算して契約金額が出てくるわけですから、そこの根底が崩れてくる可能性もありますよね。","respondent":"立木経理課長","answer":"明らかな違法行為がない限りは、やはりそれは民民同士の契約ということになりますので、そこはあまり行政から言うところは、明らかに例えば社会保険に入っていないとかということは、当然私ども、適切にしなければいけないのですが、最低賃金等を守っている以上は。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"わかりました。次の件と重なってしまうのですけれども、先ほど辞退されている方々の理由の一つに、技術者不足ということがありました。それと、辞退されている方々は入札金額が出ていないのですけれども、これはタイミング的にはどういうタイミングで辞退されるという形で、ここに出ないのですか。それとも、辞退されているところについては金額は出さないという形になっているのでしょうか。","respondent":"立木経理課長","answer":"今回、４件ほど報告を出していますが、それぞれ工事案件に関しまして、それぞれの事業者のほうで、限られた人員の中でどういう配置をしていくか、どこに向かって入札をとりに行くのかというところがあると思われます。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問・要望","question":"それはそれで事業者の選択なので、仕方ないことなのかという思いはするのですが、いろいろな方々に入札をしていただきたいという思いがあるのです。これを見ると、決まっているところが多いので、ほかに頑張る事業者がいないのかという思いがあるのですが、その辺はいかがでしょうか。","respondent":"立木経理課長","answer":"公共工事、公契約の一つとして、事業者の経済的な部分のところもありますので、多くの事業者に契約をとっていただくのが一番望ましいと考えておりますが、やはり工事内容によりまして、できる事業者、できない事業者、それからあと、公契約、公共の工事だけではなく。","id":"exchange-041"}]},{"id":"topic-06","title":"品川区西五反田三丁目付近再構築工事請負契約","agenda":"品川区西五反田三丁目付近再構築工事請負契約","exchanges":[{"speaker":"田中委員","kind":"質問","question":"今、聞こえなかったのですが、４番の方の辞退理由はわかったのですけれども、１番の方をもう一度教えていただけますか。","respondent":"立木経理課長","answer":"資料７ページの調書の１番の会社の辞退理由ですが、こちらは、区が提示しております予定価格、こちらを事業者のほうで計算した工事の見積額が予定価格を超えてしまっているということで、入札しても落札できないということが、あらかじめわかったということで辞退をしているです。","id":"exchange-042"}]},{"id":"topic-07","title":"大崎橋広場改修工事請負契約","agenda":"大崎橋広場改修工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"技術者不足というのも情けないですよね。だって、たくさん業者はあるわけではないですか。品川区でその中の何社かということなのでしょうけれども、これだけ辞退云々という話が出て、本当に１社２社でやっていくなら、やはり枠を広げて、もっと入札できる人たちに参加してもらうという形にしないと、区民の方が見ても、納得できないのではないかと。ご見解を聞かせてください。","respondent":"立木経理課長","answer":"そういった中で、やはり指名入札ではないという中で、みずから希望で入札を出してきていただくという中では、４社、手を挙げていただいているのは、それなりにきちんと私どもの意図が伝わっているのかとは考えております。","id":"exchange-043"},{"speaker":"須貝委員","kind":"質問","question":"意見だけ言わせていただきますけれども、これではあたかも品川区は支払いが悪いから品川区の仕事は受けたくないような印象すら持たれてしまうのです。ですけれども、これでは適切な競争入札とは、どう見ても区民の方も見えないと思うのです。見えにくい。ですから、私は改善というものを、間口を広げるということもやっていかないと、恥ずかしいのではないかと思いますので、意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"}]},{"id":"topic-08","title":"大井町駅前公衆便所改築工事請負契約","agenda":"大井町駅前公衆便所改築工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"せめて点字ブロックをきちんとつけてほしいとおっしゃっていたのですけれども、点字ブロックをつけていただきたいのと、本当に多くの方が使っていたトイレの改修なので、とりわけ障害がある方への周知というのは、障害者福祉課とも連携をとって、さまざまな団体の方も通じて説明をしていくなど、周知の丁寧さがまたバリアフリー化にもつながっていくと思うのですけれども、その点についてはどうお考えなのか。","respondent":"立木経理課長","answer":"申しわけございませんが私ども、契約の部分では、壊して建てるのか、既存のものを残しながら建てて、最後壊すのかという部分に関しましては、今、情報がないのでお答えできないのですが、この平面図を見る限りでは。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問・要望","question":"建設委員会でも報告があったということで、そこで審議されていると思うけれども、１点だけ要望させていただきたいのですが、朝、本当に大勢の方が通るところなので、工事ヤードと歩行者の確保と、安全にできるように所管に伝えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"たしかこの公衆トイレは、デザインは公募か何かで決めたのですよね。公募で決めて、いろいろデザインが決まって、それに対して今回２つ、１番は積算金額超過で辞退された。ですので、デザインを重視すると、結構金額がそれにはね返るという部分があると思うのです。それを踏まえた形での予定価格になっていたのでしょうか。そこの整合性がしっかりある上で辞退者が出たという形なのか、その辺はいかがですか。","respondent":"立木経理課長","answer":"工事の発注に当たりましては、所管のほうでしっかり積算単価を見積もった上で予定価格、工事の積算金額を出しておりますので、そこの部分に関しましては、当然、工事内容に合わせた形の積算価格になっているものですので、今回も予定価格は適正だったと考えております。","id":"exchange-047"},{"speaker":"西本委員","kind":"質問","question":"結局、これ、デザインを公募して、それが決まりました、では、実際工事をするときに、差があってはいけないと思うのです。だけど、この場合はデザイン重視になってきますから、それに合った形でつくっていかなければいけないわけです。そうなった場合に、やはり技術的な面も含めて、ある程度こういったものが出てくるのではないかという思いがあるのですが、その辺はいかがですか。大丈夫なのでしょうか。","respondent":"立木経理課長","answer":"それに対してやはり各事業者が、これができるできないという、得手不得手というのも当然あると思われますし、その時々の職人の態勢等もある中で、今ここまでお金を出さないと無理だという場合と、うちだったらここまでできるというところがある中での今回の結果だと考えています。","id":"exchange-048"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろな機能が入ってくるとかという。もちろん品川区内の事業者の発展といいますか、技術革新というものも当然求めていきたいと思うのですが、なかなか難しいとなった場合に、やはり品川区にとらわれずにという部分もなければならない状況が出てくるかもしれないと、この件を見て感じたので、そこは研究していただきたいと考えていますので、これは意見で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"須貝委員","kind":"質問","question":"せっかくいらっしゃるので、施設整備課長にお聞きしたいのですが、これ、トイレですよね。公衆便所。これ、どこが技術的に難しいのでしょうか。簡単と言ったら語弊がありますけれども、大概の工務店ではできると思うのですが、どこがこれ、技術的に難しいのですか。参考に教えていただけるとありがたいのですが。","respondent":"小林施設整備課長","answer":"技術的に難しいというよりも、来年オリンピックもありますけれども、かなりそういうところの影響があるのではないかと考えています。","id":"exchange-050"},{"speaker":"田中委員","kind":"質問・要望","question":"子供用のおむつ台がつくということなのかということと、あと、Ｆ棟の「（だれでも）」というのは、だれでもトイレだと思うのですけれども、ここは障害のある方がかえられるようなベッドがつくということなのでしょうか。そこを教えていただきたいのです。","respondent":"立木経理課長","answer":"でき上がった後のトイレの運用に関しましては、すみません、今の段階では私どものほうには情報は入っておりませんので、お答えできないのですけれども、Ｆ棟に関しましては、図面で見る限りでは、おむつ台等はどうもなさそうです。","id":"exchange-051"},{"speaker":"小芝委員","kind":"確認","question":"トイレ、これは男性、女性の別がなく入れるということなのですか。その確認なのですけれども。","respondent":"立木経理課長","answer":"すみません、契約の段階では、私どももはっきりわかっていないもので、私のほうからはお答えできません。","id":"exchange-052"},{"speaker":"小芝委員","kind":"意見","question":"その喫煙所で路上喫煙禁止のたすきをした方がいつも掃除をされているのですけれども、よく水をくみにトイレに行くのですが、この時間帯というのはやはり通勤される方も多いので、トイレを利用される方も多くて、その辺、大変になるかと思って、１つぐらいはあったほうが、これは意見にすぎないのですけれども、もしお考えとか、今後どのようにされていくか、あればと思います。","respondent":"立木経理課長","answer":"私ども経理課のほうではできないのですが、所管のほうには、今の委員のお話はしっかり伝えさせていただきたいと思います。","id":"exchange-053"},{"speaker":"田中委員","kind":"提案","question":"Ｆ棟のことです。ですので、そこら辺の設計の提案というのが今後されていくといいなということで、これは要望にとどめたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"}]},{"id":"topic-09","title":"債権の放棄","agenda":"債権の放棄","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"よく聞くのは、違約金はつくけれども、返済をするのであれば元金のみになるのか、どこからかやはり違約金も含まれてくるのか。そこ、会計管理者の立場からどういう説明になるのか、自分自身もわからない部分もありながら伺っているのですけれども、違約金についての考え方を伺えますか。","respondent":"齋藤会計管理者","answer":"奨学金条例に違約金という規定があります。違約金自体を免除するということは基本的にございませんので、債権全体として資産の状況、収入状況を見て判断するということになります。","id":"exchange-055"}]},{"id":"topic-10","title":"平成３１年４月２１日執行 品川区議会議員選挙の結果","agenda":"平成３１年４月２１日執行 品川区議会議員選挙の結果","exchanges":[{"speaker":"西本委員","kind":"質問","question":"アトレの期日前投票というのが増えてきていると思うのです。ですので、品川区の中で、あと何箇所かこういうスペースを設けることはできないのかと思うのですが、このお考えはいかがでしょうか。","respondent":"秋山選挙管理委員会事務局長","answer":"利便性の高いところに設置というところでご利用いただいているのだなということは考えておりますけれども、期日前投票につきましては、品川区の場合は１４カ所ということで、人口の割合にして２３区の中でも一番多いということで、５０万人程度の区でも。","id":"exchange-056"},{"speaker":"西本委員","kind":"質問","question":"このときだったかどうかあれなのですけれども、アトレの中で期日前投票をすると、この中のお店の割引券などが使えるという話があったと思うのですが、いいこととは思っていません。ただ、それも一つのきっかけにはなるのかと思っているのですが、そういう特典というのもあわせて今後考えていただくというのはあってもいいのではないかと思うのですが、いかがですか。","respondent":"秋山選挙管理委員会事務局長","answer":"アトレの割引券につきましては、アトレ側で主体的に行っているもので、区として特に依頼をしたということはございません。","id":"exchange-057"},{"speaker":"田中委員","kind":"意見","question":"先ほどご説明の中で、年代別投票率について、１０代、２０代の投票率が下がっていることで、１０代から２０代に対して選挙の啓発をしているということだったのですけれども、若年層有権者、事務事業概要にも書いてあるメッセージカードは１８歳、１９歳向けなのですが、２０代に向けてされている啓発というのはどのようなことがあるのかというのをお知らせいただければと思います。","respondent":"秋山選挙管理委員会事務局長","answer":"大学入学とか、住所が変わるというようなことで下がっているのだろうということは思っておりますけれども、そこに向けて啓発しようということでやっておりまして、特段、２０代に向けて何かをということはないのですが、若年層に向けての啓発という中で。","id":"exchange-058"},{"speaker":"田中委員","kind":"意見","question":"今後、２０代の方たちに向けた啓発についても考えていきたいと思うので、ぜひ選管の中でも、この年代に対してどのように行っていけばいいのか。選管で行っているティッシュ配布、ポケットティッシュでしたか。そのときにも、ただ配布するだけではなく、若い世代の方たちの関心が、何かのきっかけが生まれるように一緒に考えていきたいと思います。考えましょうということで、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"大倉委員","kind":"質問","question":"先ほどのお話の中で、２０代が大学とかで区内から出てしまってというお話があったのですが、実際のところどうなのですかというところは、何かアンケートとかそういったものをしているのでしょうかということを教えてください。","respondent":"秋山選挙管理委員会事務局長","answer":"アンケート等は、実際、実施はしていないところですけれども、一般的に、大学に入った年で、地方から出てきて住所を移していないとかということはこちらでもお聞きはしておりますので、そういう意味でお話をさせていただいたところです。","id":"exchange-060"},{"speaker":"大倉委員","kind":"質問","question":"実際、これから投票率を上げていきたいというところでいうと、そういった人たちへのアンケートの実施とか、例えば、先ほど街頭で啓発事業で何か配っているというところでいうと、そういったところでのアンケートの実施とか、まさに行かない人たちへの何か意見聴取というか、アプローチをしていくというのは、わからない中で策というのは打てないと思うので、そういった中での作戦、投票率を上げるとか。","respondent":"秋山選挙管理委員会事務局長","answer":"ただ、若年層に向けての啓発というのは、いろいろ手をかえ品をかえ、国でもいろいろやっておりますので、その辺をいろいろ検討、可能性も見ながら、例えば、品川区では投票立会人のところに１８歳、１９歳の方に入っていただいております。","id":"exchange-061"},{"speaker":"大倉委員","kind":"意見","question":"関心がない方へのアプローチというのはすごく難しいと思いますし、ただ、何もやらないと、結局ずっとこのまま投票率が上がらないといって、関心を持っている人たちで意見を出し合っても、なかなか進んでいかないというところでは、そういったアンケートか何かわからないですけれども、直接選挙と関係ない部分で、例えば、品川区で開催する２０代とかが来そうなイベントで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"田中委員","kind":"質問","question":"戻ってしまうのですけれども、事務事業概要の６ページに載っている若年層への取り組みは、啓発に関する意見交換会が３回ということなのですけれども、その対象は１０代、１８歳、１９歳に向けたものだったのでしょうか。参加者も含めて、どうだったのかということをお伺いしたいのです。","respondent":"秋山選挙管理委員会事務局長","answer":"この３回は、明るい選挙推進協議会の中で、若い方に集まってもらうという。立会人というきっかけで集まっていただく。若い方が五、六人いらっしゃって、その方たちに集まっていただいて、意見交換会をしたという形になります。","id":"exchange-063"},{"speaker":"中塚委員","kind":"質問・要望","question":"私の意見ですが、まず、選管としてできることはいろいろやっていただきたいと思いますし、知恵もおかりしたいと思いますが、一方で、我々政治をやる者自身が、若い世代や全ての世代の人に対してしっかりと希望を語っていくというか、１票で政治が変わるということをわかっていただくというか、これは選管にはできない、我々政治を直接担っている者の、私も含めての責任かと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"つる副委員長","kind":"質問・要望","question":"そういった部分では、広報広聴課であったり、福祉関係の部門であったり、そうしたところと連携をさせていただいて、今ある課題とか、これからの課題というアプローチを、選挙管理委員会の選挙だけの切り取った啓発というアプローチの仕方ではないやり方を、新しい仕組み、枠組みで一生懸命やっていくということが大事なのだろうと思うのですが、いろいろなイベントを通じて、そこに明推協の方とか。","respondent":"秋山選挙管理委員会事務局長","answer":"特に若い人に向けてということでご議論になっていますけれども、若い人、今、投票する方だけではなくて、今後１８歳になるであろう若い人に向けて何かをやっていくことも必要だということもよく言われておりますので、行政全体で、投票に行くということを。","id":"exchange-065"},{"speaker":"つる副委員長","kind":"提案","question":"行政があえて選挙管理委員会で推進するという部分では、あるのかなという意味では、いろいろな課が、しっかり今まで以上に連携してアプローチしていくということを、強化していただきたいと思いますので、またいろいろな機会を通じて提案などもできればと思いますので、ぜひよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"}]},{"id":"topic-11","title":"参議院議員選挙の執行要領","agenda":"参議院議員選挙の執行要領","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"地域的なことですけれども、西大井４丁目の旧東芝会館から下あたりから大田区との区境なのですが、やはり今回の選挙が終わった後いろいろ感想やご意見を伺うと、坂を上った先のウェルカムセンター原や、期日前投票所となる坂を上った先の大井第三地域センターは、年を重ねるごとに投票するのが非常に大変だと。","respondent":"秋山選挙管理委員会事務局長","answer":"どこに行ってもいいということになると、果たして当日投票所というものが４３カ所要るのかということも検討しなければいけないだろうとは考えております。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問・要望","question":"ですので、改めて伺いたいのですけれども、これから高齢化、お年を重ねる方が増えていく中で、当日の投票所の番地だったり区割りを、いま一度見直す時期に来ているのではないかと思うのですけれども、この参議院選挙からやってほしいとか、そんな極端なことは言いません。改めて求めたいと思いますが、いかがでしょうか。","respondent":"秋山選挙管理委員会事務局長","answer":"そういうのも含めて、ただ単に区割りを変えれば解決するものではないと考えておりますので、そういう全体的な検討も含めて、投票環境の整備というふうに一言でくくってしまってはいけないかもしれませんけれども、なるべく投票ができる状況をつくっていきたいと考えています。","id":"exchange-068"},{"speaker":"西本委員","kind":"質問・要望","question":"上に行ってしまうと、貼れないのです。何箇所か下げたという場所があったので、見直しを図ったところがあるかとも思うのですけれども、少し高いところに設置するような場合については、もう少し下げられないのかということを考えていただきたい。参議院ですから、候補者は区議選よりいないとは思いますけれども、非常に効率の悪い状況でありますので、見直しを図っていただきたいと思いました。","respondent":"秋山選挙管理委員会事務局長","answer":"なるべくとにかく届かないようなところはつくらないという形で設置をさせていただいておりまして、区議選に比べて３段ですので、若干、こちらの指示も、一番上の高さは抑えるように指示をしております。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう一点だけ。あれがランダムなのです。ランダムだと、わからなくなってしまうという話をよく聞くのです。そもそもくじで番号を決めているから、掲示板は、そういう意味では、右から決まった配列でやったほうが、貼る側からするととても便利なのですけれども、そういうわけにはいかないのかという要望を聞いたので、なるほどと思ったので、質問させていただきたいのですけれども、いかがでしょうか。","respondent":"秋山選挙管理委員会事務局長","answer":"というところが１点と、あと、くじを引いてランダムな配置でやっているところと、番号順にやっているところとあるというのは聞いておりますので、それはご要望も含めてこちらでは検討したいと思いますけれども、ただ、ランダムにしているのは、あくまでも不公平というか。","id":"exchange-070"}]},{"id":"topic-12","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"もう一つは、昨年、人権行政のあり方についての中で、性的マイノリティーについて議論をしたところではあるのですけれども、今年は、人権行政全体ではなく、ずばり性的マイノリティーの人権のあり方について、とりわけ同性パートナーシップ制度について議論を深めていき、区への提言や提案や意見、要望などを上げていけたらと思います。つまり、公契約条例と性的マイノリティーについて、この２点です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"中塚委員","kind":"質問・要望","question":"以前にも私、述べさせてもらったのですけれども、依頼があるということですが、毎年やる必要があるのかというのが私の疑問でありまして、４年の任期の間に１回ぐらいは、依頼があるということですから、それに議会が応えていくということは必要かと思うのですけれども、毎年やるというのは、そこまでの必要性があるのかと思いますので、最終的な委員会運営は正副にお任せいたしますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/203294?Template=document&Id=2134#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":74408,"voices":244}},{"id":"r01-20190611-14","meetingId":"r01-cm06","date":"2019年6月11日","dateIso":"2019-06-11","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時１３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","topics":[{"id":"topic-01","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、やはり愛される、便利に利用される庁舎にしていくためにも、区民の声を聞く仕組みというのをつくっていくべきだということを私たちも主張させていただいていたのですけれども、今年度の取り組みのところで、建て替えについての検討等々も現状認識や必要性、場所や手法、こういったことも区民の皆さんに聞いていくということも必要なのではないかと思うのですが。","respondent":"立木経理課長、柏原企画調整課長、鈴木都市計画課長","answer":"そこの部分に関しまして、どういった形がとれるのかというのをこれからしっかり考えていかないといけないと考えていますが。あわせて、区有地につきまして、東品川作業所は用途制限が切れるというところがありますので、具体的な今後の活用の内容については。区内鉄道駅の安全性に対する区の認識ですが、やはりさまざまどなたが利用しても安全に利用していただくと。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これは意見です。東大井都営住宅跡地も、今東京都からのどうやって使いますかという質問に対して区が答えたという状況だと思うのですけれども、具体的にこれから交渉、調整に入ろうというところだと思うので、ぜひこういう中にそうした場所も入れていただきたいなと。それで、区内の鉄道、公共交通のところですけれども、ホームドアのところに関しては、通過駅ほどやはりつけるべきだという声が多々あります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"石田ちひろ委員の質問に関連している小さい質問ですので、ついでにお伺いしておきます。公有地の活用のところです。決算特別委員会、予算特別委員会では内部での検討は始めているのだとお答えいただいていたので、当然この表に載っているのかなと期待を持ってこの表を見ましたので、それがなかったのでちょっとがっかりしたというのがありましたので、念のためにお伺いしておきます。","respondent":"柏原企画調整課長","answer":"年次的にはまだもう少しあるというところもございまして、どういったものがいいのだろうかという内部の検討は始めているところではありますけれども、そういった観点で、スケジュール感のところで、区有地は示させていただいたというものです。","id":"exchange-003"},{"speaker":"こんの委員","kind":"確認","question":"これから各調査項目については掘り下げていくと思うのですが、確認を１点。今の段階で、どこまでどういうようなお話をこの方たちとされているのか。いわゆる建て替えに向けてのお話の内容、どこまでどういうふうにこの方たちとどういう内容のお話、調整をされているのか、参考までにお伺いします。","respondent":"立木経理課長","answer":"具体的には今年度建て替えについての検討を始めますというようなことで、そういったところのお話まででまだ具体的に、例えばどういった手法でとか、どういった立地でとかいうところまでは一切お話ができていない状態です。","id":"exchange-004"},{"speaker":"こんの委員","kind":"質問","question":"そうすると、今年度そういったことで進めていきますと、いわゆる調整というよりも伝達をしたというか、そういうぐらいのお話なのか。それによって建て替えとなると、一旦ここの場所を出なければいけないとか、スケジュール感とかいろいろとこの方たちも考えなければいけないというところまでお話をされているものなのか。そこら辺、参考までにお聞きしたいと思います。","respondent":"立木経理課長","answer":"委員おっしゃるとおりでございまして、実際に建物を動かすなり壊すなりということになりますと、それぞれの権利をお持ちの団体のほうでも準備をしなければいけないというところがありますので。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"３点お伺いします。伺いますのは、現区庁舎の建物がどれだけもつかという点です。２０１１年には耐震工事も行ったのですけれども、昨年の行革委員会でも伺ったのですが、検討のスケジュール感を考える上でも、改めて区庁舎の耐用年数というのを確認させていただきたいのが一つです。これが２点目です。","respondent":"立木経理課長、柏原企画調整課長、稲田都市開発課長","answer":"ただ、設備等も一緒に付随していますので、そういった部分も考えますと、それぞれ耐用年数等ありますので、老朽化に伴う修繕、改修等。スポーツ協会で６名といった状況でございまして、それぞれの団体でその配置といいますか、任用されている職は違うのですけれども、事務局長であったり。そういう中で、やはりしっかりしたまちづくりをやっていこうというところでございまして、平成１４年には土地再生特別措置法が制定され。","id":"exchange-006"},{"speaker":"安藤委員","kind":"確認","question":"つまり、２０１１年から２５年たつと２０３６年ということで、今この２０１９年時点でもまだ１７年もつということになりますので、躯体自体は決して今すぐ関連の区分所有の団体に建て替えますということを近々伝えて、もう今から建て替えなくてはいけないというスケジュールを切ってやるといよりも、やはり躯体がもつわけですから、まずはしっかり今の課題がどこにあるのか、そして区民がどう考えているのか。","respondent":"立木経理課長","answer":"ただし、先ほど申し上げた内容ですと、やはり建物の躯体自体の耐用年数、あとはそれに付随する設備類の耐用年数、それからその維持にかかるトータルコスト。","id":"exchange-007"},{"speaker":"安藤委員","kind":"確認","question":"トータルコストという話もありましたけれども、いろいろな視点から庁舎のあり方を考えなくてはいけないと思うのですが、耐震工事を行ったときの総務部長の答弁にもありますし、昨年も確認されたことですので、建物の耐用年数はそういったことだということを一つ頭に置いて議論の材料にしていく必要があると改めて申し上げておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問・要望","question":"それで区民の皆さんの意見を聞いて、さらにそれから見積もりを取って云々というのですから相当時間がかかると思うのです。一応２番目に混雑緩和に向けた取り組みとあります。１本、２本待たないと乗れなくなるという状況がさらにふえるわけですから、私は逆にそっちのほうに主眼を置いて取り組んでいってほしいのですけれども、どうもバリアフリー化、ホームドアの整備状況、これはすごく大事なことです。","respondent":"立木経理課長、鈴木都市計画課長","answer":"そういったことを区の内部のほうでたたき台としていろいろ検討させていただいて、また議会のほうに提示をさせていただきまして、議論をいただければと考えています。そうした意味でどれを中心にということではございませんが、まさにおっしゃっていただいたように、ある意味都内全体の乗り入れですとか、これはもう区が各駅と話をしてもどうなるものでもないところでございまして。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問・要望","question":"恐らくこの先もどんどん伸びていくのだろうなということを想像すると、やはり本当に待っていられない、早急に対策をとってほしいと思うので、品川区だけの問題ではないと思うのです。恐らくこの地域全体、東京、横浜、千葉のほうもそうかもしれないですけれども、本当に大変な問題になると思うので、区としても私はどんどん積極的にほかの区とも連携して働きかけていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問","question":"区内鉄道駅などの公共交通に関することでこれから議論をする前提で伺いたいのですが、今も須貝委員とのやりとりの中で、これは本当に一つの駅のことを捉えても、全体の話であってなかなか全ての解決には至らないということはわかりますけれども、私も区議会議員になって９年目なのですが、さまざまなこと、例えば私の地域で言えば京浜急行新馬場駅の南口のエレベーターの件。","respondent":"鈴木都市計画課長","answer":"そうした折には、今の例えばホーム柵の検討状況ですとか、そうしたところは区のほうから確認をするとか、今ご紹介いただいた京急の新馬場駅南口のお話も、そうした機会を捉えて話をさせていただいているような状況です。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これからこのことについて議論をしていく上では、これはお願いなのですけれども、やはり今３カ月に一遍ぐらいの感覚だということでおっしゃっていただいて、私は思ったより逆に多いなと思ったのですが、ぜひこういうことを行財政改革特別委員会、区議会の中で今議論をしていて、その都度ぜひその声を上げていただきたいというのが要望です。その前提で議論をしていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"大沢委員","kind":"質問","question":"今、あくつ委員の鉄道事業者と区の関係ということで、まさに私のところは武蔵小山駅でして、ご存じのように東急電鉄主体のというか住民主体の開発ということで、住んでいる方たちが主体のまちづくりをしているわけですけれども、以前話を聞いたときに、どうしても東急電鉄の力が強くて行政の力は及ばずで。","respondent":"稲田都市開発課長","answer":"その力関係といいますと、なかなか鉄道事業者の鉄道に係るもの、それからその周辺に係るもの、そういう中におきましては、どうしても譲れない鉄道を運行するための安全上の問題とかそういうものはあったりしますけれども、地域の。","id":"exchange-013"},{"speaker":"大沢委員","kind":"意見","question":"やはり、東急電鉄はあくまでも鉄道事業者であって住民、我々住んでいる居住者ではないわけでありますので、ぜひとも私たちの武蔵小山に限らずほかの場所でも鉄道事業者にしっかりと声が通る、しっかりとした意思の疎通ができて迅速に対応していただくような、なかなか大変なことだと思いますけれども、ご努力だけお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"確認","question":"庁舎のあり方について、もう一度確認させてください。今年度取り組みとして、経理課の中に組織をつくるというお話があったと思うのですけれども、その規模とかメンバー的なものはどういう形になっているのでしょうか。そこら辺も教えてください。","respondent":"立木経理課長","answer":"こちらの取り組みも、庁内検討会等の部分ですが、一応全庁的な部分で少し考えていきたいのと、あとそれの下部みたいな形でやっていきたいと考えております。具体的には、部長クラスのメンバーを中心としたようなものと、あとは実務担当者という部分です。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。その中で、現庁舎の課題整理ということに関しては、この建物の中の課題という意味なのか、地域、大井町、この辺を含めての課題の検討になるのか、この辺を教えてください。","respondent":"立木経理課長","answer":"こちらの課題整理の部分に関しましては、今おっしゃったとおり庁舎の中の部分がまず一つ。それから、あと例えばまだどこに建てるのか、どういった手法でやるのかというところもまだ決まっていないという中では、周辺環境も含めての課題整理が必要かと考えています。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問","question":"結局、大井町近辺、先ほどほかの部分、まちづくりでも出ていたと思うのですけれども、この庁舎をやることによって大井のまちづくり、広町、中央公園だとかそういう話も含めてくると思うのですけれども、ここら辺までこの会議体でやっていくのか。そこまで含めたということまで考えていいのでしょうか。","respondent":"立木経理課長","answer":"私ども経理課のほうで所管するのは庁舎の部分ですので、まずは庁舎の建て替えの部分をどのタイミングでやるのがいいのか、それから立地としてどこにするのがいいのかという部分の検討ですので、トータル的なまちづくりの部分までは私ども影響範囲が及ばないところがありますので。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうすると、庁舎の建て替えということで全庁的にやっておいて、まちづくり部分というのはまた別の全庁的な組織も作成して、経理課だけではなくて、別の部分、企画案件になると思う。企画ではないのかな、まちづくり系なのか、当然その辺もまた別に組織体ができてくると考えておいたほうがいいのでしょうか。","respondent":"柏原企画調整課長","answer":"今、経理課長が申したとおりですけれども、まちづくりの観点という意味でも、こちらの広町の関係、それからこのエリア一体と言いますか下神明エリアも含めてですけれども、そちらはそちらで全庁的な検討体制というのはとってありますので。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"当然全庁的にやっていくから連携をとるのでしょうけれども、大きな話になっていくと思いますので、その辺連携をうまくやっていただきたいということで要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"私からは、区有施設・公有地等活用に関することというところなのですが、これを深めていく上で考えていかなくてはいけないなと思う点があります。この調査に当たっては、他区の事例なども改めて研究しながらですけれども、そういう住民参加の公有地活用の検討の手法についてもぜひ調査・研究をしていければいいなと思いますので、提案します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/145510?Template=document&Id=6068#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":22574,"voices":80}},{"id":"r01-20190612-18","meetingId":"r01-cm06","date":"2019年6月12日","dateIso":"2019-06-12","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ２時５２分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"品川改革連合の筒井ようすけです。どうぞよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"本多委員","kind":"質問","question":"今ご説明いただきました「テストイベントへの協力」なのですけれども、およそ１年前にはホッケー会場もビーチバレーボール会場もテストイベントがあるということで、競技会場も完成されていると思うのですけれども、両方の会場は、今、工事が進められていますけれども、完成時期だけ概要を教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"次に、ビーチバレーボールのほうですが、こちらはテストイベントのときは仮設を建てて、その間に大会を催し、終わったら一度壊すと聞いております。ですから、実際のオリンピックのときの会場は、２０２０年に入ってからつくると聞いております。","id":"exchange-002"},{"speaker":"本多委員","kind":"意見","question":"区としてもやるべきことがあると思って、本日はその課題だけ言って、これで終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"筒井委員","kind":"意見","question":"テストイベントについてですけれども、これは我々議員も見にいっていいものなのか。そういった場合、どういう形の立場というか、議員として行くものなのか、それとも一区民として行くものなのか、そのあたりをお知らせください。「まちの賑わいを作る」のところで「ライブサイト」があるのですけれども、これは一体どういったものなのか、この２点をお知らせください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"２点ご質問をいただきました。テストイベントなのですが、この２種類は色合いが違いまして、まずホッケーに関しましては、組織委員会が実施するものです。こちらに関しましては、無観客でやるというのが前提です。基本的にはそうなっております。","id":"exchange-004"},{"speaker":"筒井委員","kind":"質問","question":"すると、テストイベントについては、今のところ無観客、後日また案内ということなのですけれども、ビーチバレーボールに関しては、チケットを買わなければいけないということで、ただ、議員として視察に行くという場合でも、それはチケットを購入して見にいかなければいけないという理解でよろしいでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"視察の枠は特に聞いておりません。今のところバレーボール連盟は通常の大会を開催するという予定で、それぞれが負担すると聞いております。","id":"exchange-005"},{"speaker":"筒井委員","kind":"質問","question":"わかりました。ＬＩＮＥによる情報発信についてですけれども、これは、要はＬＩＮＥスタンプをダウンロードして使うというものなのでしょうか。どういうふうにＬＩＮＥで情報発信するのか、具体的にどうするのかを聞きたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今、委員がおっしゃいましたスタンプについても、今、検討をしております。いわゆるメディア、企業が、スタンププレゼントのプレミアムが出ていることがあると思うのですけれども、あの形はかなり高額なもので、それは考えていません。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"言葉の説明だけ、知らなくて申しわけないのですが、スポーツの中の最初の表のページで、障害者スポーツのフリー利用で「リング」や「縄」はどういう競技なのか。「縄」は縄跳びかしらと思うのですけれども、それから「ストラックアウト」も教えてください。裏に行って、「アキュラシー」も、すみません、無知で知らないものですから教えてください。","respondent":"中元スポーツ推進課長","answer":"縄ですが、こちらは縄跳びまでは難しいようで、床に置いた縄を飛び越したりとか、少し簡易な形でやっていただくものです。ストラックアウトはいろいろなものを使ってできるのですが、目標を決めまして、そこを目がけて物を投げるというものです。","id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"確認","question":"ご説明ありがとうございました。確認だけさせてください。それと、グラウンド・ゴルフはそもそも土でやるものだと思うから、その辺のところも団体の方にはどういうふうに、説明はされていると思うのですけれども、確認だけさせてください。","respondent":"中元スポーツ推進課長","answer":"そちらは、実は既に荏原Ｂ地域スポーツクラブの会合の中でお話に出ておりまして、今現在、どういう対応をするのか、このままできるのか、場所を変えるか検討しなくてはいけないのか、今、調整中のところです。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"資料の一番最後の障がい者スポーツ指導員養成講習会派遣ということで、今、実際に指導員をやられている方は、これを受けた方でどのくらいいらっしゃるのか伺いたいと思います。","respondent":"中元スポーツ推進課長","answer":"手元に資料がないのですが、毎年こちらは派遣していますので、相当数、十数名ぐらいにはもうなっているかと思います。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問","question":"それは受講した方が十数名ということですね。なかなかそういう場も、私もどうやって探したらいいのかわかりませんけれども、少ないのかなという感じがしますので、どのくらいいらっしゃるのかということと、区内の競技場のバリアフリーなどの整備状況は区のほうでつかんでいらっしゃるのか、その点もあわせて伺いたいと思います。","respondent":"中元スポーツ推進課長","answer":"区内の施設のバリアフリーの状況ですが、スポーツに特化したものは総合体育館、戸越体育館で、ほかの活動場所は学校施設を活用しているところが多数ありますので、それぞれのその施設の利用目的に沿ったバリアフリー対応がなされていると認識しています。","id":"exchange-010"},{"speaker":"若林委員","kind":"質問・要望","question":"１ページ目の「障害者（交流）スポーツ教室」について、昭和５７年からということで一番古い歴史のある事業ですが、ざっとこの一覧を見比べると、ここの教室だけ唯一、区で競技を指定しないで、「団体と協議し」ということで、団体の方のいわゆる障害のある方のスポーツ以外にも、健常者と本当に一緒にできるようなということが窺えるのですが、まずは「団体等」とありますか、この内容、それから。","respondent":"中元スポーツ推進課長","answer":"団体は、障害者７団体の方を順番に、昨年やらなかったところを次の団体という形で調整をさせていただいておりまして、今年度につきましては、視覚障害者の団体の方と、現在、調整しておりまして、民謡を一緒に踊ってみようかということで。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問","question":"ボッチャについては、品川区が既にこの間ずっと区民に対する「一生涯の生涯スポーツ」という視点も含めて推進してこられたというところでは、まさに今回のオリンピック・パラリンピックの大会を通じて、より一層ここは拡充ができるというところのレガシーということでは、非常に大きいウエートになってくるのかなと思いますが、あとは委員会の運営自体の話なので、委員長・副委員長かもしれませんが。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"これは何らかの形でうまく協会とも連携しながら残せていければいいかなと思うのですが、どういう方向かはまだ頭に浮かばないので、今後の検討課題とさせていただきたいと思います。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"今現在は報道等を見る中では、保育園生の、いわゆる幼稚園生と設定されている５歳児が、保育園生においてはまだ特段動きはないのかと思うのですが、この間、東京都に対して、東京都にそういう動きがない場合、品川区として支援をしてほしいということで何度か質問させていただいているわけですけれども、まずその辺の東京都の動きです。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"「学校連携観戦プログラム」についてのご質問です。委員ご指摘のとおり、こちらは学校教育法に基づく児童・生徒が対象というもので、保育園、認定こども園は入っておりません。","id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"先ほどオリンピック・パラリンピック推進のところであったパブリックビューイングとか、そうしたところで５歳児に限らず、少しでもそういう快適な環境を整えて、もう少し下の年齢の子どもたちが、時間等の制約は当然あると思いますけれども、そうしたところであれば親子でも招待、そうしたことは幅広の意味では可能なのかなと思いますが、あくまでも生で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"筒井委員","kind":"質問・要望","question":"レガシーで、ソフト面で区内開催競技のスポーツの推進ということが挙げられましたけれども、特に例えばビーチバレーボールについては、品川区内にそうした砂浜はないので、今後、推進するに当たり一つの課題かなと考えておりますけれども、私としてはせっかくの東八潮での開催、本番で開催されるということで、東八潮の場所を活用していただきたいというのはあるのですけれども。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"現在はビーチバレーボールの推進ということでは、大会をちょうど５月５日に行いましたり、あとは体験会をやったりですとか、観戦ツアーもやっていただいたりですね、今年のテストイベントのときも観戦ツアーは行う予定でおります。","id":"exchange-015"},{"speaker":"筒井委員","kind":"質問・要望","question":"区内開催・応援競技以外で障害者スポーツを含めて、このホッケー、ビーチバレーボール、ブラインドサッカー以外のスポーツ全体をソフト面のレガシーとして、ぜひ推進・普及をしていっていただきたいと考えているのですけれども、そうした開催・応援競技以外のスポーツの推進は、品川区としてはレガシーとしてどのようにお考えになっているのでしょうか。","respondent":"中元スポーツ推進課長","answer":"詳細が決まりましたら、所管の委員会にご報告を申し上げながら、ご意見を伺いながら進めてまいりたいと思います。その中で委員おっしゃったようなレガシーに関して、そういうものも取り込んで検討していけたらと考えております。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問","question":"障害者のスポーツだけではなく、健常者のスポーツ、このオリンピック・パラリンピックをやったことによって、「スポーツが手軽にできる」「活性化した」というレガシーを残していけたらと思っていますけれども、日常のスポーツを手軽にできるようにしていくというところでのお考えを伺いたいと思います。","respondent":"中元スポーツ推進課長","answer":"最後の大井八潮の地区の地域スポーツクラブが来年３月には結成予定ですので、区内全域で身近な場所で、近くの区の施設を活用してスポーツを生活の中に取り入れていただけるような形で進めていきたいと考えているところです。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"障害者スポーツはこの間もやってきたということでしたけれども、ぜひこれが大会後もさらに発展する形でやっていっていただきたいと思います。普通のスポーツの点でも、地域スポーツクラブが区内全域で今年度できるということで、この間やってこられた荏原地域、そういったところでスポーツを気軽にできるようになったわけですが、実績・成果にはどういったものがあるかご説明いただければと思います。","respondent":"中元スポーツ推進課長","answer":"申しわけありません、具体的な数字は、今、地域スポーツクラブについては持ち合わせないのですけれども、荏原Ｂ地域と荏原Ａ地域と２つありまして、荏原Ａ地域のほうがｅｂａｒａＡということで活動しております。","id":"exchange-018"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"筒井委員","kind":"質問","question":"聖火リレーのルートについてですけれども、７月２２日は品川区が最後のルートなのですけれども、スタートの江東区が夢の大橋からのスタートのものでよろしかったのでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"委員ご指摘の中で、聖火がずっと大会中燃やしていく場所だと思うので、詳細なルートについてはまだどちらも検討中と聞いていますので、そちらからというのは私どもはわからないところです。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"これもまだ未定かもしれないのですけれども、これは各区、例えば品川区の前日は中央区で終わっているのですけれども、江東区からスタートする場合、中央区から聖火を車などで移動させるものなのでしょうか。その辺は、私はわからないので。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"中央区で終わりましたら、ポットみたいなものに入れて車で移動して、次の日の江東区のスタート地点に持っていくと聞いております。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問","question":"コロンビア共和国の事前キャンプで、区民交流というところで区内の障害者団体とかそういった、実際の当事者の方にお知らせしたのか、交流はあったのか伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ボッチャでのですか。特別支援学校等にもご案内してみようかとは今のところ考えているところですが、まだ会場と日にち、この日は例えば練習とか、この日は観光だとか、その辺のスケジュールが決まっていないもので。","id":"exchange-021"},{"speaker":"のだて委員","kind":"意見","question":"日常のスポーツの環境を整えていくというところでは、具体的に今、思いつかないのですけれども、競技場の今のバリアフリーの状況ですとか、車いす体験をするのもいいのかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"吉田委員","kind":"提案","question":"今のご意見に関連するかと思いますけれども、障害者理解というか、障害者スポーツを通じてということもとても大切だと思うのですけれども、いらっしゃる方とかまちのつくり方を含めて、皆さんの意識啓発、意識を変えていくことが必要かなと考えています。それで、一つ提案ですけれども、障害者自身が講師になって研修をして障害への理解を深める研修をやっている団体があります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"本多委員","kind":"質問・要望","question":"わかりました。会派はそれでまとめて、また改めて出しますけれども、今、１点だけ。先ほども発言しましたけれども、人の動線です。先ほどつる委員からも出ました、本当に全ての子どもたちに観戦という経験をしていただきたいと思いますので、その辺の動員も含めて取り上げていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"文化プログラムについてですけれども、「しながわ文化プログラム」のご説明によると、区における伝統文化の魅力発信や新たな区の文化の発掘を目的としているということと、また、対象イベントの文学、美術、舞踏、写真、音楽、演劇、生活、芸能、そうしたことなのですけれども、この文化プログラム推進に関することでこの調査内容案ですと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/110082?Template=document&Id=6554#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":34102,"voices":114}},{"id":"r01-20190614-10","meetingId":"r01-cm06","date":"2019年6月14日","dateIso":"2019-06-14","committee":"議会運営委員会","time":"午後 １時００分～午後 ２時２８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","topics":[{"id":"topic-01","title":"の４、議長会への要望事項","agenda":"の４、議長会への要望事項","exchanges":[{"speaker":"大倉委員","kind":"質問・要望","question":"私たちの会派からは、まず乳幼児、児童、生徒の安全確保を求める要望については、昨今のさまざまな自動車による悲惨な事故、川崎でも殺傷事件が起こっております。次に、高齢者施設整備に関する要望、これも今まで出していたとおりですが、人生１００年時代を支える総合的施策を国の責任において講じるなど、この要望内容のように求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"芹澤委員","kind":"質問・要望","question":"２点目、羽田空港の機能強化に関しては、これも国と都に要望を出しています。３点目、東京２０２０オリンピック観戦チケットに関する要望。３点目、障害者、高齢者、保育園等に格安チケットを販売されるよう、組織委員会への要望をお願いしたいということで、出しております。４点目、高齢者施策の更なる充実を求める要望。５点目、地方税財源の充実を求める要望。６点目、保育施策の更なる充実を求める要望。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"新妻委員","kind":"質問・要望","question":"幼児期に子どもの視力検査を行いますが、視力に異常があるかどうかをより一層確実に検査するために有効とされている、フォトスクリーナーの導入において支援を求めるため、公明党として要望します。この１０月から始まります幼児教育無償化に当たって、３歳以上の食材費は保護者負担とされておりますが、より一層区民の皆様への負担の軽減を図るため、食材料費の無償化が必要であると考え、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"国に求めることとして、国民健康保険及び介護保険における国庫負担の大幅引き上げを求める要望ということで、高過ぎる国保料の引き下げへ、全国知事会も１兆円規模の財政負担を国に求めておりますが、改めて国庫負担の引き上げを求めることと、介護保険料の引き下げへ、国による公費負担を大幅に引き上げるということです。続いて、国と東京都への要望ですが、少人数学級の実施を求める要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"東京都への要望ということで、学校教員の人事権と教員給与を品川区への移譲を求める要望ということで、すみません、一部訂正しながら読ませていただきます。これらの趣旨を踏まえ、下記の事項について要望します。３番目、これも国に対する要望で、品川区内上空を通過する新たな飛行ルートの変更を求める要望です。４つ目、国への要望で、鉄道における通勤・通学時のラッシュアワーの解消を求める要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん共産党としては計画反対、撤回を求めるところですが、議長会への要望ということであれば、決議に沿った中身がよろしいのではないかと。教室型説明会が１３カ所終わったところなのですけれども、これは国への要望ですが、教室型説明会の継続、引き続き開催してほしいということはぜひ、皆さんのご意見を踏まえてですが、決議に加わると、なおいいかなという意見を述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"本多委員","kind":"質問・要望","question":"同じように、羽田空港に関することと高齢者施設に関することは、一つ一つの課題についてはおおむね共有できると思いますので、この２つはまず国に対する要望として絞っていいのかなと思います。少数意見でもその課題が全会派、議会全体で認識できるものは、取り上げていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"渡部委員","kind":"質問・要望","question":"委員長から話があったように、たくさん出てきたので少しまとめてということですが、今、本多委員から話がありましたとおりだと思います。少数意見でも課題はありましょうから、検討いただきたいということで、今回はもうある程度まとまっている中で、今日意見が出ましたので、あとは議長に一任としていただいてよろしいかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"今、お話がありましたとおり、まとめてですので、今回公明党から細かい要望も入れさせていただきましたが、各会派から共通で出ている部分もまとめていただきまして、また新たに出した羽田新飛行ルートにおきましては決議もされているところから、ぜひこれは要望する方向でご検討いただければと思います。は議長一任とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問・要望","question":"羽田のことですけれども、まさに皆様の言うとおり、これはぜひ言うべきと思いますが。別に否定しているわけではないです。できるだけこの形を生かして要望したほうが、我々は大分省略しましたが、自民党が出しているような形を要望の形に少し直して、出したほうがわかりやすいのではないかということで、補足します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"須貝委員","kind":"提案","question":"説明会の話がありましたけれど、それを出してしまうと、どちらが主なのかわからなくなるので、やはり今、あくつ委員がおっしゃったとおり１つに絞って、提案したほうがいいと思います。は皆さんの要望でさまざま出ていますけれども、議長が取り上げなければいけない問題だというものがあれば、まとめていただければありがたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"中塚委員","kind":"提案","question":"共産党が提案した中で、これは一致できるのではないかというものとすると、国保制度について国の財政負担をしっかりしてほしいと、この点はいけるのではないかと期待を込めて。難しければ、他の会派のご意見もありますけれども。やはり国民健康保険制度ですから、国がしっかり責任を負うということは一致できる点があるのではないかということで、あえて発言させていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"渡部委員","kind":"質問・要望","question":"会派でいろいろもませていただいて、出させていただいた中で、先ほども申し上げたのですが、乳幼児、児童、生徒の安全確保を求める要望については、今、マスコミ等でもいろいろな話があって、連日さまざまなニュースもある中で、国のほうへと都のほうへは、若干内容を変えて出させていただいていますが、主として都へ要望するところで、太字になっているところもありますが、やはり警察との関係ですとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"若林副委員長","kind":"質問・要望","question":"今、国と都への要望ということで議論が集約されましたが、公明党からは全国市議会議長会を通じてというものがあります。議長にはくれぐれも、この意見も踏まえて考えていただきたいということを、申し添えます。具体的には幼児教育の食材料費、これは全国的な問題だとも思いますので、そのことをコメントします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-02","title":"防災服のリニューアル","agenda":"防災服のリニューアル","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"ですから、今、貸与されている前回のものはあるので、何かあればそれを着ればいい話ですから、デザインとか発注の仕方とか、発注する、しないにしても、私は個人的にはこれから議会独自のものを考えていくというのは、いい考えだと思いますし、議会でやるのが本筋だと思っています。ですから、私個人の意見としては、どこかの機関でしばらくそういう検討をすべきではないかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"中塚委員","kind":"意見","question":"今のあくつ委員のご意見と同じです。もちろん、いざ災害が起きたとき、どう行動するのかという議会側の対応は議論を進めていくべきで、それに合った形というのがどういうものなのか、よく皆さんとご議論できたらと思いますので、今回の発注はせず、議論を深めていくということで、よろしいのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"意見","question":"自民党としても考え方は同じです。今回の発注は見送って結構だと思います。その検討をするのが、議運なのか、先ほど出ていましたが、議会改革推進会議等も活用できるかと思いますので、その辺、ある程度議長の裁量にもなってくると思いますので、検討していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"仮に区別というふうなことがしたいのであれば、例えば同じものにして、刺しゅうなり何なりをして、明確にこういう団体ですというものを示すならいいですけれど、やはり区民の皆さんの税金で、我々もつくってもらうわけですから、そこは統一して、我々も区のため、区民のために一緒に働くのだという姿勢と、謙虚に費用をかけないで制服をつくっていくのだと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"渡部委員","kind":"意見","question":"それは区の中で何かがあったときには、最初は当然私たちも地域のひとりとしての活動、この中には区民消火隊の方もいれば、消防団の方もいれば、町会関係の方もいて、まず第一義的にはそういう動きをした後、区議会として何か動かなければならないというときには、そういう服装で行くことも考えられますが、それは先ほどの議論でもありましたけれども、議会改革の中でしっかりもんでいこうというのであれば。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"局長にちょっと調べていただきたいことがあるのですが。議会と職員と分けた防災服というふうにつくっている自治体が実際に、２３区だけでもいいのですが、あるのかどうか。もし調べていただけたらありがたいと思います。品川区だけがやるのかどうか、よそもそういうふうにやっているのか、そういうことを参考のために調べていただけたらありがたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"本多委員","kind":"質問・要望","question":"取り上げていただきたいものがありまして、天皇陛下への賀詞のことを取り上げていただきたいと考えています。５月には、衆議院におきましても、参議院におきましても、天皇陛下に御即位の賀詞をお示ししております。本区議会におきましても同様に、賀詞をお示ししたいというふうに思っております。案文を読み上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"本多委員","kind":"質問・要望","question":"本日は、ぜひ会派にお持ち帰りいただき、ご検討いただければと思います。願いとしましては、次回の議運で再度取り上げていただき、できましたら本会議において議決を要望するものです。参考までに、先ほど５月に衆議院においても、参議院においても決議をされたと発言しましたけれども、全会一致をもって決議をされました。本区議会においても同様にしていければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"須貝委員","kind":"確認","question":"議会・委員会運営に関する申し合わせ確認事項というものがありまして、その１６ページに、臨時会後に、会派構成人数の増減があった場合は、速やかに議会運営委員会で協議し、直近の定例会までに結論を得るものとするということで、我々長年の間、恐らく議長経験者の方は、皆さんそうされてきたと思うのですが、会派の人数等の変更があった場合には速やかに、例えば議運の委員長、副委員長もそうですが。","respondent":"米田区議会事務局長","answer":"今、ご案内のありました申し合わせ確認事項に関しては、１６ページのところで、臨時会後に会派構成人数の増減があった場合は、速やかに、議会運営委員会で協議し、直近の定例会までに結論を得るものとするということで、今回でいいますと。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問","question":"それは皆さん一致したと思うのですが、ただ正式に議会運営委員会が立ち上がったわけですから、その立ち上がった中で、こういう申し合わせ事項がある中で、このまま委員長、副委員長の状況が、従来の約束と変わったやり方を進めるということは、品川区議会がせっかく今、議会改革をやっている中で、そういうものを無視して進めるというのは、私は間違っているような気がするのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"須貝委員","kind":"提案","question":"品川区議会、こうして議会改革をしつつ、さまざまな提案なり、変革も今しています。その中で、こういう申し合わせ事項がある中で、それと逸脱したようなやり方というのは、私は早急に改善をすべきだと。こちらを直すのか、それとも新たに条文を加えるのか、そこはやはり、私は品川区だけが議会を運営しているわけではないですから、その辺も考えてこれから進めていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"石田（秀）委員長","kind":"提案","question":"私から公の場で、あえて須貝委員にも言わせていただくけれども、ちゃんとこういう公の場で私は今まで須貝委員にこういうことを言ったことはないですけれども、議会改革を議長から提案していただいた、そのときは大沢議長のときだと思います。いろいろなことを含めて。それだけはお願いしたいなと、私は思います。次回の開催は、第２回定例会本会議の前日です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/268822?Template=document&Id=5320#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":24527,"voices":75}},{"id":"r01-20190626-10","meetingId":"r01-cm06","date":"2019年6月26日","dateIso":"2019-06-26","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時２８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","topics":[{"id":"topic-01","title":"令和元年第２回定例会","agenda":"令和元年第２回定例会","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ご説明ありがとうございました。若干ご質問させていただきたいと思うのですけれども、今まで区長１人と副区長２人という体制を組まれていましたが、今回の２人目の副区長ですけれども、どういう位置づけ、役割なのか、今までとの違いと、またどのような事業を担っていくのか、その仕事の内容についてご説明いただけたらと思います。","respondent":"濱野区長","answer":"今現在は副区長１名ということであります。しかし、長年にわたって副区長２名というのが品川区の場合多かったと考えています。私が助役でありましたときもそのようなことでありました。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"ピックアップした部分を和氣正典さんということですが、今、具体的な事業としてオリンピック・パラリンピックがありましたが、そのほかに、今想定されているものがあればご説明いただきたいと思います。","respondent":"濱野区長","answer":"代表的な例として、オリンピック・パラリンピックということで例示をさせていただいた次第です。分担については、また資料をもってご説明をさせていただきたいと思います。","id":"exchange-002"}]},{"id":"topic-02","title":"の２、令和元年第２回定例会についての(2)賀詞","agenda":"の２、令和元年第２回定例会についての(2)賀詞","exchanges":[{"speaker":"本多委員","kind":"提案","question":"前回の議会運営委員会におきまして提案をさせていただきまして、ご意見をいただいたり、ご検討いただいたり、ありがとうございました。それで、修正をさせていただきました。前回提案をさせていただいたものから、各会派の皆様方からご検討いただいてご意見いただきました。資料No.４の裏面の賀詞というところから、内容だけ読み上げさせていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"中塚委員","kind":"提案","question":"前回の議会運営委員会で提案された案文について、提案者に意見を伝え、今回修正をされたものが示されました。あくまで国民の総意による解決ですから、つまりは共産党から憲法上の制度である天皇の制度について、廃止を求める運動を将来にわたって起こしたりはしない、立憲主義を貫くという意味からしても、いずれにしても憲法の全ての条項を守るというのが日本共産党の考えです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"須貝委員","kind":"提案","question":"私は今回のご提案に対しまして、一言申し上げたいと思います。ですが、実際各自治体・各議会で果たしてこれをやることなのかどうなのかという、私はやはりそこにひとつ問題があるのではないかと思います。そういう場を実際設けてあります。それが１点と、それと、今、時期としてもう既に６月後半です。今回に関しては、私は品川区議会としては出すべきではない、かと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"中塚委員","kind":"提案","question":"一言述べたいと思います。態度としては反対です。特命事項として事業推進の体制を強化するというのであれば、２３区で最低の福祉の引き上げや、区内経済の核となる商店街や町工場など、中小企業への支援の強化こそ必要だと思いますので、いずれにしてもこれ以上の再開発を進める体制強化である提案となることから、副区長の選任同意については反対をさせていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"}]},{"id":"topic-03","title":"ポートランド市公式訪問団","agenda":"ポートランド市公式訪問団","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"議会事務局長に聞くことかどうかちょっとわからない部分はあるのですが、公式訪問団ということですので、報告書は作成、そして提出、発表されるのか、その点だけご説明いただけたらと思います。","respondent":"米田区議会事務局長","answer":"所管のほうからは、報告書の作成を行っていくというようなことを聞いております。私のほうで答えられるのは、今のところ以上です。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"ポートランド市と姉妹都市を結んで３５周年ということで、大事な節目だと考えています。内容については、経費を抑えるべきと言いながら無理な要望かもしれませんが、友好がはぐくまれるよう充実をしていくべきものだと考えていますので、特段反対をするものではありません。ぜひお体に留意して、現地と交流を務めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問・要望","question":"おかしな話かなと思うのは、濱野区長は、品川区公式訪問団の一員として議長に同行いただきたい。今、現に区民生活や各産業の経営が本当に厳しい状況にある中で、おそらく議員が行くのでしょうけれども、議員特権と思われるような状況、対応を品川区議会としても私はするべきではないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"議長にお聞きしたいのですが、東京都への要望で、東京２０２０オリンピック・パラリンピック競技大会における観戦チケットに関する要望なのですが、これを今、これから出すということですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"出した。そうか、出してしまったのですね。あれは時期的にどうなのかなとちょっと思ったのですが、うまく組んでくれるとありがたいですね。意見だけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"今、議長がおっしゃったのですが、選挙の直近の前ではないですか。そうすると、じゃあ、言葉、各会派説明云々もありますけれども、かなりナーバスな時期だと思うのですけれども、それは大丈夫ですか。","respondent":"渡辺議長","answer":"先ほどのお願いのとおりです。議会側が配慮をして気をつけることとして、お願いいたします。","id":"exchange-012"},{"speaker":"須貝委員","kind":"意見","question":"議会運営委員会の委員長には本当に嫌な話だと思うのですけれども、議会運営委員会の役員数の数については、やはりきちんと私は何らかの指針を出すべきだと思うので、やはり明文化できるようなきちっとしたものを明記できるように、私は早くそういうのを議題として議会運営委員会の中で話し合ったほうがいいと思いますので、それをちょっと申し上げておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/268822?Template=document&Id=5322#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":17491,"voices":95}},{"id":"r01-20190701-6","meetingId":"r01-cm07","date":"2019年7月1日","dateIso":"2019-07-01","committee":"区民委員会","time":"午前１０時００分～午後 ０時０５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","topics":[{"id":"topic-01","title":"第４０号議案、品川区消費者センター条例の一部を改正する条例","agenda":"第４０号議案、品川区消費者センター条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"それからもう一つ、啓発展示室は移転するというご説明だったと思いますけれども、２つのものが１つになるというご説明でしたが、結局は廃止されると聞いているのですが、そこを今、利用なさっている方から私は伺ったのですけれども、３階にはもうなくなりますという雰囲気で掲示があったと思うのですが、その点、いかがでしょうか。その辺をお伺いしたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"こうしたところをうまく使い分ける形で、活動はしっかりやっていっていただけるだろうということで考えているところです。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"グループ室というのは、一般に貸し出している部屋ではないのですか。例えば、今まで啓発展示室を毎週使っていらした方がいらっしゃるわけです。その方たちは毎週、そこを非常に便利に使っていらした。その方たちが、全く同じようにそのグループ室を使えるようになるということですか。","respondent":"山崎商業・ものづくり課長","answer":"団体の方々にとりましては、いつ行ってもあいているスペースですので、そういう意味では団体の方の使い勝手は非常にいい状況ですが、広く公共施設の有効活用を考える上では、いろいろ今回、一元化というメリットを活かし。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"だから、団体の側にとっては、今はいつ行ってもあいているスペースということでおっしゃいましたけれども、団体側にとっては、いつ行ってもあいているスペースという形でグループ室を利用するわけにはいかなくなるというのは、そのとおりなのですか。","respondent":"山崎商業・ものづくり課長","answer":"こちらは通常の公共施設の利用と同様に考えておりまして、そこはしっかり調整ということで、いろいろ工夫をしながら、活動自体を阻害するような状況にはするつもりはございませんので、よろしくご理解賜りたいと考えているところです。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問・要望","question":"私が伺った団体の方からは、今までは常時、毎週使えていたのに、これからは抽選して、当たる当たらないを心配しながら使わなければいけなくなるので、それが非常に困ったことだと言っておられたので、それは困りましたねとお返事しておいたのですけれども、今回の単に住所を移すということだけでなくて、区の側からすれば、あるいは商業・ものづくり課の側からすれば。","respondent":"山崎商業・ものづくり課長","answer":"そういう意味では、そういった活動可能時間としてのメリットもありますので、団体の方々と十分コミュニケーションを図りながら、諸活動の活性化にも寄与する今回の移転ということで位置づけておりますので、委員のおっしゃられたことも含めまして。","id":"exchange-004"},{"speaker":"くにば委員","kind":"質問","question":"もう１点が、実際、新しく使うほうの施設跡の整備に関しての予算であるとか、幾らぐらい使う予定であるとか、そのようなことの見通し、おおむね予算規模はこちらの予算の内訳に書いてあることは、新しいところへの移転のための予算であって、施設跡を活用する、新たな施設の予算は書いていないような気がするのですけれども、そちらについてお伺いしたいです。","respondent":"山崎商業・ものづくり課長","answer":"いろいろ企画なり、区の調整部門では、公共施設の有効活用を図る観点で検討はなされているやに聞いておりますが、今、本委員会などでご説明する具体的な状況にはなっていないです。今回の予算につきましては、消費者センターそのものの移転の直接経費です。","id":"exchange-005"},{"speaker":"くにば委員","kind":"質問","question":"これは９月２４日より業務開始ということで、もう期限は迫っていると思うのですけれども、実際のところ、施設跡は先ほどおっしゃった形で、まだ決まっていない、これから話し合うということなのですけれども、具体的にどのような課でやるとか、どのようなチームで話し合いがなされるのか、最終的にこれに使おうということで、決める決定権はどなたにあるのか、それを伺いたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"一元化することで、消費者センターが商業・ものづくり課との連携強化、バリアフリーもあるのですけれども、これを一元化したことで、商業・ものづくり課があるところに来たことで、効果がありますという文章だと思うのですけれども、その効果がある具体的な、２,０００万円もかけてやる理由の中にあるわけですから、具体的にこうなっていくということがあると思うのですけれども、具体的に教えてください。","respondent":"山崎商業・ものづくり課長","answer":"まだ、例えば来年度打ち上げる新規事業などにそういった概念を入れられたらということで、あくまでも検討の段階ではありますけれども、一例を申し上げますと、例えば今、私ども本課で社会貢献製品の推進事業というのをやっています。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問・要望","question":"２,０００万円も使うのであるならば、例えばいろいろな議会の中で出てくるけれども、消費者センターに弁護士の方との連携とか、そういう質問も出てきたではないですか。お金をかけるなら、ソフトの面でもっと具体的に内容を重視してくれる、一般の消費者、区民を守っていただける方法を考えてほしいという思いがあるので、その辺について教えてください。","respondent":"山崎商業・ものづくり課長","answer":"先ほどの委員のご質問については、場所が移って何か新しいことにトライしないのか、そういう意味でないと効果がというふうに考えたものですから、プラスアルファの部分を１つご紹介しました。","id":"exchange-008"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"１点、考え方を確認させていただきたいのですけれども、一元化ということは理解できます。それで、より大井町の駅に近かった消費者センターを、一元化とはいえ、中小企業センターの中にというところが、いわゆる相談業務が主だと思うのです。区民の皆さんの利便性から考えると、なぜそこだったのかというところで、１点考え方を確認させてください。","respondent":"山崎商業・ものづくり課長","answer":"ただ、消費者センターのご相談のほぼ８割が電話相談にあるということと、それから、逆に言えば、区役所と中小企業センターと、駅から比べるとという意味もありますが、区役所から比較しますと、ほぼ同様の位置にあるということと、そういったことも考えまして、今の位置。","id":"exchange-009"},{"speaker":"こんの副委員長","kind":"確認","question":"先ほどほかの委員からの質問で、平米数の話が出たときに、倉庫を整理して、そこをというのは、きちんと整理したらできたのではないかという思いもあったものですから、考え方を確認しましたけれども、いわゆる展示室と相談業務のところが別というのは、それはやはり一元化のほうがいいだろうというところで、中小企業センターの中ということですが、いずれにしても、先ほど商品によっては事故なり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"木村委員","kind":"質問","question":"この理由の（３）の中に、バリアフリー化と書いてありました。これは物理的な何かのバリアということではないのですか。","respondent":"山崎商業・ものづくり課長","answer":"そういったことも踏まえて、建物全体につきましては、中小企業センターとしてのバリアフリーの取り組みの中で対応しつつ、消費者センターの入り口については自動ドア化を採用しようです。","id":"exchange-011"},{"speaker":"木村委員","kind":"意見","question":"これは引っ越しとか、いろいろと経費が２,０００万円を超える金額ですけれども、これを移転して一緒にすることによって、経費というものに対しては、いずれ費用を埋め合わせするぐらいの経費が削減できるのか、そういうことはありますか。","respondent":"山崎商業・ものづくり課長","answer":"そういう意味では、今後の消費者団体の諸活動の活性化、それから消費者センター機能自体の取り組みの高度化なども含めて、そうしたサービスアップをもって、この移転をよりよかったものに感じていただけるように頑張ってまいりたいと思うところです。","id":"exchange-012"},{"speaker":"おくの委員","kind":"意見","question":"先ほど述べたことですけれども、文言上は住所の変更ということですし、理由は一元化ということなのですけれども、その中身に、啓発展示室を廃止するという点で、その啓発展示室を廃止してほしくないという、啓発展示室の廃止が含まれているという点で、反対したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"}]},{"id":"topic-02","title":"第４１号議案、品川区立創業支援施設条例の一部を改正する条例","agenda":"第４１号議案、品川区立創業支援施設条例の一部を改正する条例","exchanges":[{"speaker":"湯澤委員","kind":"質問・要望","question":"募集方法で公募ということなのですけれども、公募というのはどのような方法で行っていき、どなたが選定をされていくのかというのが１つ。最後に、専任コンサルタントということなのですけれども、こちらはどういった形で選任をされて、また、この方たちというのは任期というか、そういったものというのが設定されているのか、それを教えていただけますでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"先ほど利用者のニーズということもありましたけれども、あの施設自体が、１０年前に創業支援センターとして設置をして、女性に限ったわけではありませんが、女性の起業に特化するようなメニューで特徴出しをしたということで、全国から注目を浴びて、狭いエリアですけれども。","id":"exchange-014"},{"speaker":"湯澤委員","kind":"質問・要望","question":"１,４００万円強かける事業でありますので、ぜひ多くの区民の皆様に使用していただきたいという中で、多くの方に利用していただくような設備を準備していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"おくの委員","kind":"質問","question":"これは使用可能人数が６人ということで、募集の定員が１０人ということで、今、ＳＨＩＰのところでやっていらっしゃるということなのですけれども、どの程度の利用状況なのでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"万が一、１０人が同時に使うという可能性もゼロではありませんので、そういった場合は、現在のそれ以外の階に、４階に例えば交流スペースがあったりとか、会議室があったりとか、それから、１階にはチャレンジショップのスペースがあって。","id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"改めてお伺いしますが、創業支援ですけれども、創業をしようと思っている方々にとっては、まず初めにメリットがあると思うのです。ですけれども、創業支援を、税金を使ってこれだけするということが、区にとって、および区民にとってはどういうメリットがあるのか、最初の一歩だと思うのですが、根本的なことを教えてください。","respondent":"山崎商業・ものづくり課長","answer":"基本的にはそういったことと、あと、創業といいますと、ベンチャー企業の創業などをイメージするケースが多いのですが、特に武蔵小山創業支援センターは、他にも品川区は創業支援センターを幾つか持っておりますけれども、より商業地である武蔵小山の特性を活かし。","id":"exchange-017"},{"speaker":"藤原委員","kind":"質問・要望","question":"ぜひ手厚く支援していただきたいと思うのですけれども、この６０１号室と６０２号室をコワーキングスペースにするということですが、こうしていこうと思った発想、変えていこうと思った発想は、どこから来ているのかということと、ＳＨＩＰはすごく稼働率がいいとお伺いして、高く評価しているのですけれども、あそこにもこういう形であります。","respondent":"山崎商業・ものづくり課長","answer":"コワーキングスペースは共有のスペースということで、特に女性の方などにつきましては、１人でビジネスプランを考え、いろいろな資金需要で銀行などとの資金の関係ですとか、そうした意味では、少しハードルが高いけれどもトライしたいということが多々あります。","id":"exchange-018"},{"speaker":"藤原委員","kind":"質問","question":"最後に、創業という意味で、人を育てるという意味で、専任コンサルタント２名で４６０万円の予算をとっているのですけれども、もし決まっていたら、どういう方を採用するのか、また、これは２名ですから、１人にすると約２３０万円なのですけれども、常勤とかではないのでしょうか。その辺について教えていただけますか。","respondent":"山崎商業・ものづくり課長","answer":"今回、コワーキング化を図ることによって、追加のコワーキングのインキュベーションマネジャーの費用ということで考えていますので、もちろん回しながら、常勤ということの体制はつくっていく予定です。","id":"exchange-019"},{"speaker":"松澤委員","kind":"意見","question":"話が戻ってしまうのですけれども、創業して１０年、でも９０％ぐらいにしか利用者数も減っていない。老朽化でもない。ＳＨＩＰという類似の施設がある。そのようになって、また１,５００万円かけてやる意義といいますか、意味といいますか、要は、現状で使用者が１割少なくなっているわけです。","respondent":"山崎商業・ものづくり課長","answer":"実は、武蔵小山創業支援センターは経緯がありまして、１つの機能強化の方向性という部分で、今回は今年度取り組む６階の一部スペースの改修ということで、いろいろ議論いただいているところではあります。","id":"exchange-020"},{"speaker":"松澤委員","kind":"質問","question":"委託というのはコワーキングスペースだけではなくて、施設の運営自体も全部委託ですか。","respondent":"山崎商業・ものづくり課長","answer":"一部、今のＳＨＩＰでインキュベーションマネジャーを配置しているのですけれども、それはプロポーザルなど公正な手続をもってやっていますが、そちらの支援員とも同じ会社だったりしますので、現在も、武蔵小山創業支援センターの事務室に入居している方は。","id":"exchange-021"},{"speaker":"くにば委員","kind":"質問・要望","question":"こちらは４階に既に無料の交流サロンというのがあると思うのですけれども、そちらの交流サロンにプラスアルファという形で拡充をするなりして、こちらの予算を大きくかけるのではなく、今回と同じような機能を追加ということはできなかったのかというのが１点。以上、そちらの点をお伺いしたいです。","respondent":"山崎商業・ものづくり課長","answer":"万が一、コワーキングスペースの利用者として、マナー以外に、目的以外に使用するような場合がありましたら、それは施設の目的から反するということで対応してまいりたいと考えているところです。","id":"exchange-022"},{"speaker":"くにば委員","kind":"質問","question":"後ろの３点はわかりました。もう一度、経費の備品の部分についてなのですけれども、今ご説明がありましたパネルというのがあると思うのですが、どうもそのパネルというのが、どれだけお金がかかるのかは不明なのですが、私の中で４００万円というのが、今のパネルというご説明があっても、まだどうしても内訳として多いのかなと思うのですけれども、こちらの内訳に関して、精査はなさいましたでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"それで、今、見積もりのレベルまでの資料がないものですから、スパッとお答えできないのが非常に申しわけないと思いますが、備品を購入する金額の積み上げのみではないものですので、よろしくご理解いただければと思います。","id":"exchange-023"}]},{"id":"topic-03","title":"第３６号議案、令和元年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第３６号議案、令和元年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"こちらの中で、寺ｃａｆｅの運営という部分を少し具体的にお伺いしたいというのが１つと、今回、実証実験ということで、来年度から本格的にこちらが運営できればということだと思うのですけれども、来年度以降に関しての予算の見込みであるとか、あとはその予算、財源をどこから引っ張ってくるのかとか、そういった見込みを教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"もう１点の実証実験としての財源ということですが、寄附者の意向といたしまして、東京２０２０大会に向けてという部分で、引き続き来年度もご寄附をいただけるようなお話にはなっておりますので、来年度についてはそのような予定で、今年度は実証実験としております。","id":"exchange-024"},{"speaker":"くにば委員","kind":"質問","question":"来年度も寄附していただける見込みということで、先方がそういうご意思は示していただいていると思うのですが、そちらに関して、まず確実性というか、具体的にそれを担保にして、それを当てにしてという言葉を使っていいのでしょうか、それでこちらの事業を進めていると思うのですが、何かしら先方と契約であるとか、何か確約をうまく文書で交わしているのかどうか、伺ってよろしいですか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"もしももらえなくなった場合というのは、またまちの方と協力して話をしながら、それは区の財源から補填をするのか、どこからか補助金を探してくるのか、はたまたスポンサーを探すのか、そこはいろいろな手法がありますので。","id":"exchange-025"},{"speaker":"おくの委員","kind":"質問・要望","question":"つい最近、二、三日前ですけれども、品川区内で個店を経営している方も、本当に引き上げをやめてほしいという、たまたまですけれども、私は商店主の方のお声を伺ってきたばかりですので、こういう臨時商品券の発売だけで、１月までの発売だけで消費税増税が正当化できるものではないと思うのです。その点、どのように考えておられるか、一言ご意見をお伺いしたいと考えています。","respondent":"山崎商業・ものづくり課長","answer":"消費税につきましては、国会の場でさまざま議論されて、決定に至っている経緯ですので、本委員会等でその件についてコメントということは、差し控えさせていただきたいと考えているところです。","id":"exchange-026"},{"speaker":"松澤委員","kind":"質問","question":"すみません、質問が合っているかわからないのですけれども、プレミアム付商品券が、前回お配りしたときに余ったとお聞きしたのです。完売せずに余って、その余った商品券を、また再度調整するわけではなく、一回買ってくれた方にもう一度販売したというお話を聞いたのですけれども、それは全くただのうわさであって、余ったという事実はないということですか。","respondent":"山崎商業・ものづくり課長","answer":"当選のはがきをお渡しして、ただ、引きかえが必ず１００％は買っていただけないものですから、２次販売まで実はやっています。１次で９０％さばけるのですけれども、２次で９７％ぐらいまでいきます。すると、３％はどうしても残るということになります。","id":"exchange-027"},{"speaker":"おくの委員","kind":"確認","question":"確認です。簡単なことですけれども、数字の確認で、お子さんが属する世帯の世帯主１万１,０００人というのは、延べとおっしゃられましたけれども、もし私に２人の子どもがいたら、私は２人と換算されているという理解でいいのですか。","respondent":"山崎商業・ものづくり課長","answer":"おっしゃるとおりです。","id":"exchange-028"},{"speaker":"湯澤委員","kind":"質問","question":"松澤委員の質問と重複してしまうかもしれないですけれども、「わ！しながわプレミアム付商品券」は、仮に応募者が少なくて余ってしまった場合には、どのような措置をとられるのでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"しながわプレミアム付商品券」につきましては、先ほどの非課税者あるいは子育て世帯という形で、まず購入をされる方がすごく限定をされていますので、その中で漏れなく購入の希望をとりまして、購入の希望がある方は。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"目的のところなのですけれども、消費税が１０％に引き上げられるから低所得者にという対策、子育て世帯にも対策をやりますという事業だと思いますが、まさに消費税は国が国会で決めることですけれども、地方行政としては、消費税が上がることは低所得者に打撃を与えるということは認めているということですか。","respondent":"山崎商業・ものづくり課長","answer":"消費税に関しましては、低所得者あるいは子育て世帯のみならず、日本の社会全部に影響がある話です。今回、臨時商品券事業については、国の議論の中で示されたフレームです。そうしたフレームで、自治体としてしっかり取り組ませていただくというところで考えているところです。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問・要望","question":"なぜ、あえてその質問をしたかというと、この委員会とは別かもしれない。改めて、私も消費税は、購入すれば全部にかかる、全国民にかかるというのはわかっておりますが、低所得者に来るという打撃を、担当の１つの課として、本当は全庁的にしていただきたいのですけれども、施策を新たにつくっていただきたいと思っているという意味において質問しているので、その辺について答弁していただけますか。","respondent":"山崎商業・ものづくり課長","answer":"全体の低所得者対策につきましては、産業部門以外の福祉部門なり、区全体の対応の流れの中で、区としてはしっかり対応していくということで考えるところです。","id":"exchange-031"},{"speaker":"藤原委員","kind":"確認","question":"数字の確認なのですけれども、１枚目のプリントでは区民税の非課税者が４万８,０００人になっています。２枚目のプリントで、購入引換券の非課税者で３万７,７９６人になっています。この差は、課税されている方が扶養に入っている方とか、生活保護、中国残留邦人などの支援給付を受給されている方を引いた数ということですか。","respondent":"山崎商業・ものづくり課長","answer":"そのスキームの中で、戻りが８割だったということがありまして、そういった推計がどうしても必要ですので、そうした数の違いです。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"プレミアム率を２０％つけて、区が施策を実施してくれるわけですので、その対象に入っている方がわかりやすく、買いやすく、プレミアムの金額が広くそういう方々に行くように、所管課としては、丁寧に易しくわかりやすく説明等をして、喜んでいただけるようにしていただきたいと思うのですけれども、その辺はいかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"そういう過程の中で、今、委員がご心配された説明不足であったり、行政側からのＰＲ不足に起因して、購入希望があったのにお買い求めできなかったという問題が出来しないよう、適正にしっかり対応してまいる所存です。","id":"exchange-033"},{"speaker":"こんの副委員長","kind":"質問","question":"今の藤原委員の質問に関連するのですけれども、「わ！１冊でも買えるようになっているのですか。要するに、買おうと思ったらもう売り切れてしまったということが心配なのですが、そこの見通しはどうなのでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"商連のほうは、予算額が決まっているものでということはありますけれども、そういった形でご理解をいただきたいのと、同時期に商連と区の商品券が区内にたくさん出回りますので、そういう意味では、その辺がこんがらがらないようなシームレスな。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/826260?Template=document&Id=2838#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":34533,"voices":121}}]);
